import {MarketChart} from '/terminal/chart.js';
import {escapeHtml as esc,localeFromPath,readIntent,internalPath,safeWebUrl,decimalText,moneyText,dataState,registrationAvailable} from './product-core.js';

let locale=localeFromPath(location.pathname),root,dialog,snapshot=null,session=null,catalog=null,portfolio=null,summary=null,portfolios=[],selectedInstrument=null,marketData=null,news=[],events=[],strategies=[],brokerStatus=null,view='holdings',terminalView='overview',chart=null,toastTimer,callback=null,operationBusy=false;
let intent=readIntent(location.search,locale),instrumentResults=[],selectedPortfolioId=null,authMode='login',newsSymbol='',resolution='5m',aiAnswer=null;
let terminalMode='provider',sampleState=null,watchlist=[],orderIntents=[];
let terminalReport=null,terminalReportLoading=false,terminalChartExpanded=false;
let lastDialogTrigger=null,terminalAuthOpen=false,terminalIntentPrepared=false;
let pollTimer=null,pollFailures=0;
let reminders=[],reminderTimer=null;
let surface='workspace',accountTab='account';
const chartViews=new Map(),chartIndicators={ema9:true,ema20:true,vwap:false};
let chartViewKey=null;
const terminalSelections={provider:null,sample:null};
const deliveredReminders=new Set();
const L=(en,nb)=>locale==='nb'?nb:en;
function syncPageLocale(){document.documentElement.lang=locale;const skip=document.querySelector('a.skip');if(skip)skip.textContent=L('Skip to workspace','Hopp til arbeidsområdet');}
const path=name=>`/${locale}/${name}/`;
const el=(selector,scope=document)=>scope.querySelector(selector);
const money=(value,currency='USD')=>moneyText(value,currency,locale);
const decimal=value=>decimalText(value,locale);
const requestId=()=>crypto.randomUUID();
const providerResolution=()=>({'1m':'1min','5m':'5min','15m':'15min','1h':'1h','1d':'1day'})[resolution]||'5min';
const button=(label,action,cls='',attrs='')=>`<button type="button" class="${cls}" data-product="${action}" ${attrs}>${label}</button>`;
const field=(label,name,value='',type='text',attrs='',help='')=>`<label class="p-field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${attrs}>${help?`<small>${help}</small>`:''}</label>`;
const password=(label,name='password',autocomplete='current-password')=>`<label class="p-field"><span>${label}</span><span class="p-password"><input name="${name}" type="password" autocomplete="${autocomplete}" minlength="12" maxlength="256" required><button type="button" data-product="show-password" aria-pressed="false">${L('Show','Vis')}</button></span></label>`;
const errorSlot=()=>'<p class="p-error" role="alert" data-error></p>';
const formActions=(label,extras='')=>`<div class="p-actions"><button type="submit" class="p-primary">${label}</button>${extras}</div>${errorSlot()}`;
const panel=(title,body,action='')=>`<section class="p-panel"><div class="p-panel-head"><h2>${title}</h2>${action}</div><div class="p-panel-body">${body}</div></section>`;
const rawStateName=key=>({upgrade:L('Upgrade required','Oppgradering kreves'),unavailable:L('Service unavailable','Tjenesten er utilgjengelig'),connect:L('Connect your broker','Koble til megleren'),stale:L('Stale data','Utdaterte data'),closed:L('Market closed','Markedet er stengt'),delayed:L('Delayed data','Forsinkede data'),unverified:L('Connection not verified','Tilkobling ikke bekreftet'),current:L('Current','Oppdatert')})[key]||key;
const stateLabel=key=>({pending:L('Pending','Venter'),submitting:L('Submitting','Sender'),unknown:L('Outcome unknown','Ukjent utfall'),manual_review:L('Needs review','Må gjennomgås'),new:L('Accepted','Godkjent'),accepted:L('Accepted','Godkjent'),partially_filled:L('Partially filled','Delvis utført'),filled:L('Filled','Utført'),rejected:L('Rejected','Avvist'),pending_cancel:L('Cancellation pending','Kansellering venter'),canceled:L('Cancelled','Kansellert'),cancelled:L('Cancelled','Kansellert'),expired:L('Expired','Utløpt'),replaced:L('Replaced','Erstattet'),connected:L('Connected','Tilkoblet'),disconnected:L('Disconnected','Frakoblet'),authorization_required:L('Authorization required','Godkjenning kreves'),manual:L('Manual valuation','Manuell verdi'),scheduled:L('Scheduled','Planlagt'),payment_pending:L('Payment pending','Betaling venter'),current:L('Current','Oppdatert'),delayed:L('Delayed','Forsinket'),stale:L('Stale','Utdatert'),market_closed:L('Market closed','Markedet er stengt'),unavailable:L('Unavailable','Utilgjengelig')})[key]||key;
const date=value=>{try{return value?new Intl.DateTimeFormat(locale==='nb'?'nb-NO':'en-GB',{dateStyle:'medium',timeStyle:'short',timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone}).format(new Date(typeof value==='number'&&value<1e12?value*1000:value)):'—';}catch{return '—';}};
const has=feature=>(snapshot?.entitlements?.features||[]).includes(feature);
const paid=()=>['portfolio','pro'].includes(snapshot?.entitlements?.tier);
const pro=()=>snapshot?.entitlements?.tier==='pro';
const user=()=>snapshot?.user?.kind!=='guest'&&snapshot?.user?snapshot.user:((session?.user?.kind==='user')?session.user:null);
const ready=(tier=intent.tier)=>catalog?.availability?.[tier]?catalog.availability[tier].ready===true:(snapshot?.billing?.ready===true||catalog?.ready===true||catalog?.billingReady===true);
const canRegister=()=>registrationAvailable(catalog,snapshot);
const planName=tier=>tier==='pro'?'Nortivo Terminal Pro':'Nortivo Portfolio';
const total=(tier,interval)=>({portfolio:{month:10,year:96},pro:{month:30,year:288}})[tier]?.[interval]??10;
const securityInput=data=>{const next={...data};if(next.code&&!/^\d{6}$/.test(next.code)){next.recoveryCode=next.code;delete next.code;}return next;};
function currencyMap(value){return value&&typeof value==='object'?Object.entries(value).map(([currency,amount])=>money(amount,currency)).join(' · ')||'—':'—';}
function fxDisclosure(){return `<p class="p-inline-note">${L('Cost basis and unrealized gain in the display currency use current disclosed FX, not historical currency performance.','Kostpris og urealisert gevinst i visningsvalutaen bruker oppgitt gjeldende valutakurs, ikke historisk valutaavkastning.')}</p>${(summary?.conversions||[]).length?`<ul class="p-list">${summary.conversions.map(rate=>`<li><span class="p-mono">${esc(rate.pair)} · ${decimal(rate.rate)}</span><span class="p-meta">${esc(rate.source||'—')} · ${date(rate.asOf)}</span></li>`).join('')}</ul>`:''}`;}
function displayTransactions(){const map=new Map((portfolio?.transactions||[]).map(transaction=>[transaction.id,{...transaction}]));for(const amendment of portfolio?.amendments||[]){const original=map.get(amendment.transactionId);if(!original)continue;map.set(amendment.transactionId,amendment.type==='void'?{...original,voided:true}:{...amendment.replacement,corrected:true});}return [...map.values()];}
function watchlistFromIds(ids){return ids.filter(id=>/^(XNAS|XNYS|ARCX|BATS):[A-Z][A-Z0-9.-]*:USD$/.test(id)).map(id=>{const known=[...instrumentResults,...watchlist].find(item=>item.id===id),[venue,symbol,currency]=id.split(':');return known||{id,symbol,venue,currency,name:symbol,assetType:''};});}
async function loadWatchlist(){const data=await api('product-watchlist');watchlist=data.instruments||watchlistFromIds(data.instrumentIds||[]);}
async function loadReminders(){try{const data=await api('product-reminders');reminders=data.reminders||[];}catch{reminders=[];}}
function reminderControls(item){return `<div class="p-actions">${button(L('Remind in this app · 5 min before','Her i appen · 5 min før'),'add-reminder','',`data-id="${esc(item.id)}"`)}</div>`;}
function remindersPanel(){return `<section class="p-panel-body"><h3>${L('In-app reminders','Påminnelser i appen')}</h3><p class="p-meta">${L('This tab must be open. No email, push or background delivery is enabled. Provider revisions update the saved event time when the calendar refreshes.','Denne fanen må være åpen. Ingen e-post-, push- eller bakgrunnsvarsling er aktivert. Leverandørens revisjoner oppdaterer lagret hendelsestid ved kalenderoppdatering.')}</p><ul class="p-list">${reminders.map(item=>`<li><strong>${esc(item.title)}</strong><span class="p-meta">${date(item.remindAt)} · ${L('event','hendelse')}: ${date(item.eventTime)}</span>${button(L('Remove reminder','Fjern påminnelse'),'remove-reminder','',`data-id="${esc(item.eventId)}"`)}</li>`).join('')||`<li class="p-meta">${L('No reminders saved.','Ingen påminnelser lagret.')}</li>`}</ul></section>`;}
function startReminderChecks(){if(reminderTimer)return;reminderTimer=setInterval(()=>{if(document.hidden)return;for(const reminder of reminders){const key=`${reminder.eventId}:${reminder.remindAt}`,at=typeof reminder.remindAt==='number'?reminder.remindAt:Date.parse(reminder.remindAt),eventAt=typeof reminder.eventTime==='number'?reminder.eventTime:Date.parse(reminder.eventTime);if(Number.isFinite(at)&&at<=Date.now()&&eventAt>=Date.now()-60000&&!deliveredReminders.has(key)){deliveredReminders.add(key);notify(L('Event reminder: ','Hendelsespåminnelse: ')+reminder.title+' · '+date(reminder.eventTime));}}},15000);window.addEventListener('pagehide',()=>clearInterval(reminderTimer),{once:true});}
function portfolioWatchlistPanel(){return panel(L('Watchlist','Overvåkingsliste'),`<details><summary>${L('Search and manage instruments','Søk og administrer instrumenter')}</summary><form id="terminal-search-form" class="p-form"><label class="p-field"><span>${L('Exact symbol or company','Nøyaktig symbol eller selskap')}</span><input id="terminal-instrument-query" type="search" autocomplete="off"></label><button type="submit">${L('Search','Søk')}</button><div id="terminal-instrument-results" aria-live="polite"></div></form></details>${selectedInstrument?`<p class="p-source">${L('Selected','Valgt')}: ${esc(selectedInstrument.symbol)} · ${esc(selectedInstrument.venue)}</p>${button(L('Add selected instrument','Legg til valgt instrument'),'watchlist-add','',!paid()?'disabled':'')}`:''}<ul class="p-list">${watchlist.slice(0,8).map(item=>`<li><div class="p-actions">${button(esc(item.symbol),'holding-context','',`data-instrument="${esc(item.id)}"`)}${button(L('Remove','Fjern'),'watchlist-remove','',`data-instrument="${esc(item.id)}" ${!paid()?'disabled':''}`)}</div><span class="p-meta">${esc(item.venue)} · ${esc(item.currency)}</span></li>`).join('')}</ul>`);}
function status(kind,included=true){const state=dataState(snapshot?.readiness?.[kind],included);return `<span class="p-status" data-state="${state}">${rawStateName(state)}</span>`;}
function unavailable(kind,included=true){const state=dataState(snapshot?.readiness?.[kind],included),copy={upgrade:L('Available with Terminal Pro.','Tilgjengelig med Terminal Pro.'),connect:L('Connect this service to see your data here.','Koble til tjenesten for å se dataene dine her.'),unverified:L('This connection has not been checked yet.','Denne tilkoblingen er ikke kontrollert ennå.'),stale:L('The latest update is overdue. Previously received data keeps its original timestamp.','Siste oppdatering er forsinket. Tidligere mottatte data beholder sitt opprinnelige tidspunkt.'),unavailable:L('This service is currently unavailable. Check connections for details.','Tjenesten er utilgjengelig for øyeblikket. Se tilkoblingene for detaljer.')};return `<div class="pt-empty"><p>${copy[state]||L('No data is available for this view yet.','Det finnes ingen data for denne visningen ennå.')}</p>${button(state==='upgrade'?L('Compare plans','Sammenlign abonnementer'):L('View connections','Se tilkoblinger'),state==='upgrade'?'pricing':'integration-status')}</div>`;}
function errorText(error){const map={AUTH_REQUIRED:L('Your session ended. Sign in again; your saved records remain available.','Økten er avsluttet. Logg inn igjen; lagrede registreringer er beholdt.'),LOGIN_FAILED:L('The email or password was not accepted. Try again.','E-postadressen eller passordet ble ikke godtatt. Prøv igjen.'),INVALID_CREDENTIALS:L('Enter a valid email and a password with at least 12 characters.','Skriv inn en gyldig e-postadresse og et passord med minst 12 tegn.'),EMAIL_NOT_VERIFIED:L('Verify your email before continuing. You can request a new link below.','Bekreft e-postadressen før du fortsetter. Du kan be om en ny lenke nedenfor.'),PLAN_REQUIRED:L('Choose a plan to use this feature. Your existing records remain available.','Velg et abonnement for å bruke funksjonen. Eksisterende registreringer er beholdt.'),UPGRADE_REQUIRED:L('This feature requires Terminal Pro.','Denne funksjonen krever Terminal Pro.'),PROVIDER_UNAVAILABLE:L('The provider could not be reached. Your draft is retained; try again later.','Leverandøren kunne ikke nås. Utkastet er beholdt; prøv igjen senere.'),PROVIDER_NOT_CONFIGURED:L('This service is awaiting provider configuration and permissions.','Tjenesten venter på leverandøroppsett og tillatelser.'),BILLING_NOT_READY:L('Subscriptions are not open yet. Required provider connections and permissions must be verified first.','Abonnementene er ikke åpnet ennå. Nødvendige leverandørtilkoblinger og tillatelser må bekreftes først.'),CSRF_FAILED:L('Your session changed. Refresh the page, then retry.','Økten er endret. Oppdater siden og prøv igjen.'),RATE_LIMITED:L('Too many requests. Wait a moment and retry.','For mange forespørsler. Vent litt og prøv igjen.'),AI_QUOTA_EXCEEDED:L('Your AI allowance is used up. See the reset time in the allowance panel.','KI-kvoten er brukt opp. Se tidspunktet for nullstilling i kvotepanelet.'),MFA_REQUIRED:L('Confirm with your authenticator before continuing.','Bekreft med autentiseringsappen før du fortsetter.'),TOKEN_INVALID:L('This link has expired or has already been used. Request a new link.','Lenken er utløpt eller allerede brukt. Be om en ny lenke.'),INVALID_TOKEN:L('This link has expired or has already been used. Request a new link.','Lenken er utløpt eller allerede brukt. Be om en ny lenke.'),NETWORK_ERROR:L('Connection lost. Your draft is still here; reconnect and retry.','Tilkoblingen ble brutt. Utkastet er beholdt; koble til og prøv igjen.'),CONFLICT:L('Another tab changed this record. Refresh before editing it again.','En annen fane endret registreringen. Oppdater før du redigerer igjen.')};return map[error.code]||(locale==='en'?error.message:L('The request could not be completed. Check your fields and retry.','Forespørselen kunne ikke fullføres. Kontroller feltene og prøv igjen.'))+(error.code?` (${error.code})`:'');}
async function api(action,{method='GET',body,params={}}={}){const url=new URL('/.netlify/functions/terminal',location.origin);url.searchParams.set('action',action);Object.entries(params).forEach(([key,value])=>{if(value!==undefined&&value!==null&&value!=='')url.searchParams.set(key,value);});let response;try{response=await fetch(url,{method,credentials:'same-origin',headers:{...(body?{'Content-Type':'application/json'}:{}),...((snapshot?.csrfToken||session?.csrfToken)?{'X-CSRF-Token':snapshot?.csrfToken||session.csrfToken}:{})},...(body?{body:JSON.stringify(body)}:{})});}catch{throw{code:'NETWORK_ERROR'};}const data=await response.json().catch(()=>({}));if(!response.ok)throw{status:response.status,...(data.error||{code:'REQUEST_FAILED',message:L('The server could not complete this request.','Serveren kunne ikke fullføre forespørselen.')})};return data;}
async function post(action,body={}){return api(action,{method:'POST',body:{requestId:requestId(),...body}});}
function notify(message){if(terminalAuthOpen&&dialog?.open){let feedback=el('.pt-auth-feedback',dialog);if(!feedback){feedback=document.createElement('p');feedback.className='pt-auth-feedback';feedback.setAttribute('role','status');feedback.setAttribute('aria-live','polite');el('.pt-auth-content',dialog)?.prepend(feedback);}feedback.textContent=message;return;}const node=el('#product-toast');if(!node)return;node.textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.textContent='',6500);}
function hrefIntent(name='portfolio',mode='signup',chosen=intent){const query=new URLSearchParams({...chosen,auth:mode});return path(name)+'?'+query;}
function shell(content,active='portfolio'){syncPageLocale();root.innerHTML=`<header class="p-header"><a class="p-brand brand" href="/${locale}/" aria-label="Nortivo ${L('home','forside')}">NORTIVO</a>${productSwitcher(active)}<nav class="p-nav" aria-label="${L('Account navigation','Kontonavigasjon')}"><a href="${path('pricing')}" ${active==='pricing'?'aria-current="page"':''}>${L('Plans','Abonnementer')}</a><a href="/${locale}/support/">${L('Support','Kundestøtte')}</a></nav><div class="p-header-actions">${button(locale==='nb'?'EN':'NO','language','p-language',`aria-label="${L('Switch to Norwegian','Bytt til engelsk')}"`)}${button(user()?L('Account','Konto'):L('Log in','Logg inn'),user()?'account':'login')}</div></header>${content}<div id="product-toast" class="p-toast" role="status" aria-live="polite"></div>`;}
function footer(){return `<footer class="p-footer"><span>${L('Subscription charges in USD. Portfolio display currency is a separate setting.','Abonnement belastes i USD. Porteføljens visningsvaluta er en separat innstilling.')}</span><div class="p-actions"><a href="/${locale}/privacy/">${L('Privacy','Personvern')}</a><a href="/${locale}/support/">${L('Support','Kundestøtte')}</a></div></footer>`;}
function showDialog(title,body){destroyChart();if(!dialog.open)lastDialogTrigger=document.activeElement;dialog.innerHTML=`<div class="p-panel-head"><h2 id="product-dialog-title" tabindex="-1">${title}</h2>${button(L('Close','Lukk'),'close-dialog','p-dialog-close')}</div><div class="p-panel-body">${body}</div>`;dialog.setAttribute('aria-labelledby','product-dialog-title');if(!dialog.open)dialog.showModal();el('#product-dialog-title',dialog).focus();}
function closeDialog(){if(terminalAuthOpen){terminalAuthOpen=false;surface='workspace';dialog.classList.remove('pt-terminal-auth');}dialog.close();dialog.innerHTML='';if(lastDialogTrigger?.isConnected)lastDialogTrigger.focus();if(isTerminal())mountChart();}
function isTerminal(){return /\/terminal\//.test(location.pathname);}
function bindForm(selector,handler,{scope=document,success=null}={}){const form=el(selector,scope);if(!form)return;form.addEventListener('submit',async event=>{event.preventDefault();if(form.dataset.busy==='true')return;form.dataset.busy='true';const submit=form.querySelector('[type=submit]'),label=submit?.textContent;if(submit){submit.disabled=true;submit.textContent=L('Saving…','Lagrer…');}const error=el('[data-error]',form);if(error)error.textContent='';try{const data=Object.fromEntries(new FormData(form));await handler(data,form);if(success)notify(success);}catch(e){if(error)error.textContent=errorText(e);else notify(errorText(e));}finally{form.dataset.busy='false';if(submit?.isConnected){submit.disabled=false;submit.textContent=label;}}});}
async function refreshSnapshot(){snapshot=await api('product');if(snapshot.selectedPlan)intent={...intent,...snapshot.selectedPlan};return snapshot;}
function selectedIntentNotice(){if(callback&&!user())return `<div class="p-intent p-meta">${L('Your saved plan will be restored after this personal link is confirmed. Confirming the link does not start a subscription.','Det lagrede abonnementet hentes etter at den personlige lenken er bekreftet. Bekreftelsen starter ikke et abonnement.')}</div>`;return `<div class="p-intent p-meta"><strong>${planName(intent.tier)}</strong> · ${intent.interval==='year'?L(`USD ${total(intent.tier,'year')} billed annually. No free trial.`,`USD ${total(intent.tier,'year')} belastes årlig. Ingen gratis prøveperiode.`):L(`USD ${total(intent.tier,'month')} per month. No free trial.`,`USD ${total(intent.tier,'month')} per måned. Ingen gratis prøveperiode.`)}<br><a href="${path('pricing')}?interval=${intent.interval}">${L('Compare plans','Sammenlign abonnementene')}</a></div>`;}
function authScreen(mode='login'){surface='auth';authMode=mode;const reset=mode==='reset',forgot=mode==='forgot',signup=mode==='signup',verify=mode==='verify';const terminalModal=isTerminal()&&!reset&&!verify;const title=reset?L('Choose a new password','Velg et nytt passord'):forgot?L('Reset your password','Tilbakestill passordet'):verify?L('Confirm your email','Bekreft e-postadressen'):signup?L('Create your Nortivo account','Opprett Nortivo-kontoen din'):L('Welcome back','Velkommen tilbake');const authBody=`<p class="p-muted">${verify?L('Confirm this one-time link to verify the address. It will never start a subscription or trading.','Bekreft engangslenken for å bekrefte adressen. Dette starter aldri et abonnement eller handel.'):forgot?L('We will send a recovery link if this address has an account.','Vi sender en gjenopprettingslenke hvis adressen har en konto.'):reset?L('Use at least 12 characters. All other sessions are revoked when your password changes.','Bruk minst 12 tegn. Andre økter avsluttes når passordet endres.'):L('Registration is free. A subscription starts after payment completes.','Registrering er gratis. Et abonnement starter når betalingen er fullført.')}</p>${!reset&&!forgot&&!verify?`<div class="p-auth-tabs">${button(L('Sign in','Logg inn'),'login','',`aria-pressed="${!signup}"`)}${button(canRegister()?L('Create account','Opprett konto'):L('Registration unavailable','Registrering utilgjengelig'),'signup','',`aria-pressed="${signup}" ${!canRegister()?'disabled':''}`)}</div>`:''}<form id="product-auth-form" class="p-form">${signup?field(L('Name (optional)','Navn (valgfritt)'),'name','','text','autocomplete="name" maxlength="80"'):''}${!reset&&!verify?field(L('Email','E-post'),'email',user()?.email||'','email','autocomplete="email" maxlength="160" required'):''}${!forgot&&!verify?password(reset?L('New password','Nytt passord'):L('Password','Passord'),'password',signup||reset?'new-password':'current-password'):''}${!signup&&!reset&&!forgot&&!verify?field(L('Authenticator or recovery code (if enabled)','Autentiseringskode eller gjenopprettingskode (hvis aktivert)'),'code','','text','autocomplete="one-time-code" maxlength="40"'):''}${formActions(verify?L('Verify email','Bekreft e-post'):reset?L('Save new password','Lagre nytt passord'):forgot?L('Send recovery link','Send gjenopprettingslenke'):signup?L('Create free account','Opprett gratis konto'):L('Sign in','Logg inn'))}</form>${!verify?`<div class="p-actions">${button(forgot||reset?L('Back to sign in','Tilbake til innlogging'):L('Forgot password?','Glemt passord?'),forgot||reset?'login':'forgot')}${button(L('View plans','Se abonnementer'),'pricing')}</div>`:''}${selectedIntentNotice()}`;if(terminalModal){if(!root.querySelector('.pt-terminal-shell'))renderTerminal();surface='auth';terminalAuthOpen=true;dialog.classList.add('pt-terminal-auth');showDialog(title,`<div class="pt-auth-content">${authBody}</div>`);}else shell(`<main class="p-shell" id="workspace" tabindex="-1"><section class="p-auth p-panel"><div class="p-panel-body"><h1>${title}</h1>${authBody}</div></section>${footer()}</main>`,isTerminal()?'terminal':'portfolio');bindForm('#product-auth-form',async data=>{if(verify){const confirmed=await post('product-verify',{token:callback?.token});callback=null;if(confirmed.selectedPlan)intent={...intent,...confirmed.selectedPlan};if(confirmed.returnPath){intent.returnPath=internalPath(confirmed.returnPath,intent.returnPath);terminalIntentPrepared=true;}if(user()){await refreshSnapshot();await continueIntent();}else{authScreen('login');notify(L('Email verified. Sign in to continue with your saved plan.','E-posten er bekreftet. Logg inn for å fortsette med det lagrede abonnementet.'));}return;}if(reset){await post('product-reset',{token:callback?.token,password:data.password});callback=null;session=null;snapshot=null;authScreen('login');notify(L('Password updated. Sign in with your new password.','Passordet er oppdatert. Logg inn med det nye passordet.'));return;}if(forgot){await post('product-forgot',{email:data.email,locale});el('#product-auth-form').innerHTML=`<div class="p-notice" role="status">${L('If an account exists, its recovery email has been requested. Check your inbox and spam folder.','Hvis kontoen finnes, er gjenopprettingspost bestilt. Se i innboksen og søppelpostmappen.')}</div>`;return;}if(signup&&!canRegister())throw{code:'EMAIL_NOT_CONFIGURED',message:L('Registration opens when verification email is configured. You can sign in to an existing account.','Registrering åpner når bekreftelsespost er konfigurert. Du kan logge inn på en eksisterende konto.')};const explicitPlan=new URLSearchParams(location.search).has('tier');const result=await post(signup?'signup':'login',{...securityInput(data),...(signup||explicitPlan?intent:{})});if(signup){authScreen('login');notify(L('If registration can be completed, check your inbox for verification. Then sign in to continue.','Hvis registreringen kan fullføres, får du en bekreftelseslenke på e-post. Logg deretter inn for å fortsette.'));return;}session=result;await refreshSnapshot();intent.returnPath=(terminalModal?intent.returnPath:(snapshot.onboarding?.returnPath||intent.returnPath)).replace(/^\/(en|nb)\//,`/${locale}/`);intent.locale=locale;if(snapshot.selectedPlan)await post('product-select-plan',intent);if(terminalModal&&dialog.open)closeDialog();if(!user()?.emailVerified)verificationScreen();else await continueIntent();});if(terminalModal)el('#product-auth-form [name=email]',dialog)?.focus();}
function verificationScreen(){surface='verification';shell(`<main class="p-shell" id="workspace" tabindex="-1"><section class="p-auth p-panel"><div class="p-panel-body"><h1>${L('Check your email','Sjekk e-posten din')}</h1><p class="p-muted">${L('Use the verification link sent to','Bruk bekreftelseslenken sendt til')} <strong>${esc(user()?.email||'')}</strong>. ${L('Your plan and language choice are saved.','Abonnementet og språkvalget er lagret.')}</p><div class="p-actions">${button(L('I have verified my email','Jeg har bekreftet e-posten'),'check-verified','p-primary')}${button(L('Resend email','Send e-post på nytt'),'resend')}</div><p class="p-error" data-account-error role="alert"></p>${selectedIntentNotice()}</div></section>${footer()}</main>`);}
async function continueIntent(){if(!user()){authScreen('login');return;}if(!user().emailVerified){verificationScreen();return;}if(paid()){location.assign(internalPath(intent.returnPath,path(pro()?'terminal':'portfolio')));return;}renderWorkspace();}
const planFeatures=tier=>tier==='portfolio'?[L('Manual holdings, lots and transaction ledger','Manuelle beholdninger, kjøpsposter og transaksjonshistorikk'),L('Cost basis, allocation and cash by currency','Kostpris, fordeling og kontanter per valuta'),L('Current valuations when licensed coverage is available','Oppdaterte verdier når lisensiert dekning er tilgjengelig'),L('Relevant news, events and basic AI explanations','Relevante nyheter, hendelser og enkle KI-forklaringer')]:[L('Everything in Portfolio','Alt i Portfolio'),L('Advanced analysis, sourced AI and larger allowance','Avansert analyse, kildebasert KI og større kvote'),L('Supported strategies, backtests and scans','Støttede strategier, simuleringer og skanninger'),L('Separate broker connection and automation consent','Separat meglertilkobling og samtykke til automatisering')];
function renderPricing(){surface='pricing';root.classList.add('p-price-page');const year=intent.interval==='year';const rows=[[L('Manual holdings and transactions','Manuelle beholdninger og transaksjoner'),L('Included','Inkludert'),L('Included','Inkludert')],[L('Allocation, cost basis and cash','Fordeling, kostpris og kontanter'),L('Core tools','Grunnverktøy'),L('Core + advanced analysis','Grunnverktøy + avansert analyse')],[L('News and economic calendar','Nyheter og økonomisk kalender'),L('Portfolio context','Porteføljekontekst'),L('Full views and filters','Full visning og filtre')],[L('AI assistance','KI-assistanse'),L('Basic, on demand','Enkel, på forespørsel'),L('Advanced, higher allowance','Avansert, større kvote')],[L('Strategies, scans and backtests','Strategier, skanninger og simuleringer'),'—',L('Where supported and verified','Der det er støttet og bekreftet')],[L('Broker sync and order tools','Meglersynkronisering og ordreverktøy'),'—',L('Supported accounts only','Kun støttede kontoer')],[L('Durable automation','Varig automatisering'),'—',L('Separate enablement and risk limits','Separat aktivering og risikogrenser')]];shell(`<main class="p-shell" id="workspace" tabindex="-1"><div class="p-price-heading"><div><h1>${L('Your portfolio. Your next decision.','Din portefølje. Din neste beslutning.')}</h1><p>${L('Start with a clear view of what you own. Choose Terminal Pro when you need deeper research and supported trading tools.','Start med oversikt over det du eier. Velg Terminal Pro når du trenger grundigere analyse og støttede handelsverktøy.')}</p></div></div><div class="p-billing-toggle" role="group" aria-label="${L('Billing interval','Betalingsintervall')}">${button(L('Monthly','Månedlig'),'interval','',`data-value="month" aria-pressed="${!year}"`)}${button(L('Annually','Årlig'),'interval','',`data-value="year" aria-pressed="${year}"`)}<span class="p-saving">${L('Save 20% annually','Spar 20 % årlig')}</span></div>${!ready()?`<div class="p-banner" data-kind="warning"><p><strong>${L('Subscriptions are not open yet.','Abonnementene er ikke åpnet ennå.')}</strong><br>${L('Required commercial data, news, calendar and payment connections must be verified before purchases open.','Nødvendige tilkoblinger for kommersielle markedsdata, nyheter, kalender og betaling må bekreftes før kjøp åpnes.')} ${canRegister()?L('Free account registration is available.','Gratis kontoregistrering er tilgjengelig.'):L('Registration opens when verification email is configured.','Registrering åpner når bekreftelsespost er konfigurert.')}</p></div>`:''}<div class="p-plan-grid">${['portfolio','pro'].map(tier=>`<section class="p-plan"><h2>${planName(tier)}</h2><p>${tier==='portfolio'?L('A dedicated home for the investments you enter and manage yourself.','Et eget sted for investeringene du registrerer og følger opp selv.'):L('The full trading workspace, with research, risk and execution in context.','Hele handelsarbeidsområdet, med analyse, risiko og utførelse i sammenheng.')}</p><div class="p-plan-price">$${year?(tier==='portfolio'?8:24):total(tier,'month')}<small> / ${L('month','måned')}${year?' '+L('equivalent','tilsvarende'):''}</small></div><div class="p-plan-total">${year?L(`USD ${total(tier,'year')} billed upfront annually`,`USD ${total(tier,'year')} belastes på forskudd årlig`):L(`USD ${total(tier,'month')} billed monthly`,`USD ${total(tier,'month')} belastes månedlig`)}</div><p class="p-meta">${year?L(`Save USD ${tier==='portfolio'?24:72} per year (20%).`,`Spar USD ${tier==='portfolio'?24:72} per år (20 %).`):L('Switch to annual billing to save 20%.','Velg årlig betaling for å spare 20 %.')} ${L('No free trial.','Ingen gratis prøveperiode.')}</p>${button(ready(tier)?L('Choose','Velg')+' '+planName(tier):canRegister()?L('Create free account','Opprett gratis konto'):L('Sign in to existing account','Logg inn på eksisterende konto'),'choose-plan','p-primary',`data-tier="${tier}"`)}<ul>${planFeatures(tier).map(item=>`<li>${item}</li>`).join('')}</ul></section>`).join('')}</div><p class="p-meta">${L('All subscription prices are USD. Applicable taxes are shown at hosted checkout. Separate broker and exchange charges may apply. Availability depends on licensed coverage, provider status and eligible connected accounts.','Alle abonnementspriser er i USD. Gjeldende avgifter vises i den sikre betalingsløsningen. Separate megler- og børsavgifter kan forekomme. Tilgjengelighet avhenger av lisensiert dekning, leverandørstatus og kvalifiserte tilkoblede kontoer.')}</p><section class="p-compare"><h2>${L('Compare the workspaces','Sammenlign arbeidsområdene')}</h2><div class="p-table-wrap" role="region" tabindex="0" aria-label="${L('Scrollable data table','Rullbar datatabell')}"><table><thead><tr><th scope="col">${L('Capability','Funksjon')}</th><th scope="col">Portfolio</th><th scope="col">Terminal Pro</th></tr></thead><tbody>${rows.map(row=>`<tr>${row.map((value,index)=>index?`<td>${value}</td>`:`<th scope="row">${value}</th>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="p-price-faq"><div><h2>${L('Same plan, either interval','Samme abonnement, begge intervaller')}</h2><p>${L('Monthly and annual customers in the same tier receive the same features. Annual prices already include the 20% saving; there is no additional coupon.','Månedlige og årlige kunder på samme nivå får de samme funksjonene. Årsprisene inkluderer allerede 20 % besparelse; det er ingen ekstra rabattkode.')}</p></div><div><h2>${L('Trading needs your permission','Handel trenger din tillatelse')}</h2><p>${L('Buying Pro or connecting a broker never starts trading. Live orders require a supported, authorized account and separate confirmation. Automation has its own consent and risk limits.','Kjøp av Pro eller tilkobling av megler starter aldri handel. Ordrer med ekte penger krever en støttet, godkjent konto og separat bekreftelse. Automatisering har eget samtykke og egne risikogrenser.')}</p></div></section>${footer()}</main>`,'pricing');}

async function loadPortfolio(id=selectedPortfolioId){const result=await api('product-portfolio',{params:id?{portfolioId:id}:{}});if(id){portfolio=result.portfolio;summary=result.summary;selectedPortfolioId=portfolio?.id||id;}else{portfolios=result.portfolios||[];if(portfolios.length){selectedPortfolioId=portfolios[0].id;return loadPortfolio(selectedPortfolioId);}portfolio=null;summary=null;}return result;}
function subscriptionNotice(){const bill=snapshot?.billing||{};if(!user())return '';if(!user().emailVerified)return `<div class="p-banner" data-kind="warning"><p>${L('Verify your email to save private records and choose a subscription.','Bekreft e-posten for å lagre private registreringer og velge et abonnement.')}</p>${button(L('Verify email','Bekreft e-post'),'verification')}</div>`;if(['pending','incomplete','payment_pending','processing'].includes(bill.status)||new URLSearchParams(location.search).get('billing')==='pending')return `<div class="p-banner" data-kind="warning"><p><strong>${L('Confirming your payment','Bekrefter betalingen din')}</strong><br>${L('Your access updates automatically when payment completes.','Tilgangen din oppdateres automatisk når betalingen er fullført.')}</p>${button(L('Check payment','Kontroller betaling'),'refresh-billing')}</div>`;if(!paid())return `<div class="p-banner"><p><strong>${L('Your saved records remain available','De lagrede registreringene er beholdt')}</strong><br>${ready()?L('A subscription lets you add records and use the included tools.','Et abonnement lar deg legge til registreringer og bruke de inkluderte verktøyene.'):L('Subscriptions are not open yet. Your account and existing records remain available.','Abonnementene er ikke åpnet ennå. Kontoen og eksisterende registreringer er tilgjengelige.')}</p>${button(L('Plans & billing','Abonnement og betaling'),'billing')}</div>`;if(bill.cancelAtPeriodEnd||bill.changePending)return `<div class="p-banner" data-kind="warning"><p>${bill.cancelAtPeriodEnd?L('Your subscription ends on','Abonnementet ditt avsluttes'):L('Your plan change is scheduled for','Abonnementsendringen er planlagt til')} ${date(bill.currentPeriodEnd||bill.changePending?.effectiveAt)}.</p>${button(L('Manage subscription','Administrer abonnement'),'billing')}</div>`;return '';}
function currencyChoices(value='USD'){return ['USD','NOK','EUR','GBP','SEK','DKK','CHF','CAD','JPY'].map(currency=>`<option ${currency===value?'selected':''}>${currency}</option>`).join('');}
function portfolioPage(){surface='workspace';destroyChart();root.classList.remove('p-price-page','p-terminal');document.title=L('Portfolio · Nortivo','Portefølje · Nortivo');const holdings=summary?.holdings||[],currency=summary?.displayCurrency||portfolio?.displayCurrency||'USD',tabs=[['holdings',L('Holdings','Beholdninger')],['transactions',L('Transactions','Transaksjoner')],['history',L('History','Historikk')],['insights',L('Research','Analyse')],['settings',L('Settings','Innstillinger')]];let body='';if(summary){const content=view==='transactions'?transactionsPanel():view==='history'?portfolioHistory():view==='settings'?portfolioSettings():view==='insights'?`<div class="p-stack">${aiPanel(false)}${newsPanel(false)}${calendarPanel(false)}</div>`:holdingsPanel(holdings,currency);body=`${portfolios.length>1?`<label class="p-field p-toolbar"><span>${L('Portfolio','Portefølje')}</span><select id="product-portfolio-select">${portfolios.map(item=>`<option value="${esc(item.id)}" ${item.id===selectedPortfolioId?'selected':''}>${esc(item.name)}</option>`).join('')}</select></label>`:''}<dl class="p-summary"><div><dt>${L('Current value','Nåverdi')}</dt><dd>${money(summary.totalValue,currency)}</dd><small>${summary.valuationStatus==='complete'?L('All holdings valued','Alle beholdninger verdsatt'):L('Partial valuation','Delvis verdsettelse')}</small></div><div><dt>${L('Unrealized gain / loss','Urealisert gevinst / tap')}</dt><dd>${money(summary.displayUnrealizedPnl,currency)}</dd><small>${L('Uses available cost and FX','Bruker tilgjengelig kostpris og valuta')}</small></div><div><dt>${L('Cash','Kontanter')}</dt><dd>${summary.cash?.length===1?money(summary.cash[0].amount,summary.cash[0].currency):L('By currency','Per valuta')}</dd><small>${L('Original currencies retained','Opprinnelige valutaer beholdes')}</small></div><div><dt>${L('Net contributions','Netto innskudd')}</dt><dd>${currencyMap(summary.netContributions)}</dd><small>${L('Deposits less withdrawals','Innskudd minus uttak')}</small></div></dl>${summary.valuationStatus!=='complete'?`<div class="p-banner" data-kind="warning"><div><strong>${L('Some values are missing','Noen verdier mangler')}</strong><p>${L('This total excludes unavailable prices or exchange rates.','Totalen utelater utilgjengelige kurser eller valutakurser.')}</p><details><summary>${L('View missing data','Se manglende data')}</summary><p>${L('Prices','Kurser')}: ${esc((summary.missingPrices||[]).map(x=>typeof x==='string'?x:x.symbol||x.instrumentId).join(', ')||'—')}<br>${L('FX','Valuta')}: ${esc((summary.missingFx||[]).map(x=>typeof x==='string'?x:JSON.stringify(x)).join(', ')||'—')}</p></details></div>${button(L('Set manual value','Sett manuell verdi'),'valuation','',!paid()?'disabled':'')}</div>`:''}<div class="p-toolbar" role="group" aria-label="${L('Portfolio views','Porteføljevisninger')}">${tabs.map(([key,label])=>button(label,'portfolio-view',view===key?'selected':'',`data-view="${key}" aria-pressed="${view===key}"`)).join('')}${button(L('Refresh','Oppdater'),'refresh-portfolio')}</div><div class="p-grid"><div class="p-stack">${content}${['holdings','transactions'].includes(view)?cashPanel():''}</div><aside class="p-stack">${view==='insights'?portfolioWatchlistPanel():allocationPanel(holdings,currency)}${view==='holdings'?panel(L('Portfolio context','Porteføljekontekst'),`<p>${L('Choose a holding to use it as context in Research. Manual records and broker positions stay separate.','Velg en beholdning for å bruke den som grunnlag i Analyse. Manuelle registreringer og meglerposisjoner holdes adskilt.')}</p>${button(L('Open Research','Åpne Analyse'),'portfolio-view','',`data-view="insights"`)}`):''}</aside></div>`;}else{const action=!user()?canRegister()?'signup':'login':paid()?'new-portfolio':'billing',label=!user()?canRegister()?L('Create free account','Opprett gratis konto'):L('Log in','Logg inn'):paid()?L('Create portfolio','Opprett portefølje'):L('View plans','Se abonnementer');body=`<section class="p-onboarding p-panel"><div class="p-panel-body"><p class="p-meta">${L('Nortivo Portfolio','Nortivo Portefølje')}</p><h2>${L('See what you own. Keep a clear record.','Se hva du eier. Behold en tydelig historikk.')}</h2><p>${L('Track holdings, cash and transactions in your own portfolio. You can start with an existing position even when its original purchase date is unknown.','Følg beholdninger, kontanter og transaksjoner i din egen portefølje. Du kan starte med en eksisterende beholdning selv om opprinnelig kjøpsdato er ukjent.')}</p><div class="p-actions">${button(label,action,'p-primary')}${!user()?button(L('Log in to an existing account','Logg inn på en eksisterende konto'),'login'):`<a class="p-button" href="${path('terminal')}">${L('Open Terminal Pro','Åpne Terminal Pro')}</a>`}</div><ol class="pt-source-list"><li><strong>${L('Create a portfolio','Opprett en portefølje')}</strong><p>${L('Choose its name and display currency.','Velg navn og visningsvaluta.')}</p></li><li><strong>${L('Add holdings or cash','Legg til beholdninger eller kontanter')}</strong><p>${L('Enter quantities and known purchase costs. Missing details stay unknown.','Registrer antall og kjent kostpris. Manglende opplysninger forblir ukjente.')}</p></li><li><strong>${L('Record activity over time','Registrer aktivitet over tid')}</strong><p>${L('Build history from actual transactions and dated observations.','Bygg historikk fra faktiske transaksjoner og daterte observasjoner.')}</p></li></ol></div></section>`;}shell(`<main class="p-shell" id="workspace" tabindex="-1"><header class="p-page-heading"><div><h1>${summary?esc(summary.name):L('Your portfolio','Din portefølje')}</h1><p>${L('Manual holdings, cash and transactions.','Manuelle beholdninger, kontanter og transaksjoner.')}</p></div>${summary?`<div class="p-actions">${button(L('New portfolio','Ny portefølje'),'new-portfolio','',!paid()?'disabled':'')}${button(L('Add holding','Legg til beholdning'),'opening','p-primary',!paid()?'disabled':'')}</div>`:''}</header>${subscriptionNotice()}${body}${footer()}</main>`);el('#product-portfolio-select')?.addEventListener('change',async e=>{await loadPortfolio(e.target.value);selectedInstrument=summary?.holdings?.[0]?.instrument||null;await loadContext();portfolioPage();});bindPortfolioSettings();bindAI();el('#terminal-search-form')?.addEventListener('submit',event=>{event.preventDefault();searchInstruments();});}
function holdingsPanel(holdings,currency){return `<section class="p-panel"><div class="p-panel-head"><h2>${L('Holdings','Beholdninger')}</h2><span class="p-status">${L('Manually entered','Manuelt registrert')}</span></div>${holdings.length?`<div class="p-table-wrap" role="region" tabindex="0" aria-label="${L('Scrollable data table','Rullbar datatabell')}"><table><thead><tr><th scope="col">${L('Instrument','Instrument')}</th><th scope="col" class="p-right">${L('Quantity / cost','Antall / kostpris')}</th><th scope="col" class="p-right">${L('Current value','Nåverdi')}</th><th scope="col">${L('Data','Data')}</th><th scope="col">${L('Actions','Handlinger')}</th></tr></thead><tbody>${holdings.map(holding=>`<tr><th scope="row">${button(esc(holding.instrument.symbol),'holding-context','',`data-instrument="${esc(holding.instrument.id)}"`)}<small>${esc(holding.instrument.name)}<br>${esc(holding.instrument.venue)} · ${esc(holding.instrument.currency)} · ${esc(holding.instrument.assetType)}</small>${holding.lots?.length?`<details><summary>${L('Purchase lots','Kjøpsposter')} (${holding.lots.length})</summary><ul class="p-list">${holding.lots.map(lot=>`<li class="p-meta">${decimal(lot.quantity)} · ${money(lot.costBasis,holding.costCurrency)} · ${lot.purchaseDate?esc(lot.purchaseDate):L('Date unknown','Dato ukjent')}</li>`).join('')}</ul></details>`:''}</th><td class="p-right p-mono">${decimal(holding.quantity)}<small>${money(holding.costBasis,holding.costCurrency||holding.instrument.currency)}</small></td><td class="p-right p-mono">${money(holding.displayValue,currency)}<small>${money(holding.marketPrice,holding.marketCurrency||holding.instrument.currency)} / ${L('unit','enhet')}<br>${L('Unrealized','Urealisert')}: ${money(holding.unrealizedPnl,holding.costCurrency||holding.instrument.currency)}</small></td><td>${holding.valuationSource==='manual'?L('Manual valuation','Manuell verdi'):holding.valuationSource==='unavailable'?L('Unavailable','Utilgjengelig'):esc(holding.valuationSource||'—')}<small>${date(holding.asOf)}<br>${stateLabel(holding.status||'')}</small></td><td><div class="p-actions">${button(L('Record trade','Registrer handel'),'trade-transaction','',`data-instrument="${esc(holding.instrument.id)}" ${!paid()?'disabled':''}`)}${button(L('Set value','Sett verdi'),'valuation','',`data-instrument="${esc(holding.instrument.id)}" ${!paid()?'disabled':''}`)}</div></td></tr>`).join('')}</tbody></table></div>`:`<div class="p-empty"><h2>${L('Add what you already own','Legg til det du allerede eier')}</h2><p>${L('Use an opening position for existing holdings. Purchase dates can remain unknown. Future activity goes in the transaction ledger.','Bruk en åpningsbeholdning for det du allerede eier. Kjøpsdato kan være ukjent. Ny aktivitet føres i transaksjonshistorikken.')}</p>${button(L('Add holding','Legg til beholdning'),'opening','p-primary',!paid()?'disabled':'')}</div>`}<div class="p-panel-body"><p class="p-meta">${L('Corporate actions are not automatically applied. If a split is missing, record a split once after checking your broker records. Never adjust both quantity and a second split record. Today’s price change is not your investment return.','Selskapshendelser justeres ikke automatisk. Hvis en splitt mangler, registrer den én gang etter å ha kontrollert meglerens opplysninger. Ikke juster både antall og en ekstra splittpost. Dagens kursendring er ikke avkastningen på investeringen din.')}</p></div></section>`;}
function cashPanel(){return panel(L('Cash by currency','Kontanter per valuta'),`${summary?.cash?.length?`<ul class="p-list">${summary.cash.map(item=>`<li class="p-actions"><strong class="p-mono">${money(item.amount,item.currency)}</strong><span class="p-meta">${item.displayValue===null?L('FX unavailable','Valutakurs utilgjengelig'):money(item.displayValue,summary.displayCurrency)}</span></li>`).join('')}</ul>`:`<p class="p-muted">${L('No cash movements recorded. Add a deposit to establish your cash balance.','Ingen kontantbevegelser registrert. Legg til et innskudd for å etablere kontantbeholdningen.')}</p>`}<div class="p-actions">${button(L('Deposit','Innskudd'),'cash-transaction','',`data-kind="deposit" ${!paid()?'disabled':''}`)}${button(L('Withdrawal','Uttak'),'cash-transaction','',`data-kind="withdrawal" ${!paid()?'disabled':''}`)}${button(L('Dividend','Utbytte'),'cash-transaction','',`data-kind="dividend" ${!paid()?'disabled':''}`)}</div>`);}
function allocationPanel(holdings,currency){const valued=holdings.filter(item=>item.displayValue!==null);return panel(L('Allocation','Fordeling'),`${valued.length?`<ul class="p-list">${valued.map(holding=>`<li class="p-actions"><strong>${esc(holding.instrument.symbol)}</strong><span class="p-mono">${money(holding.displayValue,currency)}</span>${holding.allocationPercent!==undefined&&holding.allocationPercent!==null?`<span>${decimal(holding.allocationPercent)}%</span>`:''}</li>`).join('')}${(summary.cash||[]).map(cash=>`<li class="p-actions"><span>${L('Cash','Kontanter')} ${esc(cash.currency)}</span><strong class="p-mono">${money(cash.displayValue,currency)}</strong></li>`).join('')}</ul>`:`<p class="p-muted">${L('Allocation appears when holdings have supported prices and currency conversion.','Fordeling vises når beholdningene har støttede kurser og valutaomregning.')}</p>`}<p class="p-inline-note">${L('Incomplete prices or FX make allocation partial. Conversion timestamps and sources are shown with the valuation.','Manglende kurser eller valuta gir en delvis fordeling. Omregningens tidspunkt og kilde vises med verdsettelsen.')}</p>${fxDisclosure()}`);}
function kindLabel(kind){return ({opening:L('Opening position','Åpningsbeholdning'),opening_position:L('Opening position','Åpningsbeholdning'),buy:L('Buy','Kjøp'),sell:L('Sell','Salg'),deposit:L('Deposit','Innskudd'),withdrawal:L('Withdrawal','Uttak'),dividend:L('Dividend','Utbytte'),split:L('Split','Splitt')})[kind]||kind;}
function transactionsPanel(){const transactions=displayTransactions();return `<section class="p-panel"><div class="p-panel-head"><h2>${L('Transaction ledger','Transaksjonshistorikk')}</h2>${button(L('Add transaction','Legg til transaksjon'),'transaction','p-primary',!paid()?'disabled':'')}</div>${transactions.length?`<div class="p-table-wrap" role="region" tabindex="0" aria-label="${L('Scrollable data table','Rullbar datatabell')}"><table><thead><tr><th>${L('Type / date','Type / dato')}</th><th>${L('Instrument / currency','Instrument / valuta')}</th><th>${L('Quantity / amount','Antall / beløp')}</th><th>${L('Status','Status')}</th><th>${L('Actions','Handlinger')}</th></tr></thead><tbody>${[...transactions].reverse().map(transaction=>`<tr><td>${kindLabel(transaction.kind||transaction.type)}<small>${transaction.date||transaction.purchaseDate?esc(transaction.date||transaction.purchaseDate):L('Purchase date unknown','Kjøpsdato ukjent')}</small></td><td>${esc(transaction.instrument?.symbol||transaction.instrumentId||'—')}<small>${esc(transaction.currency||transaction.instrument?.currency||'')}</small></td><td class="p-mono">${decimal(transaction.quantity??transaction.amount)}<small>${transaction.unitPrice||transaction.unitCost?money(transaction.unitPrice||transaction.unitCost,transaction.currency||transaction.instrument?.currency):''}${transaction.fees?` · ${L('fees','gebyrer')} ${money(transaction.fees,transaction.currency||transaction.instrument?.currency)}`:''}</small></td><td>${transaction.voided||transaction.status==='void'?L('Voided','Annullert'):L('Recorded','Registrert')}<small>${esc(transaction.notes||'')}</small></td><td>${!transaction.voided&&transaction.status!=='void'?`<div class="p-actions">${button(L('Correct','Korriger'),'correct-transaction','',`data-id="${esc(transaction.id)}" ${!paid()?'disabled':''}`)}${button(L('Void','Annuller'),'void-transaction','p-danger',`data-id="${esc(transaction.id)}" ${!paid()?'disabled':''}`)}</div>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:`<div class="p-empty"><h2>${L('Build a reliable record','Bygg en pålitelig historikk')}</h2><p>${L('Record buys, sells, deposits, withdrawals and dividends. Corrections and voids revalidate the entire ledger before saving.','Registrer kjøp, salg, innskudd, uttak og utbytte. Korreksjoner og annulleringer validerer hele historikken før lagring.')}</p></div>`}</section>`;}
function portfolioHistory(){const history=summary?.history||[];return panel(L('Recorded history','Registrert historikk'),`<p class="p-muted">${L('History starts with recorded observations. Opening holdings do not establish a past performance curve, dividend income or time-weighted return. Realized gains require enough dated trade history.','Historikken starter med registrerte observasjoner. Åpningsbeholdninger skaper ikke en tidligere resultatkurve, utbytteinntekt eller tidsvektet avkastning. Realiserte gevinster krever tilstrekkelig datert handelshistorikk.')}</p><dl class="p-detail"><div><dt>${L('Realized gains by currency','Realiserte gevinster per valuta')}</dt><dd>${currencyMap(summary.realizedPnl)}</dd></div><div><dt>${L('Recorded dividends by currency','Registrert utbytte per valuta')}</dt><dd>${currencyMap(summary.dividends)}</dd></div></dl>${history.length?`<div class="p-table-wrap" role="region" tabindex="0" aria-label="${L('Scrollable data table','Rullbar datatabell')}"><table><thead><tr><th>${L('Observation','Observasjon')}</th><th>${L('Value','Verdi')}</th><th>${L('Data status','Datastatus')}</th></tr></thead><tbody>${history.map(item=>`<tr><td>${date(item.asOf||item.recordedAt)}</td><td class="p-mono">${money(item.totalValue,item.currency||item.displayCurrency||summary.displayCurrency)}</td><td>${esc(item.valuationStatus||'—')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="p-notice warning p-inline-note">${L('There is not enough recorded history to show performance. Deposits and withdrawals are cash flows, not investment gains.','Det er ikke nok registrert historikk til å vise avkastning. Innskudd og uttak er kontantstrømmer, ikke investeringsgevinst.')}</div>`}`);}
function portfolioSettings(){return panel(L('Portfolio settings','Porteføljeinnstillinger'),`<form id="product-portfolio-settings" class="p-form"><div class="p-fields">${field(L('Portfolio name','Porteføljenavn'),'name',portfolio.name,'text','required maxlength="80"')}<label class="p-field"><span>${L('Display currency','Visningsvaluta')}</span><select name="displayCurrency">${currencyChoices(portfolio.displayCurrency)}</select><small>${L('FX conversion does not change the original transaction currency.','Valutaomregning endrer ikke transaksjonens opprinnelige valuta.')}</small></label></div>${formActions(L('Save settings','Lagre innstillinger'))}</form>`);}
function bindPortfolioSettings(){bindForm('#product-portfolio-settings',async data=>{await portfolioCommand({type:'portfolio_settings',...data});portfolioPage();});}
async function portfolioCommand(command,id=requestId()){const result=await api('product-portfolio',{method:'POST',body:{requestId:id,command:{...command,...(command.type!=='portfolio_create'?{portfolioId:selectedPortfolioId}:{})}}});portfolio=result.portfolio;summary=result.summary;selectedPortfolioId=portfolio.id;const list=await api('product-portfolio');portfolios=list.portfolios||[];return result;}
function newPortfolio(){showDialog(L('Create portfolio','Opprett portefølje'),`<p class="p-muted">${L('Manually entered records stay separate from connected broker accounts.','Manuelle registreringer holdes adskilt fra tilkoblede meglerkontoer.')}</p><form id="new-portfolio-form" class="p-form"><div class="p-fields">${field(L('Name','Navn'),'name','','text','required maxlength="80" placeholder="'+L('Long-term investments','Langsiktige investeringer')+'"')}<label class="p-field"><span>${L('Display currency','Visningsvaluta')}</span><select name="displayCurrency">${currencyChoices(locale==='nb'?'NOK':'USD')}</select></label></div>${formActions(L('Create portfolio','Opprett portefølje'))}</form>`);const id=requestId();bindForm('#new-portfolio-form',async data=>{await portfolioCommand({type:'portfolio_create',...data},id);closeDialog();portfolioPage();openLedger('opening_position');},{scope:dialog});}
function instrumentFields(instrument=null){return `<div class="p-field full"><label for="instrument-query">${L('Search supported instruments','Søk i støttede instrumenter')}</label><div class="p-password"><input id="instrument-query" name="instrumentQuery" type="search" placeholder="${L('Symbol or company name','Symbol eller selskapsnavn')}" value="${esc(instrument?.symbol||'')}">${button(L('Search','Søk'),'instrument-search')}</div><div id="instrument-results" aria-live="polite"></div><small>${L('Select the exact instrument and venue. If coverage is unavailable, enter a manual instrument with a distinct identifier.','Velg riktig instrument og handelsplass. Hvis dekning mangler, registrer et manuelt instrument med egen identifikator.')}</small></div>${field(L('Instrument identifier','Instrumentidentifikator'),'instrumentId',instrument?.id||'','text','required maxlength="120"',L('Use the supported ID or manual:your-unique-id.','Bruk støttet ID eller manual:din-unike-id.'))}${field(L('Symbol','Symbol'),'symbol',instrument?.symbol||'','text','required maxlength="24"')}${field(L('Instrument name','Instrumentnavn'),'instrumentName',instrument?.name||'','text','required maxlength="160"')}${field(L('Venue / exchange','Handelsplass / børs'),'venue',instrument?.venue||'','text','required maxlength="24"')}<label class="p-field"><span>${L('Trading currency','Handelsvaluta')}</span><select name="currency">${currencyChoices(instrument?.currency||'USD')}</select></label><label class="p-field"><span>${L('Asset type','Aktivatype')}</span><select name="assetType">${[['stock',L('Stock','Aksje')],['etf','ETF'],['manual',L('Manual / unsupported','Manuell / uten dekning')]].map(([key,label])=>`<option value="${key}" ${instrument?.assetType===key?'selected':''}>${label}</option>`).join('')}</select></label>`;}
function instrumentFromForm(data){return {id:data.instrumentId,symbol:data.symbol,name:data.instrumentName,venue:data.venue,currency:data.currency,assetType:data.assetType};}
function openLedger(kind='buy',transactionId=null,instrumentId=null){const transactions=displayTransactions(),existing=transactionId?transactions.find(item=>item.id===transactionId):null;if(existing)kind=existing.kind||existing.type;const opening=['opening','opening_position'].includes(kind);if(opening)kind='opening_position';const instrument=existing?.instrument||portfolio?.instruments?.[existing?.instrumentId]||(summary?.holdings||[]).find(item=>item.instrument.id===instrumentId)?.instrument||null;selectedInstrument=instrument;const cash=['deposit','withdrawal'].includes(kind),dividend=kind==='dividend',split=kind==='split';showDialog(existing?L('Correct transaction','Korriger transaksjon'):opening?L('Add opening holding','Legg til åpningsbeholdning'):L('Record transaction','Registrer transaksjon'),`<p class="p-muted">${opening?L('Use this for an existing holding. Leave the purchase date blank when it is unknown.','Bruk dette for en eksisterende beholdning. La kjøpsdatoen stå tom når den er ukjent.'):L('Dates and currency must match your records. The complete ledger is checked before saving.','Datoer og valuta må stemme med registreringene dine. Hele historikken kontrolleres før lagring.')}</p>${!opening&&!existing?`<div class="p-toolbar" role="group" aria-label="${L('Transaction type','Transaksjonstype')}">${['buy','sell','deposit','withdrawal','dividend','split'].map(value=>button(kindLabel(value),'ledger-kind','',`data-kind="${value}" data-instrument="${esc(instrumentId||'')}" aria-pressed="${kind===value}"`)).join('')}</div>`:''}<form id="ledger-form" class="p-form"><div class="p-fields">${!cash?instrumentFields(instrument):`<label class="p-field"><span>${L('Currency','Valuta')}</span><select name="currency">${currencyChoices(existing?.currency||summary.displayCurrency)}</select></label>`}${!cash&&!split&&!dividend?field(L('Quantity (decimal allowed)','Antall (desimaler tillatt)'),'quantity',existing?.quantity||'','text','inputmode="decimal" pattern="[0-9]+([.][0-9]+)?" required',L('Use a dot as the decimal separator.','Bruk punktum som desimalskilletegn.')):''}${!cash&&!split&&!dividend?field(opening?L('Average unit cost','Gjennomsnittlig kostpris per enhet'):L('Unit price','Kurs per enhet'),opening?'unitCost':'unitPrice',existing?.unitCost||existing?.unitPrice||'','text',`inputmode="decimal" pattern="[0-9]+([.][0-9]+)?" ${opening?'':'required'}`,opening?L('Leave blank if purchase cost is unknown.','La stå tomt hvis kostprisen er ukjent.'):''):''}${cash||dividend?field(L('Amount','Beløp'),'amount',existing?.amount||'','text','inputmode="decimal" pattern="[0-9]+([.][0-9]+)?" required'):''}${split?field(L('Split ratio (new units per old unit)','Splittforhold (nye enheter per gammel enhet)'),'ratio',existing?.ratio||'','text','inputmode="decimal" pattern="[0-9]+([.][0-9]+)?" required',L('For 2-for-1 enter 2. This does not create a second price adjustment.','Skriv 2 ved 2-for-1. Dette oppretter ikke en ekstra kursjustering.')):''}${field(opening?L('Purchase date (optional)','Kjøpsdato (valgfritt)'):L('Transaction date','Transaksjonsdato'),opening?'purchaseDate':'date',existing?.purchaseDate||existing?.date||'','date',opening?'':'required')}${!split&&!cash?field(L('Fees in transaction currency','Gebyrer i transaksjonsvaluta'),'fees',existing?.fees||'0','text','inputmode="decimal" pattern="[0-9]+([.][0-9]+)?" required'):''}<label class="p-field full"><span>${L('Notes (optional)','Notater (valgfritt)')}</span><textarea name="notes" maxlength="1000">${esc(existing?.notes||'')}</textarea></label></div>${formActions(existing?L('Validate and save correction','Valider og lagre korreksjon'):L('Save record','Lagre registrering'))}</form>`);const id=requestId();bindForm('#ledger-form',async data=>{const record={...(opening?{}:{kind}),...(!cash?{instrument:instrumentFromForm(data),instrumentId:data.instrumentId}:{}),currency:data.currency,fees:data.fees||'0',notes:data.notes||''};if(opening){record.quantity=data.quantity;record.unitCost=data.unitCost;record.purchaseDate=data.purchaseDate||null;}else{record.date=data.date;if(cash||dividend)record.amount=data.amount;else if(split)record.ratio=data.ratio;else{record.quantity=data.quantity;record.unitPrice=data.unitPrice;}}await portfolioCommand(existing?{type:'transaction_correct',transactionId:existing.id,replacement:{...record,kind:opening?'opening':kind}}:{type:opening?'opening_position':'transaction_add',...record},id);closeDialog();view='transactions';portfolioPage();notify(L('Ledger validated and saved.','Historikken er validert og lagret.'));},{scope:dialog});}
async function searchInstruments(){const query=el('#instrument-query',dialog)||el('#terminal-instrument-query'),results=el('#instrument-results',dialog)||el('#terminal-instrument-results');if(!query||!results)return;results.innerHTML=`<p class="p-meta">${L('Searching…','Søker…')}</p>`;try{if(isTerminal()&&terminalMode==='sample'){const term=query.value.trim().toLowerCase();instrumentResults=(sampleState?.catalog||[]).filter(item=>!term||`${item.symbol} ${item.name}`.toLowerCase().includes(term)).map(item=>({...item,id:item.symbol,venue:'SAMPLE'}));}else{const data=await api('product-catalog',{params:{q:query.value}});instrumentResults=data.instruments||[];}results.innerHTML=instrumentResults.length?`<ul class="p-list">${instrumentResults.map((item,index)=>`<li>${button(`${esc(item.symbol)} · ${esc(item.name)} · ${esc(item.venue)} · ${esc(item.currency)}`,'instrument-select','',`data-index="${index}"`)}</li>`).join('')}</ul>`:`<p class="p-meta">${isTerminal()?L('No matching instruments in this data source. Try an exact symbol or company name.','Ingen matchende instrumenter i denne datakilden. Prøv et nøyaktig symbol eller selskapsnavn.'):L('No supported match. You can enter a manual identifier with its venue and currency in the holding form.','Ingen støttede treff. Du kan registrere en manuell identifikator med handelsplass og valuta i beholdningsskjemaet.')}</p>`;}catch(error){results.innerHTML=`<p class="p-error" role="alert">${esc(errorText(error))}</p>`;}}
function manualValuation(instrumentId){const holdings=summary?.holdings||[];if(!holdings.length){notify(L('Add a holding before entering its value.','Legg til en beholdning før du registrerer verdien.'));return;}showDialog(L('Set a manual valuation','Sett en manuell verdi'),`<p class="p-muted">${L('This is your own price observation. It remains explicitly labeled manual and is never described as a live provider quote.','Dette er din egen kursobservasjon. Den er tydelig merket som manuell og beskrives aldri som en direkte leverandørkurs.')}</p><form id="valuation-form" class="p-form"><label class="p-field"><span>${L('Instrument','Instrument')}</span><select name="instrumentId">${holdings.map(holding=>`<option value="${esc(holding.instrument.id)}" ${holding.instrument.id===instrumentId?'selected':''}>${esc(holding.instrument.symbol)} · ${esc(holding.instrument.venue)} · ${esc(holding.instrument.currency)}</option>`).join('')}</select></label><div class="p-fields">${field(L('Price per unit','Kurs per enhet'),'price','','text','inputmode="decimal" pattern="[0-9]+([.][0-9]+)?" required')}<label class="p-field"><span>${L('Price currency','Kursvaluta')}</span><select name="currency">${currencyChoices((holdings.find(h=>h.instrument.id===instrumentId)||holdings[0]).instrument.currency)}</select></label>${field(L('Observation time','Observasjonstidspunkt'),'asOf','','datetime-local','required')}</div>${formActions(L('Save manual value','Lagre manuell verdi'))}</form>`);const id=requestId();bindForm('#valuation-form',async data=>{await portfolioCommand({type:'valuation_set',...data,asOf:new Date(data.asOf).toISOString()},id);closeDialog();portfolioPage();},{scope:dialog});}
function voidTransaction(id){showDialog(L('Void this transaction?','Annullere transaksjonen?'),`<p>${L('The original record stays in the audit history. The entire ledger will be recalculated and the change will be rejected if it leaves invalid quantities or cash.','Den opprinnelige registreringen beholdes i revisjonshistorikken. Hele historikken beregnes på nytt, og endringen avvises hvis antall eller kontanter blir ugyldige.')}</p><form id="void-form">${formActions(L('Validate and void','Valider og annuller'))}</form>`);const receipt=requestId();bindForm('#void-form',async()=>{await portfolioCommand({type:'transaction_void',transactionId:id},receipt);closeDialog();portfolioPage();},{scope:dialog});}

function minorAmount(value,currency='USD'){if(value===null||value===undefined)return '—';try{const amount=BigInt(value),negative=amount<0n,abs=negative?-amount:amount;return money(`${negative?'-':''}${abs/100n}.${String(abs%100n).padStart(2,'0')}`,currency);}catch{return '—';}}
function billingStatus(value){return ({none:L('No active subscription','Ingen aktivt abonnement'),active:L('Active','Aktivt'),past_due:L('Payment needs attention','Betaling trenger oppfølging'),unpaid:L('Unpaid','Ubetalt'),incomplete:L('Payment pending','Betaling venter'),incomplete_expired:L('Checkout expired','Betalingsøkten er utløpt'),canceled:L('Ended','Avsluttet'),trialing:L('Billing status requires review','Betalingsstatus må kontrolleres')})[value]||L('Confirming your payment','Bekrefter betalingen din');}
async function accountPage(tab='account'){surface='account';accountTab=tab;if(!user()){authScreen('login');return;}destroyChart();root.classList.remove('p-price-page','p-terminal');const billing=snapshot.billing||{};shell(`<main class="p-shell" id="workspace" tabindex="-1"><div class="p-page-heading"><div><h1>${L('Account & billing','Konto og betaling')}</h1><p>${esc(user().email)} · ${user().emailVerified?L('Email verified','E-post bekreftet'):L('Email not verified','E-post ikke bekreftet')}</p></div><div class="p-actions">${button(L('Back to workspace','Tilbake til arbeidsområdet'),'workspace')}${button(L('Sign out','Logg ut'),'logout','p-danger')}</div></div><div class="p-toolbar" role="group" aria-label="${L('Account views','Kontovisninger')}">${button(L('Subscription','Abonnement'),'billing','',`aria-pressed="${tab==='billing'}"`)}${button(L('Security & sessions','Sikkerhet og økter'),'account','',`aria-pressed="${tab!=='billing'}"`)}</div>${tab==='billing'?`<div class="p-account-grid">${panel(L('Your subscription','Abonnementet ditt'),`<span class="p-status">${billingStatus(billing.status)}</span>${billing.mode==='test'?`<p class="p-notice warning p-inline-note">${L('Payment sandbox. This environment does not establish a production subscription.','Betalingssandkasse. Dette miljøet oppretter ikke et produksjonsabonnement.')}</p>`:''}<dl class="p-detail"><div><dt>${L('Current plan','Nåværende abonnement')}</dt><dd>${paid()?planName(snapshot.entitlements.tier):'—'}</dd></div><div><dt>${L('Billing interval','Betalingsintervall')}</dt><dd>${billing.interval==='year'?L('Annual','Årlig'):billing.interval==='month'?L('Monthly','Månedlig'):'—'}</dd></div><div><dt>${L('Current charge','Nåværende beløp')}</dt><dd>${billing.tier?`USD ${total(billing.tier,billing.interval==='year'?'year':'month')}`:'—'}${billing.interval==='year'?' '+L('upfront per year','på forskudd per år'):billing.interval==='month'?' / '+L('month','måned'):''}</dd></div><div><dt>${billing.cancelAtPeriodEnd?L('Access ends','Tilgangen avsluttes'):L('Next renewal','Neste fornyelse')}</dt><dd>${date(billing.currentPeriodEnd)}</dd></div></dl>${billing.changePending?`<div class="p-notice warning">${L('Pending change','Ventende endring')}: ${stateLabel(billing.changePending.kind||'')} ${billing.changePending.tier?planName(billing.changePending.tier):''}<br>${L('Effective','Gjelder fra')}: ${date(billing.changePending.effectiveAt||billing.changePending.expiresAt)}<br>${L('Your current plan stays active until the change is complete.','Nåværende abonnement forblir aktivt til endringen er fullført.')}</div>`:''}<div class="p-actions">${button(L('Invoices & payment method','Fakturaer og betalingsmåte'),'portal','p-primary',!billing.customerId?'disabled':'')}${button(L('Refresh billing','Oppdater betaling'),'refresh-billing','',!billing.customerId&&!billing.subscriptionId?'disabled':'')}${billing.cancelAtPeriodEnd?button(L('Keep subscription','Behold abonnementet'),'resume'):paid()?button(L('Cancel at period end','Si opp ved periodeslutt'),'cancel-plan','p-danger'):''}</div><p class="p-inline-note">${L('The secure customer portal handles invoices, card details and payment recovery. Broker funds and subscription payments are separate.','Den sikre kundeportalen håndterer fakturaer, kortopplysninger og betalingsoppfølging. Meglermidler og abonnementsbetalinger er adskilt.')}</p>`)}${panel(paid()?L('Change plan','Endre abonnement'):L('Choose a plan','Velg et abonnement'),`<form id="billing-plan-form" class="p-form"><label class="p-field"><span>${L('Plan','Abonnement')}</span><select name="tier"><option value="portfolio" ${intent.tier==='portfolio'?'selected':''}>Nortivo Portfolio — USD 10 / ${L('month','måned')}</option><option value="pro" ${intent.tier==='pro'?'selected':''}>Nortivo Terminal Pro — USD 30 / ${L('month','måned')}</option></select></label><label class="p-field"><span>${L('Interval','Intervall')}</span><select name="interval"><option value="month" ${intent.interval==='month'?'selected':''}>${L('Monthly','Månedlig')}</option><option value="year" ${intent.interval==='year'?'selected':''}>${L('Annual — save 20%','Årlig — spar 20 %')}</option></select></label><div id="billing-plan-disclosure" class="p-notice"></div><p id="billing-readiness-note" class="p-meta" ${ready()?'hidden':''}>${L('Purchases await verified required integrations and payment setup.','Kjøp venter på bekreftede nødvendige tilkoblinger og betalingsoppsett.')}</p>${formActions(paid()?L('Preview charge and effective date','Forhåndsvis beløp og virkningsdato'):L('Continue to secure checkout','Fortsett til sikker betaling'))}</form><p class="p-inline-note">${L('A downgrade takes effect at renewal by default. Your holdings, strategies and history stay saved. It does not liquidate positions or remove stop, cancel and risk-reduction controls.','En nedgradering gjelder som standard fra neste fornyelse. Beholdninger, strategier og historikk beholdes. Den selger ikke posisjoner og fjerner ikke stopp-, kansellerings- eller risikoreduserende kontroller.')}</p>`)}</div>`:`<div class="p-account-grid">${panel(L('Password','Passord'),`<form id="password-change-form" class="p-form">${password(L('Current password','Nåværende passord'),'currentPassword')}${password(L('New password','Nytt passord'),'password','new-password')}${formActions(L('Change password','Endre passord'))}</form><p class="p-inline-note">${L('Changing your password revokes all sessions. Sign in again afterward.','Når du endrer passordet, avsluttes alle økter. Logg inn på nytt etterpå.')}</p>`)}${panel(L('Authenticator security','Sikkerhet med autentiseringsapp'),`<p>${snapshot.capabilities?.mfaEnabled?L('Authenticator protection is enabled. Confirm sensitive brokerage and execution actions with a current code.','Autentisering er aktivert. Bekreft sensitive megler- og utførelseshandlinger med en gjeldende kode.'):L('Set up an authenticator before sensitive brokerage and automation controls. Save recovery codes somewhere private.','Sett opp en autentiseringsapp før du bruker sensitive megler- og automatiseringskontroller. Oppbevar gjenopprettingskodene privat.')}</p><div class="p-actions">${snapshot.capabilities?.mfaEnabled?button(L('Confirm a sensitive action','Bekreft en sensitiv handling'),'stepup')+button(L('Disable authenticator','Deaktiver autentiseringsapp'),'mfa-disable','p-danger'):button(L('Set up authenticator','Sett opp autentiseringsapp'),'mfa-enroll','p-primary',snapshot.capabilities?.mfa===false?'disabled':'')}</div>`)}${panel(L('Active sessions','Aktive økter'),`<div id="product-sessions" class="p-loading" role="status">${L('Loading your sessions…','Laster øktene dine…')}</div><div class="p-actions">${button(L('Refresh sessions','Oppdater økter'),'sessions')}${button(L('Sign out all sessions','Logg ut alle økter'),'revoke-all','p-danger')}</div>`)}${panel(L('Account records','Kontoregistreringer'),`<p>${L('Your account, billing, existing history and brokerage safety controls remain available after paid access ends. Guest sample records stay separate from your private account.','Kontoen, betaling, eksisterende historikk og meglerens sikkerhetskontroller forblir tilgjengelige etter at betalt tilgang avsluttes. Gjestens eksempelregistreringer er adskilt fra den private kontoen.')}</p><div class="p-actions">${button(L('Export portfolio records','Eksporter porteføljeregistreringer'),'export-portfolio','',!selectedPortfolioId?'disabled':'')}${button(L('Export legacy paper ledger','Eksporter tidligere papirhistorikk'),'export-legacy')}${button(L('Request account deletion','Be om kontosletting'),'request-deletion','p-danger')}</div><p class="p-inline-note">${L('For account deletion, contact support so recurring billing and broker connections can be resolved together.','Kontakt kundestøtte for sletting av konto, slik at løpende betaling og meglertilkoblinger håndteres samlet.')}</p>`)}</div>`}${footer()}</main>`,accountWorkspace());if(tab==='billing'){const form=el('#billing-plan-form');const disclosure=()=>{const tier=form.elements.tier.value,interval=form.elements.interval.value;form.querySelector('[type=submit]').disabled=!ready(tier);el('#billing-readiness-note').hidden=ready(tier);el('#billing-plan-disclosure').textContent=interval==='year'?L(`USD ${total(tier,'year')} charged upfront each year (USD ${tier==='portfolio'?8:24}/month equivalent). Save 20%. No trial.`,`USD ${total(tier,'year')} belastes på forskudd hvert år (tilsvarende USD ${tier==='portfolio'?8:24}/måned). Spar 20 %. Ingen prøveperiode.`):L(`USD ${total(tier,'month')} charged each month. No trial.`,`USD ${total(tier,'month')} belastes hver måned. Ingen prøveperiode.`);};form.addEventListener('change',disclosure);disclosure();bindForm('#billing-plan-form',async data=>{if(!ready(data.tier))throw{code:'BILLING_NOT_READY'};intent={...intent,...data};await post('product-select-plan',intent);if(paid()){const preview=await post('product-change-preview',data);showPlanPreview(preview,data);}else await checkout();});}else{bindForm('#password-change-form',async data=>{await post('product-change-password',data);snapshot=null;session=null;authScreen('login');notify(L('Password changed. Sign in again.','Passordet er endret. Logg inn på nytt.'));});await loadSessions();}}
async function loadSessions(){const node=el('#product-sessions');if(!node)return;try{const data=await api('product-sessions');node.classList.remove('p-loading');node.innerHTML=`<ul class="p-list">${(data.sessions||[]).map(item=>`<li><div class="p-actions"><strong>${item.current?L('This session','Denne økten'):L('Other session','Annen økt')}</strong>${button(L('Revoke','Avslutt'),'revoke-session','',`data-id="${esc(item.id)}"`)}</div><span class="p-meta">${L('Created','Opprettet')}: ${date(item.createdAt)} · ${L('Expires','Utløper')}: ${date(item.expiresAt)}</span></li>`).join('')}</ul>`;}catch(error){node.textContent=errorText(error);node.className='p-error';}}
async function checkout(){if(!user()){authScreen('signup');return;}if(!user().emailVerified){verificationScreen();return;}if(!ready())throw{code:'BILLING_NOT_READY'};if(paid()){await accountPage('billing');return;}const result=await post('product-checkout',{tier:intent.tier,interval:intent.interval});const url=safeWebUrl(result.url);if(!url)throw{code:'CHECKOUT_UNAVAILABLE',message:L('Checkout could not be opened. Retry from billing.','Betalingssiden kunne ikke åpnes. Prøv igjen fra betaling.')};location.assign(url);}
function showPlanPreview(preview,selection){showDialog(L('Review subscription change','Se gjennom abonnementsendringen'),`<p><strong>${planName(selection.tier)}</strong> · ${selection.interval==='year'?L(`USD ${total(selection.tier,'year')} upfront annually`,`USD ${total(selection.tier,'year')} på forskudd årlig`):L(`USD ${total(selection.tier,'month')} monthly`,`USD ${total(selection.tier,'month')} månedlig`)}</p><dl class="p-detail"><div><dt>${L('Charge due now (server preview)','Beløp nå (forhåndsvisning fra server)')}</dt><dd class="p-mono">${minorAmount(preview.amountDue,preview.currency||'USD')}</dd></div><div><dt>${L('Effective date','Virkningsdato')}</dt><dd>${date(preview.effectiveAt)}</dd></div><div><dt>${L('Preview expires','Forhåndsvisningen utløper')}</dt><dd>${date(preview.expiresAt)}</dd></div></dl><div class="p-notice">${preview.immediate?L('The upgrade takes effect only after payment is confirmed. An unpaid upgrade leaves your existing paid access in place.','Oppgraderingen gjelder først etter bekreftet betaling. En ubetalt oppgradering beholder den eksisterende betalte tilgangen.'):L('This change is scheduled for renewal. Your current plan remains in place until the stated date.','Endringen er planlagt fra fornyelsen. Nåværende abonnement gjelder frem til oppgitt dato.')}</div><form id="plan-confirm-form">${formActions(L('Confirm change','Bekreft endring'))}</form>`);const id=requestId();bindForm('#plan-confirm-form',async()=>{const result=await api('product-change',{method:'POST',body:{requestId:id,...selection,previewId:preview.previewId}});if(result.paymentRequired&&safeWebUrl(result.paymentUrl)){await refreshSnapshot();showDialog(L('Complete upgrade payment','Fullfør oppgraderingsbetalingen'),`<p>${L('Your current plan stays active until payment is confirmed. Complete authentication or payment with Stripe.','Nåværende abonnement beholdes til betalingen er bekreftet. Fullfør autentisering eller betaling hos Stripe.')}</p><a class="p-button p-primary" href="${esc(safeWebUrl(result.paymentUrl))}">${L('Continue payment','Fortsett betalingen')}</a>`);return;}await refreshSnapshot();closeDialog();await accountPage('billing');notify(L('Change submitted. Billing status is confirmed by the server.','Endringen er sendt. Betalingsstatus bekreftes av serveren.'));},{scope:dialog});}
function confirmCancellation(){showDialog(L('Cancel at period end?','Si opp ved periodeslutt?'),`<p>${L('Your purchased access continues until','Den betalte tilgangen varer til')} <strong>${date(snapshot.billing.currentPeriodEnd)}</strong>. ${L('Records stay saved. New Pro analysis and risk-increasing automation stop when access ends. Existing positions are not sold automatically.','Registreringene beholdes. Ny Pro-analyse og automatisering som øker risiko, stanser når tilgangen avsluttes. Eksisterende posisjoner selges ikke automatisk.')}</p><form id="cancel-plan-form">${formActions(L('Schedule cancellation','Planlegg oppsigelse'))}</form>`);const id=requestId();bindForm('#cancel-plan-form',async()=>{await api('product-cancel',{method:'POST',body:{requestId:id}});await refreshSnapshot();closeDialog();accountPage('billing');},{scope:dialog});}
function mfaEnroll(){showDialog(L('Set up authenticator','Sett opp autentiseringsapp'),`<form id="mfa-enroll-form" class="p-form">${password(L('Confirm your password','Bekreft passordet'))}${formActions(L('Create authenticator setup','Opprett autentiseringsoppsett'))}</form>`);bindForm('#mfa-enroll-form',async data=>{const setup=await post('product-mfa-enroll',data);showDialog(L('Add to your authenticator','Legg til i autentiseringsappen'),`<p>${L('Enter this setup key in your authenticator app. It is private and appears only during setup.','Skriv inn denne oppsettnøkkelen i autentiseringsappen. Den er privat og vises bare under oppsettet.')}</p><code class="p-key">${esc(setup.secret)}</code><form id="mfa-confirm-form" class="p-form">${field(L('Six-digit authenticator code','Sekssifret kode fra autentiseringsappen'),'code','','text','inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" required')}${formActions(L('Confirm authenticator','Bekreft autentiseringsappen'))}</form>`);bindForm('#mfa-confirm-form',async values=>{const confirmed=await post('product-mfa-confirm',values);await refreshSnapshot();showDialog(L('Save your recovery codes','Ta vare på gjenopprettingskodene'),`<p>${L('Store these privately. Each code can be used once when your authenticator is unavailable. They will not be shown again.','Oppbevar disse privat. Hver kode kan brukes én gang når autentiseringsappen er utilgjengelig. De vises ikke på nytt.')}</p><code class="p-key">${(confirmed.recoveryCodes||[]).map(esc).join('<br>')}</code>${button(L('I have saved the codes','Jeg har lagret kodene'),'finish-mfa','p-primary')}`);},{scope:dialog});},{scope:dialog});}
function stepUp(scope='security'){showDialog(L('Confirm sensitive action','Bekreft sensitiv handling'),`<form id="stepup-form" class="p-form"><label class="p-field"><span>${L('Action scope','Handlingsområde')}</span><select name="scope">${[['security',L('Account security','Kontosikkerhet')],['broker',L('Broker connection','Meglertilkobling')],['execution',L('Order and automation','Ordre og automatisering')]].map(([value,label])=>`<option value="${value}" ${value===scope?'selected':''}>${label}</option>`).join('')}</select></label>${field(L('Authenticator or recovery code','Autentiseringskode eller gjenopprettingskode'),'code','','text','autocomplete="one-time-code" required maxlength="40"')}${formActions(L('Confirm','Bekreft'))}</form>`);bindForm('#stepup-form',async data=>{await post('product-mfa-stepup',securityInput(data));closeDialog();notify(L('Sensitive action confirmed for this session. Retry your intended action.','Sensitiv handling er bekreftet for denne økten. Prøv den ønskede handlingen på nytt.'));},{scope:dialog});}
function disableMfa(){showDialog(L('Disable authenticator','Deaktiver autentiseringsapp'),`<form id="mfa-disable-form" class="p-form">${password(L('Password','Passord'))}${field(L('Authenticator or recovery code','Autentiseringskode eller gjenopprettingskode'),'code','','text','autocomplete="one-time-code" required maxlength="40"')}${formActions(L('Disable authenticator','Deaktiver autentiseringsapp'))}</form>`);bindForm('#mfa-disable-form',async data=>{await post('product-mfa-disable',securityInput(data));closeDialog();snapshot=null;session=null;authScreen('login');notify(L('Authenticator disabled. Sign in again.','Autentiseringsappen er deaktivert. Logg inn på nytt.'));},{scope:dialog});}
function newsPanel(compact=false){const items=news.filter(item=>!newsSymbol||item.symbols?.includes(newsSymbol));return panel(compact?L('Relevant news','Relevante nyheter'):L('Publisher news','Nyheter fra utgivere'),`${items.length?`<div class="pt-news-feed">${items.slice(0,compact?3:12).map(item=>`<article><p class="p-source">${esc(item.source||L('Source unavailable','Kilde utilgjengelig'))} · ${date(item.publishedAt)}</p><h3>${safeWebUrl(item.url)?`<a href="${esc(safeWebUrl(item.url))}" target="_blank" rel="noopener noreferrer">${esc(item.title)}</a>`:esc(item.title)}</h3>${item.summary?`<p>${esc(item.summary)}</p>`:''}${item.symbols?.length?`<p class="p-meta">${esc(item.symbols.join(' · '))}</p>`:''}</article>`).join('')}</div>`:unavailable('news',has('news.read'))}<p class="p-source">${L('Original reporting is separate from AI-generated explanations.','Original journalistikk er adskilt fra KI-genererte forklaringer.')}</p>`,`${status('news',has('news.read'))}${!compact?button(L('Search & filters','Søk og filtre'),'news-full'):''}`);}
function calendarPanel(compact=false){return panel(L('Economic calendar','Økonomisk kalender'),`${events.length?`<ul class="p-list">${events.slice(0,compact?3:12).map(item=>`<li><strong>${esc(item.title)}</strong><span class="p-meta">${date(item.time)} · ${esc(item.country)} · ${esc(item.currency)} · ${esc(item.importance||'')}</span>${compact?'':`<p class="p-meta">${L('Actual','Faktisk')}: ${esc(item.actual??'—')} · ${L('Consensus','Konsensus')}: ${esc(item.consensus??'—')} · ${L('Previous','Forrige')}: ${esc(item.previous??'—')} · ${L('Revised','Revidert')}: ${esc(item.revised??'—')} ${esc(item.unit||'')}</p>`}${safeWebUrl(item.url)?`<a class="p-meta" href="${esc(safeWebUrl(item.url))}" target="_blank" rel="noopener noreferrer">${esc(item.source||L('Original source','Originalkilde'))}</a>`:''}${reminderControls(item)}</li>`).join('')}</ul>`:unavailable('calendar')}<p class="p-source">${L('Times use your current timezone','Tidene bruker gjeldende tidssone')}: ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}. ${L('No background reminders are enabled.','Ingen bakgrunnspåminnelser er aktivert.')}</p>`,`${status('calendar')}${isTerminal()?button(L('All events','Alle hendelser'),'calendar-full'):button(L('Reminders','Påminnelser'),'reminders-list')}`);}
function aiPanel(advanced=false){const usage=snapshot?.ai||{},included=has(advanced?'ai.advanced':'ai.basic'),state=dataState(snapshot?.readiness?.ai,included),available=['current','delayed','closed'].includes(state),context=selectedInstrument?`${esc(selectedInstrument.symbol)} · ${esc(selectedInstrument.venue||'')} · ${advanced?resolution:esc(summary?.name||L('Portfolio','Portefølje'))}`:esc(summary?.name||L('No instrument selected','Ingen instrumenter valgt'));return panel(advanced?L('AI research','KI-analyse'):L('Portfolio explanation','Porteføljeforklaring'),`<div class="pt-context"><span>${context}</span><span class="p-status" data-state="${state}">${rawStateName(state)}</span></div><p class="p-meta">${L('An on-demand explanation using available, timestamped evidence. It cannot place orders or change your risk limits.','En forklaring på forespørsel med tilgjengelig, tidsstemplet grunnlag. Den kan ikke legge inn ordrer eller endre risikogrenser.')}</p><form id="product-ai-form" class="p-form"><label class="p-field"><span>${L('Your question','Spørsmålet ditt')}</span><textarea name="question" maxlength="4000" required ${!included||!available?'disabled':''} placeholder="${advanced?L('What should I understand about this instrument or recorded signal?','Hva bør jeg forstå om dette instrumentet eller registrerte signalet?'):L('Explain my allocation or a portfolio term…','Forklar fordelingen min eller et porteføljebegrep…')}"></textarea></label><div class="p-actions"><button type="submit" class="p-primary" ${!included||!available?'disabled':''}>${L('Ask for an explanation','Be om en forklaring')}</button></div>${errorSlot()}</form>${!available?unavailable('ai',included):''}<p class="p-source">${included?`${L('Remaining requests','Forespørsler igjen')}: ${usage.remainingRequests??'—'} / ${usage.requestLimit??'—'} · ${L('Resets','Nullstilles')}: ${date(usage.resetAt)}`:L('Your subscription does not include this AI tool. Availability is shown separately above.','Abonnementet ditt inkluderer ikke dette KI-verktøyet. Tilgjengeligheten vises separat ovenfor.')}</p>${aiAnswer?`<article class="p-ai-answer"><strong>${L('AI-generated explanation','KI-generert forklaring')}</strong><p>${esc(aiAnswer.text||aiAnswer.answer||'')}</p><p class="p-source">${L('Evidence as of','Grunnlag fra')}: ${date(aiAnswer.evidenceAsOf||aiAnswer.asOf)}</p>${aiAnswer.uncertainty?`<p>${esc(aiAnswer.uncertainty)}</p>`:''}${Array.isArray(aiAnswer.sources)?`<ul class="pt-source-list">${aiAnswer.sources.map(source=>`<li>${safeWebUrl(source.url)?`<a target="_blank" rel="noopener noreferrer" href="${esc(safeWebUrl(source.url))}">${esc(source.title||source.name||source.url)}</a>`:esc(source.title||source.name||'')}<span class="p-meta">${date(source.asOf)}</span></li>`).join('')}</ul>`:''}</article>`:''}`);}
function bindAI(){bindForm('#product-ai-form',async data=>{const kind=isTerminal()?'advanced':'basic',id=requestId();const result=await api('product-ai',{method:'POST',body:{requestId:id,question:data.question,kind,...(selectedPortfolioId?{portfolioId:selectedPortfolioId}:{}),...(selectedInstrument?{instrumentId:selectedInstrument.id}:{})}});aiAnswer=result;await refreshSnapshot();renderWorkspace();});}
async function loadContext(){if(!isTerminal()&&!selectedInstrument&&summary?.holdings?.length)selectedInstrument=summary.holdings[0].instrument;newsSymbol=selectedInstrument?.symbol||'';const results=await Promise.allSettled([api('product-news',{params:selectedInstrument?.symbol?{symbol:selectedInstrument.symbol}:{}}),api('product-calendar')]);if(results[0].status==='fulfilled')news=results[0].value.items||[];if(results[1].status==='fulfilled')events=results[1].value.events||[];await loadReminders();}

function currentConnection(){return (brokerStatus?.connections||snapshot?.broker?.connections||[]).find(connection=>connection.status==='connected')||(brokerStatus?.connections||snapshot?.broker?.connections||[])[0]||null;}
function executionLabel(){if(terminalMode==='sample')return L('Sample replay · read-only','Eksempelavspilling · skrivebeskyttet');const connection=currentConnection();if(!connection)return L('Market data · no execution account','Markedsdata · ingen utførelseskonto');return connection.mode==='live'?L('Connected live brokerage','Tilkoblet megler med ekte penger'):L('Market data · paper execution','Markedsdata · papirhandel');}
const terminalIcon=name=>`<svg class="icon-svg" aria-hidden="true" focusable="false"><use href="/terminal/icons.svg#${name}"></use></svg>`;
const terminalButton=(label,action,icon='',cls='',attrs='')=>button(`${icon?terminalIcon(icon):''}${label}`,action,cls,attrs);
const terminalIconButton=(label,action,icon,attrs='')=>terminalButton('',action,icon,'icon',`aria-label="${esc(label)}" title="${esc(label)}" ${attrs}`);
const terminalPercent=value=>new Intl.NumberFormat(locale==='nb'?'nb-NO':'en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(value));
function terminalTime(value){try{return new Intl.DateTimeFormat(locale==='nb'?'nb-NO':'en-GB',{hour:'2-digit',minute:'2-digit'}).format(new Date(typeof value==='number'&&value<1e12?value*1000:value));}catch{return '—';}}
function terminalDay(value){try{return new Intl.DateTimeFormat(locale==='nb'?'nb-NO':'en-GB',{day:'numeric',month:'short'}).format(new Date(typeof value==='number'&&value<1e12?value*1000:value));}catch{return '—';}}
const terminalTitles=()=>({overview:L('Overview','Oversikt'),markets:L('Markets','Markeder'),trade:L('Trade','Handle'),bots:L('Trading bots','Handelsroboter'),strategy:L('Strategies','Strategier'),research:L('Research','Analyse'),news:L('News','Nyheter'),calendar:L('Calendar','Kalender'),analytics:L('Analytics','Statistikk'),reports:L('Reports','Rapporter')});
function terminalNav(v,ic,label){return terminalButton(`<span>${label}</span>`,'terminal-view',ic,`navlink ${terminalView===v?'active':''}`,`data-view="${v}" ${terminalView===v?'aria-current="page"':''}`);}
function prepareTerminalEntryIntent(){if(terminalIntentPrepared)return;terminalIntentPrepared=true;const query=new URLSearchParams(location.search);intent={...intent,locale,...(!query.has('tier')?{tier:'pro'}:{}),...(!query.has('returnPath')&&!query.has('returnTo')?{returnPath:path('terminal')}:{})};}
function renderTerminalEntry(){prepareTerminalEntryIntent();surface='workspace';root.classList.remove('p-price-page');root.classList.add('p-terminal');destroyChart();document.title=L('Get started · Nortivo Terminal','Kom i gang · Nortivo Terminal');syncPageLocale();root.innerHTML=`<div class="pt-terminal-shell pt-entry-shell"><header class="appbar"><a class="brand" href="/${locale}/">NORTIVO</a><span class="pt-entry-product">Terminal Pro</span><nav class="pt-entry-nav" aria-label="${L('Account navigation','Kontonavigasjon')}"><a href="${path('pricing')}">${L('View plans','Se abonnementer')}</a>${button(locale==='nb'?'EN':'NO','language','',`aria-label="${L('Switch to Norwegian','Bytt til engelsk')}"`)}${button(L('Log in','Logg inn'),'login')}</nav></header><main class="pt-entry" id="workspace" tabindex="-1"><section class="pt-entry-panel" aria-labelledby="terminal-entry-title"><div class="pt-entry-main"><div class="pt-entry-mark" aria-hidden="true">${terminalIcon('chart-candle')}</div><h1 id="terminal-entry-title">${L('Start with your Nortivo account.','Start med Nortivo-kontoen din.')}</h1><p class="pt-entry-lead">${L('Create a free account or log in to open your own trading workspace.','Opprett en gratis konto eller logg inn for å åpne ditt eget handelsarbeidsområde.')}</p><div class="pt-entry-actions">${terminalButton(canRegister()?L('Create account','Opprett konto'):L('Registration unavailable','Registrering utilgjengelig'),'signup','user','primary',!canRegister()?'disabled':'')}${terminalButton(L('Log in','Logg inn'),'login')}</div><p class="pt-entry-access">${L('An account keeps your records private. Paid tools require an eligible subscription and available provider connections. Creating an account never starts trading.','Kontoen holder registreringene dine private. Betalte verktøy krever riktig abonnement og tilgjengelige leverandørtilkoblinger. Kontoopprettelse starter aldri handel.')}</p></div><aside class="pt-entry-next" aria-label="${L('Getting started','Slik kommer du i gang')}"><h2>${L('Your next steps','Neste steg')}</h2><ol><li><span>${terminalIcon('user')}</span><div><strong>${L('Create your account','Opprett kontoen din')}</strong><p>${L('Free registration and email verification.','Gratis registrering og bekreftelse på e-post.')}</p></div></li><li><span>${terminalIcon('stack-2')}</span><div><strong>${L('Choose your workspace','Velg arbeidsområde')}</strong><p>${L('Compare Portfolio and Terminal Pro.','Sammenlign Portfolio og Terminal Pro.')}</p></div></li><li><span>${terminalIcon('shield-check')}</span><div><strong>${L('Stay in control','Behold kontrollen')}</strong><p>${L('Broker access and automation need separate approval.','Meglertilgang og automatisering krever egen godkjenning.')}</p></div></li></ol></aside></section><section class="pt-entry-demo" aria-labelledby="terminal-demo-title"><div><h2 id="terminal-demo-title">${L('Want to look around first?','Vil du se deg rundt først?')}</h2><p>${L('Explore the terminal with fixed fictional prices. The demo is read-only and cannot trade.','Utforsk terminalen med faste fiktive kurser. Demoen er skrivebeskyttet og kan ikke handle.')}</p></div>${terminalButton(L('Explore read-only demo','Utforsk skrivebeskyttet demo'),'mode-sample','eye')}</section><footer class="pt-entry-footer"><a href="/${locale}/support/">${L('Need help? Contact support','Trenger du hjelp? Kontakt kundestøtte')}</a><a href="/${locale}/privacy/">${L('Privacy','Personvern')}</a><a href="/${locale}/">Nortivo.no</a></footer></main></div><div id="product-toast" class="p-toast" role="status" aria-live="polite"></div>`;}
function terminalVerificationNotice(){if(terminalMode==='sample'||!user()||user().emailVerified)return '';return `<aside class="pt-verification-note" aria-label="${L('Verify your account','Bekreft kontoen din')}"><span>${terminalIcon('info-circle')}</span><div><strong>${L('Verify your email to continue','Bekreft e-posten for å fortsette')}</strong><p>${L('Use the link in your email before saving private records or starting a paid workspace.','Bruk lenken du fikk på e-post før du lagrer private registreringer eller starter et betalt arbeidsområde.')}</p></div>${button(L('Verify email','Bekreft e-post'),'verification')}</aside>`;}
function terminalHeader(){return `<header class="appbar"><a class="brand" href="/${locale}/" aria-label="Nortivo ${L('home','forside')}">NORTIVO</a>${productSwitcher('terminal')}${terminalButton(`<span>${L('Find an instrument','Finn et instrument')}</span><kbd>/</kbd>`,'terminal-search','search','search-trigger',`aria-label="${L('Search instruments','Søk etter instrumenter')}"`)}${terminalButton(`<span>${L('Connections','Tilkoblinger')}</span>`,'integration-status','activity','pt-connection-button',`aria-label="${L('Connections','Tilkoblinger')}"`)}${terminalButton(esc((user()?.name||user()?.email||'N').slice(0,1).toUpperCase()),user()?'account':'login','','profile',`aria-label="${user()?L('Account settings','Kontoinnstillinger'):L('Log in','Logg inn')}"`)}</header>`;}
function terminalSidebar(){const t=terminalTitles(),group=(label,items)=>`<div class="pt-sidebar-group"><p class="pt-sidebar-label">${label}</p>${items.map(([v,i])=>terminalNav(v,i,t[v])).join('')}</div>`;return `<aside class="sidebar"><nav aria-label="${L('Trading workspace','Handelsarbeidsområde')}">${group(L('Workspace','Arbeidsområde'),[['overview','home'],['markets','chart-candle'],['trade','activity']])}${group(L('Automation','Automatisering'),[['bots','robot'],['strategy','stack-2']])}${group(L('Intelligence','Innsikt'),[['research','file-search'],['news','news'],['calendar','calendar-event']])}${group(L('Records','Registreringer'),[['analytics','chart-histogram'],['reports','chart-bar']])}</nav>${terminalButton(`<span>${L('Settings','Innstillinger')}</span>`,user()?'account':'login','settings','navlink settings')}</aside>`;}
function terminalModebar(){const sample=terminalMode==='sample',c=currentConnection();return `<div class="modebar pt-modebar"><div class="pt-context"><span class="badge ${sample?'amber':''}">${sample?L('Sample data','Eksempeldata'):L('Provider data','Leverandørdata')}</span><span>${sample?L('Read-only','Skrivebeskyttet'):c?c.mode==='live'?L('Live brokerage','Megler med ekte penger'):L('Paper brokerage','Papirhandel'):L('No brokerage connected','Ingen megler tilkoblet')}</span>${!sample?`<span class="p-status" data-state="${dataState(snapshot?.readiness?.market,pro())}">${rawStateName(dataState(snapshot?.readiness?.market,pro()))}</span>`:''}</div><div class="pt-mode-actions"><div role="group" aria-label="${L('Data mode','Datamodus')}">${button(L('Provider','Leverandør'),'mode-provider',!sample?'selected':'',`aria-pressed="${!sample}"`)}${button(L('Sample','Eksempel'),'mode-sample',sample?'selected':'',`aria-pressed="${sample}"`)}</div>${terminalIconButton(L('Refresh workspace','Oppdater arbeidsområdet'),'refresh-terminal','refresh')}${!user()&&sample?button(canRegister()?L('Create account','Opprett konto'):L('Log in','Logg inn'),canRegister()?'signup':'login','primary'):''}</div></div>`;}
function terminalKpis(){const sample=terminalMode==='sample',a=sample?sampleState?.account:null,c=currentConnection(),b=!sample?c?.balances:null,r=sample?sampleState?.regime:null;const value=sample&&a?money(String(a.equityMinor/100),'USD'):b?.equity!==undefined?money(b.equity,b.currency):'—';const card=(label,value,sub,cls='')=>`<div class="panel kpi ${cls}"><span class="kpi-label">${label}</span><strong class="kpi-value number">${value}</strong><span class="kpi-sub muted">${sub}</span></div>`;return `<section class="kpis" aria-label="${L('Your execution account','Utførelseskontoen din')}">${card(sample?L('Sample portfolio value','Eksempelporteføljens verdi'):L('Broker portfolio value','Meglerporteføljens verdi'),value,sample?L('Virtual USD ledger','Virtuell USD-hovedbok'):b?L('Broker-synchronized equity','Meglersynkronisert egenkapital'):L('Connect an eligible account','Koble til en kvalifisert konto'),'pt-equity')}${card(L('Win rate','Treffprosent'),a?.winRate!=null?decimal(a.winRate)+'%':'—',L('Closed account trades','Lukkede handler på kontoen'))}${card(L('Profit factor','Profittfaktor'),a?.profitFactor!=null?decimal(a.profitFactor):'—',L('Realized gains / losses','Realiserte gevinster / tap'))}${card(sample?L('Unrealized P&L','Urealisert resultat'):L('Available cash','Tilgjengelige kontanter'),sample&&a?money(String(a.unrealizedPnlMinor/100),'USD'):b?.cash!==undefined?money(b.cash,b.currency):'—',sample?L('Open virtual positions','Åpne virtuelle posisjoner'):L('At connected broker','Hos tilkoblet megler'),sample&&a?.unrealizedPnlMinor>0?'positive':sample&&a?.unrealizedPnlMinor<0?'negative':'')}${card(L('Completed trades','Fullførte handler'),a?.completedTrades!==undefined?decimal(a.completedTrades):'—',sample?L('Sample account only','Kun eksempelkonto'):L('This execution account','Denne utførelseskontoen'))}<div class="panel kpi kpi-regime"><div class="regime-icon">${terminalIcon('activity')}</div><div><span class="kpi-label">${L('Market regime','Markedstilstand')}</span><strong class="kpi-value ${r?.label==='bullish'?'positive':''}">${r?({bullish:L('Bullish','Stigende'),bearish:L('Bearish','Fallende'),mixed:L('Mixed','Blandet')})[r.label]||esc(r.label):L('Awaiting data','Venter på data')}</strong><span class="kpi-sub muted">${r?L('Sample price breadth','Eksempelets kursbredde'):L('No inferred AI signal','Intet utledet KI-signal')}</span></div></div></section>`;}
function terminalTrendPanel(){const r=terminalMode==='sample'?sampleState?.regime:null,score=r?.total?Math.round(r.advancing/r.total*100):null;return `<section class="panel pt-trend-panel"><div class="panel-heading"><h2>${L('Market breadth','Markedsbredde')}</h2>${terminalIconButton(L('Data sources','Datakilder'),'integration-status','info-circle')}</div><div class="trend"><div class="trend-score"><strong class="number">${score===null?'—':score+'%'}</strong><span>${L('advancing','stigende')}</span></div><div class="trend-factors"><div class="trend-factor"><span>${L('Universe','Utvalg')}</span><strong>${r?.total??'—'}</strong></div><div class="trend-factor"><span>${L('Advancing','Stigende')}</span><strong class="positive">${r?.advancing??'—'}</strong></div><div class="trend-factor"><span>${L('Declining','Fallende')}</span><strong>${r?r.total-r.advancing:'—'}</strong></div><small class="muted">${r?L('Sample · previous close','Eksempel · forrige sluttkurs'):L('Licensed coverage required','Krever lisensiert dekning')}</small></div></div></section>`;}
function terminalCompanyReport(){const r=terminalReport,sign=value=>Number(value)>0?'+':'',tone=value=>Number(value)>0?'positive':Number(value)<0?'negative':'';return `<section class="panel pt-report"><div class="panel-heading"><h2>${terminalIcon('chart-bar')}${L('Company history · 2026','Selskapshistorikk · 2026')}</h2><a class="pt-icon-link" href="/${locale}/report-2026/" aria-label="${L('Full company report','Full selskapsrapport')}">${terminalIcon('arrow-up-right')}</a></div>${r?`<div class="report-summary"><p class="p-source">${L('Nortivo · NOK · 2 Jan–17 Nov 2026','Nortivo · NOK · 2. jan.–17. nov. 2026')}</p><div class="report-return number ${tone(r.returnOnOpeningEquityPercent)}">${sign(r.returnOnOpeningEquityPercent)}${decimal(r.returnOnOpeningEquityPercent)}%</div><p class="p-meta">${L('Return on opening equity','Avkastning på inngående egenkapital')}</p><div class="report-row"><span>${L('Trading P&L','Handelsresultat')}</span><span class="number">${money(String(r.profitOre/100),'NOK')}</span></div><div class="report-row"><span>${L('Sessions / trades','Økter / handler')}</span><span class="number">${decimal(r.sessions)} / ${decimal(r.trades)}</span></div><div class="report-row"><span>${L('Avg. session return on deployed capital','Snittavkastning per økt på anvendt kapital')}</span><span class="number ${tone(r.averageDeployedDailyPercent)}">${sign(r.averageDeployedDailyPercent)}${decimal(r.averageDeployedDailyPercent)}%</span></div><div class="report-row"><span>${L('Maximum drawdown','Største verdifall')}</span><span class="number negative">${decimal(r.maxDrawdownPercent)}%</span></div><p class="report-footnote">${L('Historical company results, separate from your account and from returns on total account equity per day.','Historiske selskapsresultater, adskilt fra kontoen din og fra daglig avkastning på samlet egenkapital.')} <a href="/${locale}/report-2026/">${L('Full report, risk & method','Full rapport, risiko og metode')}</a></p></div>`:`<div class="pt-empty"><p>${L('Company report unavailable','Selskapsrapport utilgjengelig')}</p><a href="/${locale}/report-2026/">${L('Open report','Åpne rapport')}</a></div>`}</section>`;}
async function loadTerminalReport(){if(terminalReport||terminalReportLoading)return;terminalReportLoading=true;try{const response=await fetch('/report-2026/summary.json',{credentials:'omit'});if(!response.ok)return;const data=await response.json();if(Number.isFinite(data.profitOre)&&Number.isFinite(data.returnOnOpeningEquityPercent))terminalReport=data;if(surface==='workspace'&&isTerminal()&&!dialog?.open)renderTerminal();}catch{}finally{terminalReportLoading=false;}}
function terminalResearchPanel(){const eligible=pro(),state=dataState(snapshot?.readiness?.market,eligible),available=['current','delayed','closed'].includes(state);return panel(L('Test a strategy','Test en strategi'),`<p class="p-meta">${L('Review historical rules and explicit trading costs before comparing results. A backtest is separate from live account performance.','Kontroller historiske regler og uttrykkelige handelskostnader før du sammenligner resultater. En historisk test er adskilt fra faktisk kontoavkastning.')}</p><div class="p-actions">${button(L('Run backtest','Kjør historisk test'),'backtest','',!eligible||!available?'disabled':'')}${button(L('Scan markets','Skann markeder'),'scan','',!eligible||!available?'disabled':'')}</div>${!available?unavailable('market',eligible):''}<div id="research-result" aria-live="polite"></div>`);}
function terminalPage(){if(terminalMode==='sample'&&terminalView!=='overview')return terminalSamplePage();if(terminalView==='overview')return `<div class="main-grid"><div class="left-column">${marketListPanel()}${terminalTrendPanel()}</div>${productionChartPanel()}<div class="right-column">${terminalNewsPanel()}${terminalCalendarPanel()}</div></div><div class="bottom-grid">${terminalEnginePanel()}${terminalSignalPanel()}${terminalRiskPanel()}${terminalCompanyReport()}</div>`;const titles=terminalTitles(),descriptions={markets:L('Your instrument list and chart, with source and timestamp.','Instrumentlisten og grafen din, med kilde og tidspunkt.'),trade:L('Review positions, execution requests and account risk in one place.','Se posisjoner, ordreforespørsler og kontorisiko på ett sted.'),bots:L('Manage the process that runs your saved strategy rules.','Administrer prosessen som kjører de lagrede strategireglene dine.'),strategy:L('Define, review and test rules before enabling execution.','Definer, vurder og test regler før utførelse aktiveres.'),research:L('Ask a question with your selected instrument and current evidence in context.','Still et spørsmål med valgt instrument og gjeldende grunnlag i kontekst.'),news:L('Publisher reporting, with original sources and publication times.','Utgivernes journalistikk, med originalkilder og publiseringstidspunkter.'),calendar:L('Scheduled events, releases and your in-app reminders.','Planlagte hendelser, publiseringer og påminnelsene dine i appen.'),analytics:L('Account results require a complete, dated record.','Kontoresultater krever en fullstendig, datert historikk.'),reports:L('Find your records and Nortivo’s separate historical report.','Finn registreringene dine og Nortivos adskilte historiske rapport.')};let body='',actions='';switch(terminalView){case'markets':body=`<div class="pt-market-page">${marketListPanel()}${productionChartPanel()}</div>`;actions=terminalButton(L('Find instrument','Finn instrument'),'terminal-search','search');break;case'trade':body=`<div class="pt-reading-layout"><div class="p-stack">${productionChartPanel()}${terminalPositionsPanel()}</div><aside class="p-stack">${ordersPanel()}${riskConnectionPanel()}</aside></div>`;actions=terminalButton(L('New order','Ny ordre'),'broker-order','plus','primary',!selectedInstrument||!connectionCanTrade()?'disabled':'');break;case'bots':body=`<div class="pt-workspace-grid"><div class="p-stack">${terminalEnginePanel()}${riskConnectionPanel()}</div>${panel(L('Automation checklist','Sjekkliste for automatisering'),`<ol class="pt-source-list"><li>${L('Connect an eligible paper or live broker account.','Koble til en kvalifisert konto for papirhandel eller ekte handel.')}</li><li>${L('Save and review a strategy in Strategies.','Lagre og kontroller en strategi under Strategier.')}</li><li>${L('Confirm account limits and explicit automation consent.','Bekreft kontogrenser og uttrykkelig samtykke til automatisering.')}</li><li>${L('Enable only when the data and engine connection are ready.','Aktiver først når data- og motortilkoblingen er klar.')}</li></ol><p class="p-meta">${L('Stopping prevents new entries. Existing broker orders and protective stops remain at the broker.','Stopp hindrer nye innganger. Eksisterende meglerordrer og beskyttelsesordrer forblir hos megleren.')}</p>${terminalButton(L('Review strategies','Se strategier'),'terminal-view','stack-2','',`data-view="strategy"`)}`)}</div>`;break;case'strategy':body=`<div class="pt-workspace-grid">${terminalStrategiesPanel()}<div class="p-stack">${terminalResearchPanel()}${terminalSignalPanel()}</div></div>`;break;case'research':body=`<div class="pt-reading-layout"><div class="p-stack">${aiPanel(true)}</div><aside class="p-stack">${terminalResearchContext()}${terminalResearchPanel()}${terminalSignalPanel()}</aside></div>`;break;case'news':body=`<div class="pt-reading">${newsPanel(false)}</div>`;break;case'calendar':body=`<div class="pt-reading-layout">${calendarPanel(false)}${panel(L('Your reminders','Påminnelsene dine'),remindersPanel())}</div>`;break;case'analytics':body=`<div class="pt-workspace-grid">${terminalAnalyticsPanel()}<div class="p-stack">${terminalPositionsPanel()}${terminalRiskPanel()}</div></div>`;break;case'reports':body=`<div class="pt-report-grid">${terminalRecordsPanel()}${terminalCompanyReport()}</div>`;break;}return terminalScreen(titles[terminalView]||titles.overview,descriptions[terminalView]||'',body,actions);}
function renderTerminal(){if(!user()&&terminalMode!=='sample'){renderTerminalEntry();return;}const focused=root.contains(document.activeElement)?document.activeElement:null,focusData=focused?.dataset?{...focused.dataset}:null;surface='workspace';root.classList.remove('p-price-page');root.classList.add('p-terminal');destroyChart();document.title=`${terminalTitles()[terminalView]||'Terminal Pro'} · Nortivo`;syncPageLocale();const t=terminalTitles();root.innerHTML=`<div class="pt-terminal-shell">${terminalHeader()}<div class="layout">${terminalSidebar()}<main class="workspace" id="workspace" tabindex="-1">${terminalModebar()}${terminalVerificationNotice()}${terminalView==='overview'?`<h1 class="sr-only">${L('Terminal overview','Terminaloversikt')}</h1>${terminalKpis()}`:terminalAccountSummary()}<nav class="mobile-tabs" aria-label="${L('Trading tools','Handelsverktøy')}">${Object.keys(t).map(v=>terminalButton(t[v],'terminal-view','',terminalView===v?'active':'',`data-view="${v}" ${terminalView===v?'aria-current="page"':''}`)).join('')}${terminalButton(L('Settings','Innstillinger'),user()?'account':'login','settings')}</nav>${terminalPage()}<footer class="statusbar"><span>${terminalMode==='sample'?`${L('Fixed fictional sample','Fast fiktivt eksempel')} · ${date(sampleState?.replay?.asOf)}`:executionLabel()}</span><span><a href="/${locale}/support/">${L('Support','Kundestøtte')}</a> · <a href="/${locale}/privacy/">${L('Privacy','Personvern')}</a></span></footer></main></div></div><div id="product-toast" class="p-toast" role="status" aria-live="polite"></div>`;mountChart();bindAI();if(focusData?.product)[...root.querySelectorAll('[data-product]')].find(node=>Object.entries(focusData).every(([key,value])=>node.dataset[key]===value))?.focus({preventScroll:true});}
function marketListPanel(){const sample=terminalMode==='sample',instruments=sample?(sampleState?.catalog||[]).map(item=>({...item,id:item.symbol,venue:'SAMPLE',currency:'USD'})):watchlist;return `<section class="panel pt-watchlist"><div class="panel-heading"><h2>${L('Watchlist','Overvåkingsliste')}</h2><div class="heading-actions">${terminalIconButton(L('Find an instrument','Finn et instrument'),'terminal-search','plus')}${selectedInstrument&&!sample?terminalIconButton(L('Add selected instrument','Legg til valgt instrument'),'watchlist-add','list'):''}</div></div><div class="segmented">${terminalButton(L('My list','Min liste'),'terminal-view','','selected',`data-view="overview"`)}${terminalButton(L('Markets','Markeder'),'terminal-search')}</div><div class="table-wrap"><table class="watch-table"><thead><tr><th>${L('Symbol','Symbol')}</th><th class="right">${L('Price','Kurs')}</th><th class="right">% ${L('Chg','Endr.')}</th></tr></thead><tbody>${instruments.map(item=>{const quote=sample?sampleState?.markets?.[item.symbol]?.quote:item.id===selectedInstrument?.id?marketData?.quote:null,price=sample&&quote?String(quote.priceMinor/100):quote?.price,change=quote?.changePercent;return `<tr class="${item.symbol===selectedInstrument?.symbol?'selected':''}"><td>${terminalButton(`<span class="pt-symbol-icon">${terminalIcon('chart-candle')}</span><span>${esc(item.symbol)}</span>`,'market-select','','pt-watch-symbol',`data-instrument="${esc(item.id)}" title="${esc(item.name||item.symbol)} · ${esc(item.venue)}"`)}</td><td class="right number">${price!==undefined?decimal(price):'—'}</td><td class="right number ${change>0?'positive':change<0?'negative':''}">${change!==undefined?`${change>0?'+':''}${terminalPercent(change)}%`:'—'}</td></tr>`;}).join('')}</tbody></table>${!instruments.length?`<div class="pt-compact-empty"><strong>${L('Your markets, in one list','Markedene dine, i én liste')}</strong><p>${L('Find an exact instrument and venue to build your watchlist.','Finn riktig instrument og handelsplass for å bygge listen.')}</p>${terminalButton(L('Find instrument','Finn instrument'),'terminal-search','plus')}</div>`:''}</div>${!sample?`<div class="pt-watch-footer">${selectedInstrument?`<span>${esc(selectedInstrument.symbol)} · ${esc(selectedInstrument.venue)}</span>${terminalIconButton(L('Remove selected instrument','Fjern valgt instrument'),'watchlist-remove','trash',`data-instrument="${esc(selectedInstrument.id)}"`)}`:`<span>${L('Prices require licensed coverage','Kurser krever lisensiert dekning')}</span>`}</div>`:''}</section>`;}

function chartMarket(){if(terminalMode==='sample'){const symbol=selectedInstrument?.symbol||sampleState?.watchlist?.[0];return sampleState?.markets?.[symbol]||null;}if(!marketData?.quote||!marketData?.bars?.length)return null;const quote=marketData.quote;const bars=marketData.bars.map(bar=>({time:bar.time,open:Number(bar.open)*100000000,high:Number(bar.high)*100000000,low:Number(bar.low)*100000000,close:Number(bar.close)*100000000,volume:Number(bar.volume)}));return {symbol:quote.symbol,currency:quote.currency,priceScale:100000000,priceDecimals:Math.min(8,Math.max(2,(String(quote.price).split('.')[1]||'').length)),name:selectedInstrument?.name||quote.symbol,quote:{priceMinor:Number(quote.price)*100000000,asOf:quote.asOf},bars,...{[({'1m':'bars','5m':'bars5m','15m':'bars15m','1h':'bars1h','4h':'bars4h','1d':'bars1d'})[resolution]||'bars']:bars}};}
function terminalEnginePanel(){const sample=terminalMode==='sample',c=sample?null:currentConnection(),worker=dataState(snapshot?.readiness?.worker,pro()),running=!!(!sample&&c?.automationEnabled&&worker==='current'),text=sample?L('Read-only sample','Skrivebeskyttet eksempel'):running?L('Running','Kjører'):c?.automationEnabled?L('Waiting for connection','Venter på tilkobling'):L('Stopped','Stanset');return `<section class="panel pt-engine"><div class="panel-heading"><h2>${terminalIcon('robot')}${L('Trading engine','Handelsmotor')}</h2><span class="badge ${running?'positive':''}">${text}</span></div><div class="engine-layout"><div class="engine-steps">${[[L('Market data','Markedsdata'),sample?L('Fixed replay','Fast avspilling'):rawStateName(dataState(snapshot?.readiness?.market,pro()))],[L('Saved strategies','Lagrede strategier'),sample?L('Example rules','Eksempelregler'):String(strategies.length)],[L('Risk limits','Risikogrenser'),sample?L('Example limits','Eksempelgrenser'):c?.risk?L('Configured','Angitt'):L('Not set','Ikke angitt')],[L('Execution','Utførelse'),sample?L('Disabled','Deaktivert'):c?.mode||L('Not connected','Ikke tilkoblet')]].map(([label,value])=>`<div class="engine-step"><span>${label}</span><strong>${esc(value)}</strong></div>`).join('')}</div></div><div class="engine-controls">${terminalButton(L('Manage bots','Administrer roboter'),'terminal-view','robot','',`data-view="bots"`)}${sample?'':terminalButton(L('Enable','Aktiver'),'automation-consent','player-play','primary',!pro()||!c?'disabled':'')}${!sample&&c?terminalButton(L('Stop','Stopp'),'broker-stop','player-stop'):''}</div><p class="engine-description">${sample?L('Explore the example without starting a process or placing orders.','Utforsk eksempelet uten å starte en prosess eller legge inn ordrer.'):L('Review strategy rules, account limits and consent before enabling automation.','Kontroller strategiregler, kontogrenser og samtykke før automatisering aktiveres.')}</p></section>`;}
function terminalSignalPanel(){const signals=terminalMode==='sample'?(sampleState?.signals||[]):[],s=[...signals].reverse().find(item=>item.symbol===selectedInstrument?.symbol)||null;return `<section class="panel pt-signal"><div class="panel-heading"><h2>${terminalIcon('activity')}${L('Signal details','Signaldetaljer')}</h2><span class="muted tiny">${s?date(s.time):'—'}</span></div>${s?`<div class="signal-content"><div><strong>${esc(s.symbol)} · ${esc(s.decision||'')}</strong>${[[L('Reference','Referanse'),s.priceMinor!==undefined?money(String(s.priceMinor/100),'USD'):'—'],[L('Quantity','Antall'),s.quantity??'—'],[L('Target','Mål'),s.takeProfitMinor?money(String(s.takeProfitMinor/100),'USD'):'—'],[L('Stop','Stopp'),s.stopLossMinor?money(String(s.stopLossMinor/100),'USD'):'—']].map(([label,value])=>`<div class="signal-price-row"><span>${label}</span><span class="number">${value}</span></div>`).join('')}</div><div class="signal-rules">${(s.conditions||[]).filter(item=>item.enabled!==false).slice(0,4).map(item=>`<div class="signal-condition">${terminalIcon(item.met?'circle-check':'info-circle')}<span>${esc(item.label||item.id)}</span></div>`).join('')}<small class="muted">${L('Fixed sample evidence','Fast eksempelgrunnlag')}</small></div></div>`:`<div class="pt-compact-empty"><strong>${L('No evaluated signal','Ingen vurderte signaler')}</strong><p>${L('A signal needs a saved strategy and current, permitted market data.','Et signal trenger en lagret strategi og tillatte, oppdaterte markedsdata.')}</p>${terminalButton(L('Open research','Åpne analyse'),'terminal-view','file-search','',`data-view="research"`)}</div>`}</section>`;}
function terminalRiskPanel(){const sample=terminalMode==='sample',c=sample?null:currentConnection(),risk=c?.risk,sr=sample?sampleState?.risk:null,a=sample?sampleState?.account:null;const sampleRows=sr&&a?[[L('Portfolio exposure','Porteføljeeksponering'),a.equityMinor?Math.max(0,(a.equityMinor-a.cashMinor)/a.equityMinor*100):0],[L('Daily loss limit used','Daglig tapsgrense brukt'),sr.maxDailyLossMinor?Math.min(100,Math.max(0,-sr.dailyPnlMinor/sr.maxDailyLossMinor*100)):0],[L('Max. position size','Maks. posisjonsstørrelse'),sr.maxPositionBps/100]]:[];return `<section class="panel pt-risk"><div class="panel-heading"><h2>${terminalIcon('shield-check')}${L('Risk management','Risikostyring')}</h2>${sample?'':terminalIconButton(L('Broker and risk settings','Megler og risikoinnstillinger'),'broker','settings')}</div>${sample?`<div class="risk-lines">${sampleRows.map(([label,value])=>`<div class="risk-line"><span>${label}</span><progress class="risk-progress" max="100" value="${Math.min(100,Math.max(0,value))}" aria-label="${label}"></progress><span class="number">${terminalPercent(value)}%</span></div>`).join('')||`<p class="p-meta">${L('No sample risk values','Ingen eksempelrisikoverdier')}</p>`}</div><div class="risk-footer">${terminalIcon('info-circle')}${L('Sample account limits · read-only','Eksempelkontoens grenser · skrivebeskyttet')}</div>`:`<div class="pt-risk-values">${[[L('Max. order value','Maks. ordreverdi'),risk?.maxOrderNotional],[L('Max. position value','Maks. posisjonsverdi'),risk?.maxPositionNotional],[L('Daily loss limit','Daglig tapsgrense'),risk?.maxDailyLoss]].map(([label,value])=>`<div><span>${label}</span><strong class="number">${value!==undefined?money(value,'USD'):'—'}</strong></div>`).join('')}<div><span>${L('Orders per day','Ordrer per dag')}</span><strong class="number">${risk?.maxOrdersPerDay??'—'}</strong></div></div><div class="risk-footer ${risk?'':'amber'}">${terminalIcon(risk?'shield-check':'info-circle')}${risk?L('Limits checked before new orders','Grenser kontrolleres før nye ordrer'):L('Connect account and confirm limits','Koble til konto og bekreft grenser')}</div>`}</section>`;}
function terminalSamplePage(){const t=terminalTitles(),copy={markets:L('Explore fixed sample instruments and their recorded price history.','Utforsk faste eksempelinstrumenter og registrert kurshistorikk.'),trade:L('Inspect virtual positions and recorded orders without placing a trade.','Se virtuelle posisjoner og registrerte ordrer uten å handle.'),bots:L('See how a trading engine separates data, rules, risk and execution.','Se hvordan en handelsmotor skiller data, regler, risiko og utførelse.'),strategy:L('Read the rules used by the example replay.','Les reglene som brukes i eksempelavspillingen.'),research:L('Understand the selected instrument and the limits of this sample.','Forstå det valgte instrumentet og begrensningene i eksempelet.'),news:L('Fictional stories illustrate a source-led reading experience.','Fiktive saker viser en leseopplevelse med tydelige kilder.'),calendar:L('Fixed fictional events, shown in your local timezone.','Faste fiktive hendelser, vist i din lokale tidssone.'),analytics:L('Only recorded virtual activity contributes to these metrics.','Kun registrert virtuell aktivitet inngår i disse målene.'),reports:L('Sample account records and company history, clearly separated.','Eksempelkontoens registreringer og selskapshistorikk, tydelig adskilt.')};let body='';switch(terminalView){case'markets':body=`<div class="pt-market-page">${marketListPanel()}${productionChartPanel()}</div>`;break;case'trade':body=`<div class="pt-reading-layout"><div class="p-stack">${productionChartPanel()}${terminalPositionsPanel(true)}</div><aside class="p-stack">${panel(L('Recorded sample orders','Registrerte eksempelordrer'),sampleOrdersTable())}${terminalRiskPanel()}</aside></div>`;break;case'bots':body=`<div class="pt-workspace-grid">${terminalEnginePanel()}${panel(L('Execution model','Utførelsesmodell'),`<dl class="p-detail"><div><dt>${L('Mode','Modus')}</dt><dd>${L('Read-only replay','Skrivebeskyttet avspilling')}</dd></div><div><dt>${L('Broker connection','Meglertilkobling')}</dt><dd>${L('None','Ingen')}</dd></div></dl><p>${L('The example describes paper execution on a later eligible candle, including adverse slippage and fees. It does not reproduce real exchange liquidity.','Eksempelet beskriver papirutførelse ved et senere kvalifisert kurspunkt, med negativ kursglidning og gebyrer. Det gjenskaper ikke faktisk børslikviditet.')}</p><details><summary>${L('Model details','Modelldetaljer')}</summary><dl class="p-detail">${['fillTiming','fee','liquidity'].map(k=>`<div><dt>${esc(k==='fillTiming'?L('Fill timing','Utførelsestid'):k==='fee'?L('Fees','Gebyrer'):L('Liquidity','Likviditet'))}</dt><dd>${esc(sampleState?.executionModel?.[k]||'—')}</dd></div>`).join('')}</dl></details>`)}</div>`;break;case'strategy':body=`<div class="pt-workspace-grid">${terminalSampleStrategyPanel()}${terminalSignalPanel()}</div>`;break;case'research':body=`<div class="pt-reading-layout"><div class="p-stack">${terminalResearchContext()}${terminalSignalPanel()}</div>${panel(L('AI explanation','KI-forklaring'),`<div class="pt-empty"><h2>${L('Sample context, without a generated forecast','Eksempelgrunnlag uten en generert prognose')}</h2><p>${L('AI requests are disabled in the read-only sample. The selected instrument, candle interval and recorded rule evidence remain visible alongside this explanation. Switch to provider data to use an available AI connection.','KI-forespørsler er deaktivert i det skrivebeskyttede eksempelet. Det valgte instrumentet, kursintervallet og det registrerte regelgrunnlaget vises sammen med denne forklaringen. Bytt til leverandørdata for å bruke en tilgjengelig KI-tilkobling.')}</p>${button(L('Use provider data','Bruk leverandørdata'),'mode-provider')}</div>`)}</div>`;break;case'news':body=sampleNewsPanel();break;case'calendar':body=sampleCalendarPanel();break;case'analytics':body=`<div class="pt-workspace-grid">${terminalAnalyticsPanel(true)}${terminalRiskPanel()}</div>`;break;case'reports':body=`<div class="pt-report-grid">${terminalRecordsPanel(true)}${terminalCompanyReport()}</div>`;break;}return terminalScreen(t[terminalView],copy[terminalView]||'',body,`<span class="badge amber">${L('Read-only sample','Skrivebeskyttet eksempel')}</span>`);}
function terminalNewsPanel(){const sample=terminalMode==='sample',items=sample?(sampleState?.news||[]):news.filter(item=>!newsSymbol||item.symbols?.includes(newsSymbol));return `<section class="panel"><div class="panel-heading"><h2>${terminalIcon('news')}${L('News intelligence','Nyhetsoversikt')}</h2>${terminalIconButton(L('All news','Alle nyheter'),'terminal-view','arrow-right',`data-view="news"`)}</div><div class="news-filter"><span class="badge ${sample?'amber':''}">${sample?L('Fictional sample','Fiktivt eksempel'):rawStateName(dataState(snapshot?.readiness?.news,pro()))}</span>${terminalButton(L('AI analysis','KI-analyse'),'focus-ai','file-search')}</div><div class="news-list">${items.slice(0,3).map(item=>`<article class="news-item"><div class="news-art">${terminalIcon(item.category==='macro'?'world':item.category==='sector'?'stack-2':'news')}</div><div>${!sample&&safeWebUrl(item.url)?`<a class="news-title" href="${esc(safeWebUrl(item.url))}" target="_blank" rel="noopener noreferrer">${esc(item.title)}</a>`:`<strong class="news-title">${esc(item.title)}</strong>`}<p class="news-time">${sample?L('Fictional','Fiktiv'):esc(item.source)} · ${date(item.publishedAt)}</p></div></article>`).join('')||`<div class="pt-compact-empty"><strong>${L('No current news feed','Ingen oppdatert nyhetsstrøm')}</strong><p>${L('Publisher news appears when a permitted source is connected.','Utgivernes nyheter vises når en tillatt kilde er tilkoblet.')}</p>${button(L('Connection status','Tilkoblingsstatus'),'integration-status')}</div>`}</div></section>`;}
function terminalCalendarPanel(){const sample=terminalMode==='sample',items=sample?sampleState?.calendar||[]:events;return `<section class="panel"><div class="panel-heading"><h2>${terminalIcon('calendar-event')}${L('Economic calendar','Økonomisk kalender')}</h2>${terminalButton(L('View all','Vis alle'),'terminal-view','arrow-right','',`data-view="calendar"`)}</div><div class="calendar-list">${items.slice(0,3).map(item=>`<article class="calendar-event"><time class="number">${new Intl.DateTimeFormat(locale==='nb'?'nb-NO':'en-GB',{hour:'2-digit',minute:'2-digit'}).format(new Date(item.scheduledAt||item.time))}</time><span class="country">${esc(item.country||item.currency||'')}</span><div>${esc(item.title)}<small>${sample?L('Fictional sample','Fiktivt eksempel'):esc(item.importance||'')}</small></div></article>`).join('')||`<div class="pt-compact-empty"><strong>${L('Awaiting calendar connection','Venter på kalendertilkobling')}</strong><p>${L('Scheduled events will appear with their source and local time.','Planlagte hendelser vises med kilde og lokal tid.')}</p></div>`}</div><div class="pt-calendar-source">${sample?L('Fixed fictional events','Faste fiktive hendelser'):esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}</div></section>`;}
function productionChartPanel(){const market=chartMarket(),sample=terminalMode==='sample',quote=sample?market?.quote:marketData?.quote,symbol=selectedInstrument?.symbol||L('Select a market','Velg et marked'),change=quote?.changePercent;return `<section class="panel chart-panel ${terminalChartExpanded?'chart-expanded':''}" id="chart-panel" aria-label="${L('Market chart','Markedsgraf')}"><div class="chart-header"><div class="chart-symbol"><span class="pt-symbol-icon">${terminalIcon('chart-candle')}</span><strong>${esc(symbol)}</strong><span class="chart-company">${esc(selectedInstrument?.name||'')}</span></div><div class="chart-quote"><strong id="product-chart-value" class="chart-price number">${quote?sample?decimal(String(quote.priceMinor/100)):decimal(quote.price):'—'}</strong>${change!==undefined?`<span class="chart-change ${change>0?'positive':change<0?'negative':''}">${change>0?'+':''}${terminalPercent(change)}%</span>`:''}</div><div class="timeframes" role="group" aria-label="${L('Chart timeframe','Grafintervall')}">${['1m','5m','15m','1h','1d'].map(value=>button(value==='1d'?'D':value,'product-timeframe',resolution===value?'selected':'',`data-resolution="${value}" aria-pressed="${resolution===value}"`)).join('')}${terminalIconButton(terminalChartExpanded?L('Collapse chart','Lukk utvidet graf'):L('Expand chart','Utvid grafen'),'terminal-expand-chart','arrows-maximize',`aria-pressed="${terminalChartExpanded}"`)}</div></div><div class="chart-meta"><div class="chart-indicators">${[['ema9','EMA 9'],['ema20','EMA 20'],['vwap','VWAP']].map(([key,label])=>button(label,'chart-indicator',`pt-indicator ${chartIndicators[key]?'selected':''}`,`data-indicator="${key}" aria-pressed="${chartIndicators[key]}"`)).join('')}<span class="muted">${sample?L('Sample replay','Eksempelavspilling'):esc(marketData?.source||L('Awaiting provider','Venter på leverandør'))}</span></div><span>${esc(market?.currency||selectedInstrument?.currency||'USD')}</span></div>${market?`<p class="chart-provenance">${L('As of','Fra')}: ${date(quote.asOf)} · ${sample?L('Fixed fictional sample','Fast fiktivt eksempel'):rawStateName(quote.freshness==='market_closed'?'closed':quote.freshness||'unavailable')}</p><div class="chart-surface"><canvas tabindex="0" role="img" aria-label="${L('Candlestick chart','Lysestakegraf')}"></canvas><div class="chart-tooltip"></div><div class="chart-controls"><button data-chart-action="in" aria-label="${L('Zoom in','Zoom inn')}">+</button><button data-chart-action="out" aria-label="${L('Zoom out','Zoom ut')}">−</button><button data-chart-action="reset">${L('Reset','Tilbakestill')}</button></div></div>`:`<div class="p-chart-empty"><div class="pt-chart-empty-icon">${terminalIcon('chart-candle')}</div><h2>${L('Your next decision starts here','Neste beslutning starter her')}</h2><p>${L('Choose an instrument to open its chart, news and research in one workspace.','Velg et instrument for å samle graf, nyheter og analyse i ett arbeidsområde.')}</p><div class="p-actions">${terminalButton(L('Find instrument','Finn instrument'),'terminal-search','search')}${terminalButton(L('Explore sample','Se eksempel'),'mode-sample','player-play','primary')}</div><span class="p-meta">${rawStateName(dataState(snapshot?.readiness?.market,pro()))} · ${L('No illustrative prices in production','Ingen eksempelkurser i produksjon')}</span></div>`}<div class="chart-footer">${terminalButton(L('Trade','Handle'),'broker-order','adjustments-horizontal','primary',sample||!selectedInstrument||!connectionCanTrade()?'disabled':'')}${terminalButton(L('Signals','Signaler'),'terminal-view','activity','',`data-view="research"`)}${terminalButton(L('AI analysis','KI-analyse'),'focus-ai','file-search')}${terminalButton(L('News','Nyheter'),'terminal-view','news','',`data-view="news"`)}${terminalButton(L('Backtest','Historisk test'),'backtest','chart-histogram','',sample||!pro()?'disabled':'')}${terminalButton(L('Alerts','Varsler'),'reminders-list','bell','',sample?'disabled':'')}${terminalIconButton(L('Chart data','Grafdata'),'terminal-chart-data','list')}</div>${market?`<details class="chart-data"><summary>${L('Recent candles & keyboard guide','Siste kurspunkter og tastaturveiledning')}</summary><p class="p-meta">${L('Arrow keys pan. + / − zoom. Home / End move to first / latest candle.','Piltaster flytter. + / − zoomer. Home / End viser første / siste kurspunkt.')}</p><div class="p-table-wrap" role="region" tabindex="0" aria-label="${L('Scrollable data table','Rullbar datatabell')}">${chartTable(market)}</div></details>`:''}</section>`;}

function chartTable(market){const bars=market[({'1m':'bars','5m':'bars5m','15m':'bars15m','1h':'bars1h','4h':'bars4h','1d':'bars1d'})[resolution]]||market.bars||[];return `<table><caption>${L('Last available completed candles','Siste tilgjengelige fullførte kurspunkter')} · ${esc(market.currency||'USD')}</caption><thead><tr><th>${L('Time','Tid')}</th><th>O</th><th>H</th><th>L</th><th>C</th><th>${L('Volume','Volum')}</th></tr></thead><tbody>${bars.slice(-20).map(bar=>`<tr><td>${date(bar.time)}</td>${[bar.open,bar.high,bar.low,bar.close].map(value=>`<td class="p-mono">${decimal(String(value/(market.priceScale||100)))}</td>`).join('')}<td class="p-mono">${decimal(bar.volume)}</td></tr>`).join('')}</tbody></table>`;}
function mountChart(){destroyChart();const container=el('.chart-surface',root),market=chartMarket();if(!container||!market)return;chart=new MarketChart(container,{t:key=>({warmupChart:L('No completed candles for this interval.','Ingen fullførte kurspunkter for intervallet.'),event:L('Event','Hendelse'),chart:L('candlestick chart','lysestakegraf'),bars:L('candles','kurspunkter'),lastPrice:L('last price','siste kurs'),chartKeyboard:L('Arrow keys pan. Plus and minus zoom. Data table follows.','Piltaster flytter. Pluss og minus zoomer. Datatabell følger.')})[key]||key,time:terminalTime,date,day:terminalDay});chartViewKey=chartCacheKey();chart.update(market,{timeframe:resolution,indicators:{...chartIndicators}});const saved=chartViews.get(chartViewKey);if(saved)chart.restoreViewState?.(saved);}
function sampleNewsPanel(){const items=sampleState?.news||[];return panel(L('Sample newsroom','Eksempelnyheter'),`<p class="pt-section-note">${L('Fixed fictional stories for the replay. These are not current financial news.','Faste fiktive saker for avspillingen. Dette er ikke aktuelle finansnyheter.')}</p><div class="pt-news-feed">${items.map(item=>`<article><p class="p-source">${L('Fictional sample','Fiktivt eksempel')} · ${date(item.publishedAt)}</p><h3>${esc(item.title)}</h3>${item.summary?`<p>${esc(item.summary)}</p>`:''}<p class="p-meta">${esc((item.symbols||[]).join(' · '))}</p></article>`).join('')||`<div class="pt-empty"><h3>${L('No sample stories at this time','Ingen eksempelsaker på dette tidspunktet')}</h3><p>${L('The replay only shows stories published before its current timestamp.','Avspillingen viser bare saker publisert før gjeldende avspillingstidspunkt.')}</p></div>`}</div>`);}
function sampleCalendarPanel(){return panel(L('Sample event calendar','Eksempelets hendelseskalender'),`<p class="pt-section-note">${L('Fixed fictional events. Times are local; reminders and background updates are disabled.','Faste fiktive hendelser. Tidene er lokale; påminnelser og bakgrunnsoppdateringer er deaktivert.')}</p><div class="p-table-wrap" role="region" tabindex="0" aria-label="${L('Scrollable data table','Rullbar datatabell')}"><table><caption>${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}</caption><thead><tr><th>${L('Time','Tid')}</th><th>${L('Event','Hendelse')}</th><th>${L('Actual','Faktisk')}</th><th>${L('Consensus','Konsensus')}</th><th>${L('Status','Status')}</th></tr></thead><tbody>${(sampleState?.calendar||[]).map(item=>`<tr><td>${date(item.scheduledAt)}</td><th scope="row">${esc(item.title)}<small>${esc(item.country||item.currency||'')}</small></th><td class="number">${esc(item.actual??'—')}</td><td class="number">${esc(item.consensus??'—')}</td><td>${stateLabel(item.status||'scheduled')}</td></tr>`).join('')||`<tr><td colspan="5">${L('No events in this sample','Ingen hendelser i dette eksempelet')}</td></tr>`}</tbody></table></div>`);}
function engineStrategyPanel(){const connection=currentConnection();return panel(L('Strategy & engine','Strategi og handelsmotor'),`<div class="p-actions"><span class="p-status">${connection?.automationEnabled?L('Automation enabled','Automatisering aktivert'):L('Automation stopped','Automatisering stanset')}</span>${status('worker',pro())}</div><ul class="p-list">${strategies.slice(0,4).map(strategy=>`<li><strong>${esc(strategy.name)}</strong><span class="p-meta">${esc(strategy.instrumentId)} · SMA ${strategy.fast}/${strategy.slow} · v${strategy.version} · ${strategy.enabled?L('enabled','aktivert'):L('disabled','deaktivert')}</span>${button(L('Edit strategy','Rediger strategi'),'edit-strategy','',`data-id="${esc(strategy.id)}" ${!pro()?'disabled':''}`)}</li>`).join('')||`<li class="p-meta">${L('Save a supported strategy, bind its account, then review risk and automation consent separately. Signing in never starts the engine.','Lagre en støttet strategi, knytt den til kontoen og gå deretter gjennom risiko og automatiseringssamtykke separat. Innlogging starter aldri handelsmotoren.')}</li>`}</ul><div class="p-actions">${button(L('New strategy','Ny strategi'),'new-strategy','',!pro()?'disabled':'')}${button(L('Enable automation','Aktiver automatisering'),'automation-consent','p-primary',!pro()||!connection||terminalMode==='sample'?'disabled':'')}${button(L('Stop automation','Stans automatisering'),'broker-stop','p-danger',!connection?'disabled':'')}</div><p class="p-source">${L('Execution runs in a separate worker. A running state requires a verified heartbeat. Stop prevents new entries; existing broker orders and protective stops remain active.','Utførelse kjører i en separat bakgrunnsprosess. Kjørende status krever bekreftet livstegn. Stopp hindrer nye innganger; eksisterende meglerordrer og beskyttelsesordrer forblir aktive.')}</p>`);}
function riskConnectionPanel(){const connection=currentConnection(),risk=connection?.risk;return panel(L('Risk & connected account','Risiko og tilkoblet konto'),`<p><strong>${esc(connection?.accountLabel||L('No broker connected','Ingen megler tilkoblet'))}</strong></p><p class="p-source">${connection?`${esc(connection.provider)} · ${esc(connection.mode)} · ${L('Last sync','Sist synkronisert')}: ${date(connection.lastSyncAt)}`:L('Portfolio does not need a broker. Pro can connect supported accounts after authorization.','Portfolio trenger ingen megler. Pro kan koble til støttede kontoer etter godkjenning.')}</p>${risk?`<dl class="p-detail"><div><dt>${L('Maximum order','Maksimal ordre')}</dt><dd>${money(risk.maxOrderNotional)}</dd></div><div><dt>${L('Position exposure','Posisjonseksponering')}</dt><dd>${money(risk.maxPositionNotional)}</dd></div><div><dt>${L('Daily loss limit','Daglig tapsgrense')}</dt><dd>${money(risk.maxDailyLoss)}</dd></div><div><dt>${L('Orders per day','Ordrer per dag')}</dt><dd>${risk.maxOrdersPerDay}</dd></div></dl>`:`<p class="p-notice warning p-inline-note">${L('No account risk limits are confirmed. Risk-increasing execution stays blocked.','Ingen kontorisikogrenser er bekreftet. Utførelse som øker risiko forblir blokkert.')}</p>`}<div class="p-actions">${button(L('Manage connection','Administrer tilkobling'),'broker')}${button(L('Edit risk limits','Endre risikogrenser'),'risk-limits','',!connection?'disabled':'')}${button(L('Authenticator confirmation','Autentiseringsbekreftelse'),'stepup')}</div>${safeWebUrl(connection?.manageUrl||brokerStatus?.manageUrl)?`<a class="p-button" target="_blank" rel="noopener noreferrer" href="${esc(safeWebUrl(connection?.manageUrl||brokerStatus?.manageUrl))}">${L('Manage directly at broker','Administrer direkte hos megleren')}</a>`:''}`);}
function connectionCanTrade(){return !!currentConnection()&&currentConnection().status==='connected'&&(pro()||currentConnection().positions?.length);}
function ordersPanel(){return panel(L('Order intents & broker status','Ordreintensjoner og meglerstatus'),`${orderIntents.length?`<ul class="p-list">${orderIntents.slice(-8).reverse().map(order=>`<li><div class="p-actions"><strong>${order.side==='buy'?L('Buy','Kjøp'):L('Sell','Selg')} ${esc(order.quantity)} ${esc(order.symbol)}</strong><span class="p-status">${stateLabel(order.status)}</span></div><span class="p-meta">${L('Filled','Utført')}: ${esc(order.filledQuantity||'0')} / ${esc(order.quantity)} · ${date(order.createdAt)}<br>${esc(order.reason||'')}</span>${!['filled','canceled','cancelled','rejected','expired','replaced'].includes(order.status)?button(L('Request cancellation','Be om kansellering'),'cancel-order','',`data-id="${esc(order.id)}"`):''}</li>`).join('')}</ul>`:`<p class="p-meta">${L('No order intents recorded. An accepted request is not a fill; the broker determines execution and cancellation status.','Ingen ordreintensjoner registrert. En godkjent forespørsel er ikke en utførelse; megleren avgjør utførelses- og kanselleringsstatus.')}</p>`}<div class="p-actions">${button(L('Refresh orders','Oppdater ordrer'),'refresh-orders')}${button(L('Reduce a position','Reduser en posisjon'),'reduce-order','',!currentConnection()?.positions?.length?'disabled':'')}</div>`);}
async function selectMarket(instrument){terminalSelections[terminalMode]={...instrument};selectedInstrument=instrument;newsSymbol=instrument.symbol;aiAnswer=null;if(terminalMode==='sample'){renderTerminal();return;}marketData=null;renderTerminal();try{const results=await Promise.allSettled([api('product-quotes',{params:{instrumentId:instrument.id,resolution:providerResolution()}}),api('product-news',{params:{symbol:instrument.symbol}})]);if(results[0].status==='fulfilled')marketData=results[0].value;else notify(errorText(results[0].reason));if(results[1].status==='fulfilled')news=results[1].value.items||[];renderTerminal();}catch(error){notify(errorText(error));}}
async function loadTerminalData(){const results=await Promise.allSettled([api('product-broker-status'),api('product-strategy'),api('product-broker-orders'),api('product-watchlist')]);if(results[0].status==='fulfilled')brokerStatus=results[0].value;if(results[1].status==='fulfilled')strategies=results[1].value.strategies||[];if(results[2].status==='fulfilled')orderIntents=results[2].value.intents||[];if(results[3].status==='fulfilled')watchlist=results[3].value.instruments||watchlistFromIds(results[3].value.instrumentIds||[]);await loadContext();if(!selectedInstrument&&watchlist.length)selectedInstrument=watchlist[0];if(selectedInstrument&&terminalMode!=='sample'){try{marketData=await api('product-quotes',{params:{instrumentId:selectedInstrument.id,resolution:providerResolution()}});}catch{marketData=null;}}}
function brokerPage(){const connections=brokerStatus?.connections||snapshot?.broker?.connections||[];showDialog(L('Broker connection & safety','Meglertilkobling og sikkerhet'),`<p class="p-notice warning">${brokerStatus?.liveReleaseEnabled?L('Live trading requires an eligible authorized account, separate order confirmation and enabled risk controls.','Handel med ekte penger krever en kvalifisert godkjent konto, separat ordrebekreftelse og aktiverte risikokontroller.'):L('Live transmission is not released. Only supported paper accounts can be connected after provider approval. Norwegian live eligibility is not verified.','Utførelse med ekte penger er ikke frigitt. Bare støttede papirkontoer kan kobles til etter leverandørgodkjenning. Norsk kvalifikasjon for handel med ekte penger er ikke bekreftet.')}</p><p class="p-inline-note">${L('Broker passwords are never requested. Identity checks, custody and funding remain with your broker. Connecting an account never starts trading.','Vi ber aldri om meglerpassord. Identitetskontroll, oppbevaring og finansiering håndteres av megleren. Tilkobling av konto starter aldri handel.')}</p>${connections.map(connection=>`<section class="p-panel-body"><h3>${esc(connection.accountLabel)} · ${esc(connection.mode)}</h3><p class="p-meta">${stateLabel(connection.status)} · ${L('Last sync','Sist synkronisert')}: ${date(connection.lastSyncAt)}<br>${esc(connection.stoppedReason||'')}</p>${connection.balances?`<dl class="p-detail"><div><dt>${L('Equity','Egenkapital')}</dt><dd>${money(connection.balances.equity,connection.balances.currency)}</dd></div><div><dt>${L('Cash','Kontanter')}</dt><dd>${money(connection.balances.cash,connection.balances.currency)}</dd></div></dl>`:''}${connection.positions?.length?`<div class="p-table-wrap" role="region" tabindex="0" aria-label="${L('Scrollable data table','Rullbar datatabell')}"><table><caption>${L('Broker-synchronized positions · separate from manual holdings','Meglersynkroniserte posisjoner · adskilt fra manuelle beholdninger')}</caption><tbody>${connection.positions.map(position=>`<tr><th>${esc(position.symbol)}</th><td>${decimal(position.quantity)}</td><td>${money(position.marketValue,position.currency)}</td></tr>`).join('')}</tbody></table></div>`:''}<div class="p-actions">${button(L('Sync account','Synkroniser konto'),'broker-sync','',`data-id="${esc(connection.id)}"`)}${button(L('Stop automation','Stans automatisering'),'broker-stop','p-danger',`data-id="${esc(connection.id)}"`)}${button(L('Disconnect','Koble fra'),'broker-disconnect','',`data-id="${esc(connection.id)}"`)}</div>${safeWebUrl(connection.manageUrl)?`<a class="p-button" href="${esc(safeWebUrl(connection.manageUrl))}" target="_blank" rel="noopener noreferrer">${L('Open broker','Åpne megleren')}</a>`:''}</section>`).join('')}<div class="p-actions">${button(L('Connect authorized paper account','Koble til godkjent papirkonto'),'broker-connect','p-primary',`data-mode="paper" ${!pro()?'disabled':''}`)}${brokerStatus?.liveReleaseEnabled&&brokerStatus?.supportedModes?.includes('live')?button(L('Connect eligible live account','Koble til kvalifisert konto for ekte penger'),'broker-connect','',`data-mode="live" ${!pro()?'disabled':''}`):''}${button(L('Confirm authenticator','Bekreft autentiseringsapp'),'stepup','',`data-scope="broker"`)}</div>${status('broker',pro())}`);}
function strategyForm(strategyId=null){const existing=strategies.find(item=>item.id===strategyId),connection=currentConnection();showDialog(existing?L('Edit strategy','Rediger strategi'):L('Create strategy','Opprett strategi'),`<p class="p-muted">${L('A saved strategy does not start automation. Review the account and risk limits in a separate consent step.','En lagret strategi starter ikke automatisering. Se gjennom konto og risikogrenser i et separat samtykketrinn.')}</p><form id="strategy-product-form" class="p-form"><div class="p-fields">${field(L('Name','Navn'),'name',existing?.name||'Daily SMA crossover','text','required maxlength="100"')}<label class="p-field"><span>${L('Instrument','Instrument')}</span><select name="instrumentId" required>${[...watchlist,...(selectedInstrument?[selectedInstrument]:[])].filter((item,index,all)=>all.findIndex(i=>i.id===item.id)===index).map(item=>`<option value="${esc(item.id)}" ${item.id===existing?.instrumentId?'selected':''}>${esc(item.symbol)} · ${esc(item.venue)}</option>`).join('')}</select></label>${field(L('Fast SMA period','Rask SMA-periode'),'fast',existing?.fast||'9','number','min="2" max="199" required')}${field(L('Slow SMA period','Langsom SMA-periode'),'slow',existing?.slow||'20','number','min="3" max="200" required')}${field(L('Whole-share size','Helt antall aksjer'),'quantity',existing?.quantity||'1','text','pattern="[1-9][0-9]*" inputmode="numeric" required')}<label class="p-field"><span>${L('Paper account','Papirkonto')}</span><select name="connectionId"><option value="">${L('Research only, no account','Kun analyse, ingen konto')}</option>${(brokerStatus?.connections||[]).map(item=>`<option value="${esc(item.id)}" ${item.id===(existing?.connectionId||connection?.id)?'selected':''}>${esc(item.accountLabel)}</option>`).join('')}</select></label><label class="p-check"><input type="checkbox" name="enabled" ${existing?.enabled?'checked':''}><span>${L('Enable this saved definition (automation requires separate consent)','Aktiver denne lagrede definisjonen (automatisering krever separat samtykke)')}</span></label></div>${formActions(L('Save validated strategy','Lagre validert strategi'))}</form>`);const id=requestId();bindForm('#strategy-product-form',async(data,form)=>{await api('product-strategy',{method:'POST',body:{requestId:id,...(existing?{strategyId:existing.id}:{}),strategy:{...data,fast:Number(data.fast),slow:Number(data.slow),mode:(brokerStatus?.connections||[]).find(item=>item.id===data.connectionId)?.mode||'paper',enabled:form.elements.enabled.checked}}});await loadTerminalData();closeDialog();renderTerminal();},{scope:dialog});}
function automationConsent(){const connection=currentConnection();if(!connection)return;showDialog(L('Enable account automation','Aktiver kontoautomatisering'),`<p class="p-notice warning">${L('This enables the selected strategy on the selected account after server checks. Review every limit. Existing broker orders remain your responsibility when automation stops.','Dette aktiverer den valgte strategien på den valgte kontoen etter serverkontroller. Gå gjennom hver grense. Eksisterende meglerordrer er fortsatt ditt ansvar når automatiseringen stanser.')}</p><form id="automation-consent-form" class="p-form"><p><strong>${esc(connection.accountLabel)} · ${esc(connection.mode)}</strong></p><label class="p-field"><span>${L('Enabled strategy','Aktivert strategi')}</span><select name="strategyId" required>${strategies.filter(item=>item.enabled&&item.connectionId===connection.id).map(item=>`<option value="${esc(item.id)}">${esc(item.name)} · v${item.version}</option>`).join('')}</select></label><div class="p-fields">${field(L('Maximum order notional (USD)','Maksimalt ordrebeløp (USD)'),'maxOrderNotional',connection.risk?.maxOrderNotional||'','text','inputmode="decimal" required')}${field(L('Maximum position notional (USD)','Maksimalt posisjonsbeløp (USD)'),'maxPositionNotional',connection.risk?.maxPositionNotional||'','text','inputmode="decimal" required')}${field(L('Daily loss limit (USD)','Daglig tapsgrense (USD)'),'maxDailyLoss',connection.risk?.maxDailyLoss||'','text','inputmode="decimal" required')}${field(L('Maximum orders per day','Maksimalt antall ordrer per dag'),'maxOrdersPerDay',connection.risk?.maxOrdersPerDay||'','number','min="1" max="100" required')}</div><label class="p-check"><input type="checkbox" name="consent" required><span>${L('I authorize only this account, saved strategy version and these risk limits. I understand how to stop new entries and manage existing orders directly at the broker.','Jeg godkjenner kun denne kontoen, den lagrede strategiversjonen og disse risikogrensene. Jeg forstår hvordan nye innganger stanses og eksisterende ordrer håndteres direkte hos megleren.')}</span></label>${formActions(L('Enable this automation','Aktiver denne automatiseringen'))}</form>`);const id=requestId();bindForm('#automation-consent-form',async data=>{await api('product-broker-consent',{method:'POST',body:{requestId:id,connectionId:connection.id,strategyId:data.strategyId,automationEnabled:true,...(connection.mode==='live'?{liveConsentConfirmed:true}:{}),risk:{maxOrderNotional:data.maxOrderNotional,maxPositionNotional:data.maxPositionNotional,maxDailyLoss:data.maxDailyLoss,maxOrdersPerDay:Number(data.maxOrdersPerDay)}}});await loadTerminalData();closeDialog();renderTerminal();},{scope:dialog});}

let brokerOrderDraft=null;
function brokerOrder(reduceOnly=false,draft=null){const connection=currentConnection();if(!connection){brokerPage();return;}const selected=draft?.instrumentId||(reduceOnly?null:selectedInstrument?.id);showDialog(reduceOnly?L('Reduce an existing position','Reduser en eksisterende posisjon'):L('Review a broker order','Se gjennom en meglerordre'),`<p class="p-notice warning">${esc(connection.accountLabel)} · <strong>${connection.mode==='live'?L('LIVE BROKERAGE · REAL MONEY','MEGLERHANDEL · EKTE PENGER'):L('PAPER BROKERAGE · SIMULATED MONEY','PAPIRHANDEL · SIMULERTE PENGER')}</strong></p><form id="broker-order-form" class="p-form"><div class="p-fields"><label class="p-field"><span>${L('Instrument','Instrument')}</span><select name="instrumentId" required>${reduceOnly?(connection.positions||[]).map(position=>{const match=position.instrumentId?{id:position.instrumentId,symbol:position.symbol}:watchlist.find(item=>item.symbol===position.symbol)||instrumentResults.find(item=>item.symbol===position.symbol);return match?`<option value="${esc(match.id)}">${esc(position.symbol)} · ${decimal(position.quantity)} ${L('held','eid')}</option>`:'';}).join(''):[...watchlist,...(selectedInstrument?[selectedInstrument]:[])].filter((item,index,all)=>all.findIndex(i=>i.id===item.id)===index).map(item=>`<option value="${esc(item.id)}" ${item.id===selected?'selected':''}>${esc(item.symbol)} · ${esc(item.venue)} · ${esc(item.currency)}</option>`).join('')}</select></label><label class="p-field"><span>${L('Side','Retning')}</span><select name="side">${reduceOnly?'':`<option value="buy" ${draft?.side==='buy'?'selected':''}>${L('Buy','Kjøp')}</option>`}<option value="sell" ${reduceOnly||draft?.side==='sell'?'selected':''}>${L('Sell held shares','Selg eide aksjer')}</option></select></label>${field(L('Whole shares','Helt antall aksjer'),'quantity',draft?.quantity||'','text','pattern="[1-9][0-9]*" inputmode="numeric" required')}<label class="p-field"><span>${L('Order type','Ordretype')}</span><select name="type"><option value="market" ${draft?.type==='market'?'selected':''}>${L('Market','Marked')}</option><option value="limit" ${draft?.type==='limit'?'selected':''}>Limit</option></select></label>${field(L('Limit price (required for limit orders)','Limitkurs (påkrevd for limitordrer)'),'limitPrice',draft?.limitPrice||'','text','inputmode="decimal"')}<label class="p-field"><span>${L('Time in force','Gyldighet')}</span><select name="timeInForce"><option value="day">${L('Day · regular market session','Dag · ordinær markedsøkt')}</option></select></label></div>${reduceOnly?`<p class="p-meta">${L('The server verifies available long holdings and existing sell orders. No new short position is permitted. If the position cannot be verified, manage it directly at the broker.','Serveren kontrollerer tilgjengelige lange beholdninger og eksisterende salgsordrer. Nye shortposisjoner er ikke tillatt. Håndter posisjonen direkte hos megleren hvis den ikke kan bekreftes.')}</p>`:''}${formActions(L('Review all order details','Se gjennom alle ordredetaljer'))}</form>`);bindForm('#broker-order-form',async data=>{if(data.type==='limit'&&!/^\d+(\.\d+)?$/.test(data.limitPrice))throw{code:'INVALID_LIMIT_PRICE',message:L('Enter a positive limit price.','Skriv inn en positiv limitkurs.')};brokerOrderDraft={...data,connectionId:connection.id,reduceOnly};reviewBrokerOrder(connection);},{scope:dialog});}
function reviewBrokerOrder(connection){const draft=brokerOrderDraft,instrument=[...watchlist,...instrumentResults,...(selectedInstrument?[selectedInstrument]:[])].find(item=>item.id===draft.instrumentId)||watchlistFromIds([draft.instrumentId])[0];showDialog(L('Confirm broker order','Bekreft meglerordre'),`<p class="p-notice warning"><strong>${esc(connection.accountLabel)} · ${esc(connection.mode).toUpperCase()}</strong></p><dl class="p-detail"><div><dt>${L('Instrument / venue / currency','Instrument / handelsplass / valuta')}</dt><dd>${esc(instrument?.symbol||draft.instrumentId)} · ${esc(instrument?.venue||'—')} · ${esc(instrument?.currency||'USD')}</dd></div><div><dt>${L('Side / quantity','Retning / antall')}</dt><dd>${draft.side==='buy'?L('Buy','Kjøp'):L('Sell','Selg')} ${decimal(draft.quantity)}</dd></div><div><dt>${L('Order type / conditions','Ordretype / betingelser')}</dt><dd>${esc(draft.type)} ${draft.type==='limit'?money(draft.limitPrice,instrument?.currency||'USD'):L('Market price at execution','Markedspris ved utførelse')}</dd></div><div><dt>${L('Duration','Varighet')}</dt><dd>${L('Day, regular session','Dag, ordinær markedsøkt')}</dd></div><div><dt>${L('Reference quote','Referansekurs')}</dt><dd>${marketData?.quote?.instrumentId===draft.instrumentId?money(marketData.quote.price,marketData.quote.currency)+' · '+date(marketData.quote.asOf):L('Unavailable for this selection','Utilgjengelig for dette valget')}</dd></div><div><dt>${L('Estimated costs','Anslåtte kostnader')}</dt><dd>${L('Broker fees, spread and final price are not confirmed by Nortivo. Review your broker’s schedule.','Meglergebyrer, spread og endelig pris er ikke bekreftet av Nortivo. Se meglerens prisliste.')}</dd></div></dl><p class="p-meta">${L('Submission creates a durable order intent. The broker determines acceptance, rejection, partial fills and final execution. A timeout can mean an unknown outcome; refresh the original intent before retrying.','Innsending oppretter en varig ordreintensjon. Megleren avgjør godkjenning, avvisning, delutførelser og endelig utførelse. Tidsavbrudd kan bety ukjent utfall; oppdater den opprinnelige intensjonen før nytt forsøk.')}</p><form id="broker-order-confirm-form"><label class="p-check"><input type="checkbox" required><span>${L('I confirm this exact account and order.','Jeg bekrefter denne bestemte kontoen og ordren.')}</span></label>${formActions(connection.mode==='live'?L('Submit live order','Send ordre med ekte penger'):L('Submit paper order','Send papirordre'),button(L('Edit order','Rediger ordre'),'edit-broker-order'))}</form>`);const id=requestId();bindForm('#broker-order-confirm-form',async()=>{await api('product-broker-order',{method:'POST',body:{requestId:id,...draft,confirmed:true,...(draft.type==='market'?{limitPrice:undefined}:{})}});await loadTerminalData();closeDialog();renderTerminal();notify(L('Order intent saved. Check its broker-confirmed status.','Ordreintensjonen er lagret. Kontroller den meglerbekreftede statusen.'));},{scope:dialog});}
function backtestForm(){showDialog(L('Backtest a saved strategy','Test en lagret strategi historisk'),`<p class="p-notice warning">${L('Simulation, not live or customer returns. Historical data, missing bars, fees and slippage affect the result.','Simulering, ikke faktisk handel eller kundeavkastning. Historiske data, manglende kurspunkter, gebyrer og prisglidning påvirker resultatet.')}</p><form id="backtest-form" class="p-form"><label class="p-field"><span>${L('Saved strategy','Lagret strategi')}</span><select name="strategyId" required>${strategies.map(strategy=>`<option value="${esc(strategy.id)}">${esc(strategy.name)} · v${strategy.version}</option>`).join('')}</select></label><div class="p-fields">${field(L('Initial simulated cash (USD)','Simulert startkapital (USD)'),'initialCash','10000','number','min="100" max="10000000" step="0.01" required')}${field(L('Fee per fill (USD)','Gebyr per utførelse (USD)'),'fee','1','number','min="0" max="100" step="0.01" required')}${field(L('Slippage (basis points)','Prisglidning (basispunkter)'),'slippageBps','5','number','min="0" max="1000" step="1" required')}</div>${formActions(L('Run simulation','Kjør simulering'))}</form><div id="backtest-results" aria-live="polite"></div>`);const id=requestId();bindForm('#backtest-form',async data=>{const result=await api('product-backtest',{method:'POST',body:{requestId:id,strategyId:data.strategyId,costs:{initialCash:Number(data.initialCash),fee:Number(data.fee),slippageBps:Number(data.slippageBps)}}});el('#backtest-results',dialog).innerHTML=`<hr class="p-separator"><h3>${L('Simulated result','Simulert resultat')}</h3><dl class="p-detail"><div><dt>${L('Starting cash','Startkapital')}</dt><dd>${money(result.initialCash)}</dd></div><div><dt>${L('Ending equity','Sluttverdi')}</dt><dd>${money(result.endingEquity)}</dd></div><div><dt>${L('Simulated return','Simulert avkastning')}</dt><dd>${decimal(result.returnPercent)}%</dd></div><div><dt>${L('Simulated trades','Simulerte handler')}</dt><dd>${Array.isArray(result.trades)?result.trades.length:esc(result.trades)}</dd></div></dl><p class="p-source">${esc(typeof result.source==='object'?result.source.name||result.source.provider:result.source||'')}</p><p class="p-meta">${esc(Array.isArray(result.assumptions)?result.assumptions.join(' '):typeof result.assumptions==='object'?JSON.stringify(result.assumptions):result.assumptions||'')}</p>`;},{scope:dialog});}
function scanForm(){showDialog(L('Scan supported instruments','Skann støttede instrumenter'),`<p class="p-muted">${L('Choose up to eight watchlist instruments. A scan is evidence from completed data, not an order or a forecast.','Velg opptil åtte instrumenter i overvåkingslisten. En skanning er grunnlag fra fullførte data, ikke en ordre eller en prognose.')}</p><form id="scan-form" class="p-form">${watchlist.map(item=>`<label class="p-check"><input type="checkbox" name="instrumentIds" value="${esc(item.id)}"><span>${esc(item.symbol)} · ${esc(item.venue)}</span></label>`).join('')}${formActions(L('Run scan','Kjør skanning'))}</form><div id="scan-results" aria-live="polite"></div>`);const id=requestId();bindForm('#scan-form',async(data,form)=>{const ids=new FormData(form).getAll('instrumentIds');if(!ids.length||ids.length>8)throw{code:'INVALID_SCAN',message:L('Choose one to eight instruments.','Velg ett til åtte instrumenter.')};const result=await api('product-scan',{method:'POST',body:{requestId:id,instrumentIds:ids}});el('#scan-results',dialog).innerHTML=`<hr class="p-separator"><p class="p-meta">${esc(typeof result.definition==='string'?result.definition:JSON.stringify(result.definition))} · ${date(result.asOf)}</p><ul class="p-list">${(result.results||[]).map(item=>`<li><strong>${esc(item.instrumentId)}</strong><span class="p-meta">${item.signal?`${esc(item.signal.signal)} · ${date(item.signal.time)}`:L('Insufficient current history','Utilstrekkelig oppdatert historikk')}</span></li>`).join('')}</ul>`;},{scope:dialog});}
function integrationStatus(){const titles={market:L('Market data','Markedsdata'),news:L('News','Nyheter'),calendar:L('Calendar','Kalender'),broker:L('Brokerage','Megler'),ai:L('AI explanations','KI-forklaringer'),worker:L('Trading engine','Handelsmotor'),strategy:L('Strategy tools','Strategiverktøy'),email:L('Account email','Konto-e-post'),billing:L('Payments','Betalinger')},features={market:'market.read',news:'news.read',calendar:'calendar.read',broker:'broker.connect',ai:isTerminal()?'ai.advanced':'ai.basic',worker:'automation.run'};showDialog(L('Connections','Tilkoblinger'),`<p>${L('Check which services are available and which tools your subscription includes. Account access is shown separately from service availability.','Se hvilke tjenester som er tilgjengelige, og hvilke verktøy abonnementet ditt inkluderer. Kontotilgang vises adskilt fra tjenestens tilgjengelighet.')}</p><ul class="p-list">${Object.entries(snapshot?.readiness||catalog?.readiness||{}).map(([key,state])=>`<li><div class="p-actions"><h3>${titles[key]||esc(key)}</h3><span class="p-status" data-state="${dataState(state)}">${rawStateName(dataState(state))}</span></div><p class="p-meta">${esc(state.provider||L('No provider selected','Ingen leverandør valgt'))}${features[key]?` · ${has(features[key])?L('Included in your plan','Inkludert i abonnementet ditt'):L('Not included in your plan','Ikke inkludert i abonnementet ditt')}`:''}</p>${key==='broker'?button(L('Manage brokerage','Administrer megler'),'broker'):''}<details><summary>${L('Connection details','Tilkoblingsdetaljer')}</summary><dl class="p-detail"><div><dt>${L('Configuration','Oppsett')}</dt><dd>${state.configured?L('Configured','Konfigurert'):L('Pending','Venter')}</dd></div><div><dt>${L('Data permissions','Datatillatelser')}</dt><dd>${state.permissionsReady?L('Confirmed','Bekreftet'):L('Pending','Venter')}</dd></div><div><dt>${L('Last connection check','Siste tilkoblingskontroll')}</dt><dd>${state.reachable===true?L('Successful','Vellykket'):state.reachable===false?L('Failed','Mislyktes'):L('Not checked','Ikke kontrollert')}</dd></div>${state.authorizationRequired?`<div><dt>${L('Account authorization','Kontogodkjenning')}</dt><dd>${state.authorized?L('Approved','Godkjent'):L('Required','Kreves')}</dd></div>`:''}${state.coverage?`<div><dt>${L('Coverage','Dekning')}</dt><dd>${esc(typeof state.coverage==='string'?state.coverage:JSON.stringify(state.coverage))}</dd></div>`:''}</dl></details></li>`).join('')||`<li>${L('Connection status is not available yet.','Tilkoblingsstatus er ikke tilgjengelig ennå.')}</li>`}</ul>${snapshot?.capabilities?.admin?`<details><summary>${L('Owner tools','Eierverktøy')}</summary><div class="p-actions">${button(L('Inspect operational health','Se driftsstatus'),'admin-health')}${button(L('Check provider connections','Kontroller leverandørtilkoblinger'),'admin-probe')}</div></details>`:''}`);}
function fullNews(){showDialog(L('News research','Nyhetsanalyse'),`<p class="p-meta">${L('Search the loaded licensed articles. Selected instrument context','Søk i de innlastede lisensierte artiklene. Valgt instrumentkontekst')}: ${esc(selectedInstrument?.symbol||L('All markets','Alle markeder'))}.</p><div class="p-fields"><label class="p-field"><span>${L('Headline search','Overskriftssøk')}</span><input id="news-loaded-search" type="search" autocomplete="off"></label><label class="p-field"><span>${L('Publisher','Utgiver')}</span><select id="news-publisher"><option value="">${L('All publishers','Alle utgivere')}</option>${[...new Set(news.map(item=>item.source))].map(source=>`<option>${esc(source)}</option>`).join('')}</select></label></div><div id="full-news-results" aria-live="polite"></div>`);const display=()=>{const query=el('#news-loaded-search',dialog).value.trim().toLowerCase(),source=el('#news-publisher',dialog).value,items=news.filter(item=>(!query||item.title.toLowerCase().includes(query))&&(!source||item.source===source));el('#full-news-results',dialog).innerHTML=items.length?`<ul class="p-list">${items.map(item=>`<li><h3>${safeWebUrl(item.url)?`<a href="${esc(safeWebUrl(item.url))}" target="_blank" rel="noopener noreferrer">${esc(item.title)}</a>`:esc(item.title)}</h3><span class="p-meta">${esc(item.source)} · ${date(item.publishedAt)} · ${esc((item.symbols||[]).join(', '))}</span>${item.summary?`<p>${esc(item.summary)}</p>`:''}</li>`).join('')}</ul>`:`<p class="p-notice p-inline-note">${L('No loaded articles match these filters.','Ingen innlastede artikler passer filtrene.')}</p>`;};el('#news-loaded-search',dialog).addEventListener('input',display);el('#news-publisher',dialog).addEventListener('change',display);display();}
function fullCalendar(){showDialog(L('Economic event research','Økonomisk hendelsesanalyse'),`<p class="p-meta">${L('Provider release times use your timezone','Leverandørens publiseringstider bruker tidssonen din')}: ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}. ${L('Missing release values remain unknown.','Manglende publiserte verdier forblir ukjente.')}</p><div class="p-fields"><label class="p-field"><span>${L('Country','Land')}</span><select id="calendar-country"><option value="">${L('All countries','Alle land')}</option>${[...new Set(events.map(item=>item.country))].map(value=>`<option>${esc(value)}</option>`).join('')}</select></label><label class="p-field"><span>${L('Currency','Valuta')}</span><select id="calendar-currency"><option value="">${L('All currencies','Alle valutaer')}</option>${[...new Set(events.map(item=>item.currency).filter(Boolean))].map(value=>`<option>${esc(value)}</option>`).join('')}</select></label><label class="p-field"><span>${L('Importance','Viktighet')}</span><select id="calendar-importance"><option value="">${L('All levels','Alle nivåer')}</option>${[...new Set(events.map(item=>item.importance).filter(Boolean))].map(value=>`<option>${esc(value)}</option>`).join('')}</select></label></div><div id="full-calendar-results" aria-live="polite"></div>${remindersPanel()}`);const display=()=>{const country=el('#calendar-country',dialog).value,currency=el('#calendar-currency',dialog).value,importance=el('#calendar-importance',dialog).value,items=events.filter(item=>(!country||item.country===country)&&(!currency||item.currency===currency)&&(!importance||String(item.importance)===importance));el('#full-calendar-results',dialog).innerHTML=items.length?`<ul class="p-list">${items.map(item=>`<li><h3>${esc(item.title)}</h3><span class="p-meta">${date(item.time)} · ${esc(item.country)} · ${esc(item.currency)} · ${esc(item.importance??'')}</span><dl class="p-detail"><div><dt>${L('Actual','Faktisk')}</dt><dd>${esc(item.actual??'—')} ${esc(item.unit||'')}</dd></div><div><dt>${L('Consensus','Konsensus')}</dt><dd>${esc(item.consensus??'—')}</dd></div><div><dt>${L('Previous','Forrige')}</dt><dd>${esc(item.previous??'—')}</dd></div><div><dt>${L('Revised','Revidert')}</dt><dd>${esc(item.revised??'—')}</dd></div></dl>${safeWebUrl(item.url)?`<a class="p-meta" href="${esc(safeWebUrl(item.url))}" target="_blank" rel="noopener noreferrer">${esc(item.source||L('Original source','Originalkilde'))}</a>`:''}${reminderControls(item)}</li>`).join('')}</ul>`:`<p class="p-notice p-inline-note">${L('No loaded events match these filters.','Ingen innlastede hendelser passer filtrene.')}</p>`;};for(const id of ['calendar-country','calendar-currency','calendar-importance'])el('#'+id,dialog).addEventListener('change',display);display();}
async function exportRecords(legacy=false){let blob;if(legacy){const response=await fetch('/.netlify/functions/terminal?action=export',{credentials:'same-origin'});if(!response.ok){const error=await response.json().catch(()=>({}));throw error.error||{code:'EXPORT_UNAVAILABLE'};}blob=await response.blob();}else{const data=await api('product-portfolio-export',{params:{portfolioId:selectedPortfolioId}});blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});}const url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=legacy?'nortivo-paper-history.csv':'nortivo-portfolio.json';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function renderWorkspace(){if(isTerminal())renderTerminal();else portfolioPage();}
async function changeLanguage(){if(dialog.open)return;const drafts=[...root.querySelectorAll('form[id]')].map(form=>({id:form.id,fields:[...form.elements].filter(control=>control.name).map(control=>({name:control.name,type:control.type,value:control.value,checked:control.checked}))}));const next=locale==='nb'?'en':'nb';locale=next;intent={...intent,locale:next,returnPath:intent.returnPath.replace(/^\/(en|nb)\//,`/${next}/`)};const route=location.pathname.replace(/^\/(?:(?:en|nb)\/)?/,`/${next}/`),query=new URLSearchParams(location.search);query.set('locale',next);if(query.has('returnPath'))query.set('returnPath',intent.returnPath);if(query.has('returnTo'))query.set('returnTo',intent.returnPath);history.replaceState(null,'',route+'?'+query+location.hash);document.documentElement.lang=next;if(surface==='pricing')renderPricing();else if(surface==='auth')authScreen(authMode);else if(surface==='verification')verificationScreen();else if(surface==='account')await accountPage(accountTab);else renderWorkspace();for(const draft of drafts){const form=el('#'+draft.id,root);if(!form)continue;const used=new Set();for(const saved of draft.fields){const control=[...form.elements].find((node,index)=>node.name===saved.name&&node.type===saved.type&&!used.has(index));if(!control)continue;used.add([...form.elements].indexOf(control));if(saved.type==='checkbox'||saved.type==='radio')control.checked=saved.checked;else control.value=saved.value;}if(draft.id==='billing-plan-form')form.dispatchEvent(new Event('change',{bubbles:true}));}el('[data-product="language"]',root)?.focus();if(user()&&snapshot.selectedPlan){try{await post('product-select-plan',intent);}catch(error){notify(errorText(error));}}}
function startQuotePolling(){if(pollTimer||!isTerminal())return;const tick=async()=>{pollTimer=null;if(!document.hidden&&!dialog?.open&&pro()&&terminalMode==='provider'&&selectedInstrument&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){try{const instrumentId=selectedInstrument.id,data=await api('product-quotes',{params:{instrumentId,resolution:providerResolution()}});if(selectedInstrument?.id===instrumentId&&terminalMode==='provider'){marketData=data;const node=el('#product-chart-value');if(node)node.textContent=money(data.quote.price,data.quote.currency);const provenance=el('.chart-provenance',root);if(provenance)provenance.textContent=`${L('As of','Fra')}: ${date(data.quote.asOf)} · ${data.quote.currency} · ${stateLabel(data.quote.freshness)}`;if(chart)chart.update(chartMarket(),{timeframe:resolution,indicators:{...chartIndicators}});const table=el('.chart-data .p-table-wrap',root);if(table)table.innerHTML=chartTable(chartMarket());}pollFailures=0;}catch{pollFailures++;if(pollFailures===1)notify(L('Data refresh failed. The chart retains its timestamped last-known values.','Dataoppdateringen mislyktes. Grafen beholder tidsstemplede sist kjente verdier.'));}}pollTimer=setTimeout(tick,Math.min(120000,30000*2**Math.min(pollFailures,2)));};pollTimer=setTimeout(tick,30000);window.addEventListener('pagehide',()=>{clearTimeout(pollTimer);pollTimer=null;},{once:true});}
async function refreshWorkspace(){if(!user()){renderWorkspace();return;}await refreshSnapshot();if(isTerminal())await loadTerminalData();else{await loadPortfolio();await loadContext();await loadWatchlist();}renderWorkspace();}
function bindEvents(){startQuotePolling();startReminderChecks();document.addEventListener('keydown',event=>{if(!isTerminal()||surface!=='workspace'||dialog?.open||event.ctrlKey||event.metaKey||event.altKey||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(event.key==='/'){event.preventDefault();el('[data-product=terminal-search]',root)?.click();}else if(event.key==='Escape'&&terminalChartExpanded){terminalChartExpanded=false;renderTerminal();}});document.addEventListener('click',async event=>{const target=event.target.closest('[data-product]');if(!target||target.disabled)return;const action=target.dataset.product;if(action==='language'){event.preventDefault();await changeLanguage();return;}if(action==='show-password'){const input=target.previousElementSibling,show=input.type==='password';input.type=show?'text':'password';target.textContent=show?L('Hide','Skjul'):L('Show','Vis');target.setAttribute('aria-pressed',String(show));return;}if(operationBusy)return;operationBusy=true;try{switch(action){case'terminal-entry':terminalMode='provider';selectedInstrument=null;terminalView='overview';renderTerminal();break;case'terminal-view':if(Object.hasOwn(terminalTitles(),target.dataset.view)){terminalView=target.dataset.view;terminalChartExpanded=false;renderTerminal();}break;case'terminal-search':showDialog(L('Find a market','Finn et marked'),`<form id="terminal-search-form" class="p-form"><label class="p-field"><span>${L('Exact symbol or company','Nøyaktig symbol eller selskap')}</span><input id="terminal-instrument-query" type="search" placeholder="${L('Symbol or company name','Symbol eller selskapsnavn')}" autocomplete="off"></label><button type="submit">${L('Search','Søk')}</button><div id="terminal-instrument-results" aria-live="polite"></div></form>`);el('#terminal-search-form',dialog).addEventListener('submit',event=>{event.preventDefault();searchInstruments();});el('#terminal-instrument-query',dialog).focus();break;case'chart-indicator':{const name=target.dataset.indicator;if(Object.hasOwn(chartIndicators,name)){chartIndicators[name]=!chartIndicators[name];renderTerminal();}break;}case'terminal-expand-chart':terminalChartExpanded=!terminalChartExpanded;renderTerminal();break;case'terminal-chart-data':{const details=el('.chart-data',root);if(details){details.open=!details.open;details.scrollIntoView({block:'nearest'});}break;}case'close-dialog':closeDialog();break;case'login':authScreen('login');break;case'signup':authScreen('signup');break;case'forgot':authScreen('forgot');break;case'pricing':location.assign(path('pricing'));break;case'account':await accountPage();break;case'billing':await accountPage('billing');break;case'workspace':renderWorkspace();break;case'logout':await post('logout');snapshot=null;session=null;portfolio=null;summary=null;portfolios=[];watchlist=[];marketData=null;news=[];events=[];brokerStatus=null;strategies=[];orderIntents=[];if(isTerminal()){terminalMode='provider';renderTerminal();}authScreen('login');break;case'verification':verificationScreen();break;case'check-verified':await refreshSnapshot();if(user()?.emailVerified)await continueIntent();else notify(L('Verification has not been confirmed yet. Use the email link first.','Bekreftelse er ikke registrert ennå. Bruk e-postlenken først.'));break;case'resend':await post('product-resend');notify(L('A new verification email has been requested. Check your inbox.','En ny bekreftelsespost er bestilt. Se i innboksen.'));break;case'interval':intent.interval=target.dataset.value;history.replaceState(null,'',location.pathname+'?interval='+intent.interval);renderPricing();break;case'choose-plan':intent={tier:target.dataset.tier,interval:intent.interval,locale,returnPath:path(target.dataset.tier==='pro'?'terminal':'portfolio')};if(user()){await post('product-select-plan',intent);await refreshSnapshot();await accountPage('billing');}else location.assign(hrefIntent('portfolio',canRegister()?'signup':'login',intent));break;case'checkout':await checkout();break;case'portal':{const result=await post('product-portal'),url=safeWebUrl(result.url);if(!url)throw{code:'PORTAL_UNAVAILABLE'};location.assign(url);break;}case'refresh-billing':await post('product-refresh');await refreshSnapshot();if(new URLSearchParams(location.search).get('billing')==='pending'&&paid())history.replaceState(null,'',location.pathname);await refreshWorkspace();notify(L('Subscription status updated.','Abonnementsstatus oppdatert.'));break;case'cancel-plan':confirmCancellation();break;case'resume':await post('product-resume');await refreshSnapshot();accountPage('billing');break;case'sessions':await loadSessions();break;case'revoke-session':case'revoke-all':{const result=await post('product-revoke',action==='revoke-all'?{all:true}:{sessionId:target.dataset.id});if(result.signInRequired){snapshot=null;session=null;authScreen('login');}else await loadSessions();break;}case'mfa-enroll':mfaEnroll();break;case'finish-mfa':closeDialog();await accountPage();break;case'mfa-disable':disableMfa();break;case'stepup':stepUp(target.dataset.scope||'security');break;case'new-portfolio':if(!paid())await accountPage('billing');else newPortfolio();break;case'opening':openLedger('opening_position');break;case'transaction':openLedger('buy');break;case'cash-transaction':openLedger(target.dataset.kind);break;case'trade-transaction':openLedger('buy',null,target.dataset.instrument);break;case'ledger-kind':openLedger(target.dataset.kind,null,target.dataset.instrument);break;case'correct-transaction':openLedger('buy',target.dataset.id);break;case'void-transaction':voidTransaction(target.dataset.id);break;case'valuation':manualValuation(target.dataset.instrument);break;case'portfolio-view':view=target.dataset.view;portfolioPage();break;case'refresh-portfolio':await loadPortfolio();await loadContext();portfolioPage();break;case'export-portfolio':await exportRecords();break;case'export-legacy':await exportRecords(true);break;case'instrument-search':await searchInstruments();break;case'instrument-select':{const instrument=instrumentResults[Number(target.dataset.index)];if(!instrument)break;if(el('#ledger-form',dialog)){const form=el('#ledger-form',dialog);for(const [key,value]of Object.entries({instrumentId:instrument.id,symbol:instrument.symbol,instrumentName:instrument.name,venue:instrument.venue,currency:instrument.currency,assetType:instrument.assetType}))if(form.elements[key])form.elements[key].value=value;selectedInstrument=instrument;el('#instrument-results',dialog).innerHTML=`<p class="p-notice">${L('Selected','Valgt')}: ${esc(instrument.name)} · ${esc(instrument.venue)} · ${esc(instrument.currency)}</p>`;}else if(isTerminal()){if(dialog.open)closeDialog();await selectMarket(instrument);}else{selectedInstrument=instrument;newsSymbol=instrument.symbol;await loadContext();portfolioPage();}break;}case'market-select':{const instrument=terminalMode==='sample'?(sampleState?.catalog||[]).find(item=>item.symbol===target.dataset.instrument):watchlist.find(item=>item.id===target.dataset.instrument);if(instrument)await selectMarket({...instrument,id:instrument.id||instrument.symbol});break;}case'watchlist-add':case'watchlist-remove':if(selectedInstrument||target.dataset.instrument){await post('product-watchlist',{type:action==='watchlist-add'?'add':'remove',instrumentId:target.dataset.instrument||selectedInstrument.id});if(isTerminal()){await loadTerminalData();renderTerminal();}else{await loadWatchlist();portfolioPage();}}break;case'mode-provider':if(selectedInstrument)terminalSelections[terminalMode]={...selectedInstrument};terminalMode='provider';marketData=null;selectedInstrument=terminalSelections.provider||watchlist[0]||null;if(user()){await loadTerminalData();if(terminalSelections.provider&&selectedInstrument?.id!==terminalSelections.provider.id)await selectMarket(terminalSelections.provider);}renderTerminal();break;case'mode-sample':{let result;try{result=await api('session');}catch(error){if(error.status!==401)throw error;result=await post('guest');}session=result;snapshot=result.product||snapshot;sampleState=result.state;if(!sampleState){const again=await api('session');sampleState=again.state;}if(selectedInstrument)terminalSelections[terminalMode]={...selectedInstrument};terminalMode='sample';selectedInstrument=terminalSelections.sample||{...(sampleState.catalog||[])[0],id:(sampleState.catalog||[])[0]?.symbol};renderTerminal();break;}case'product-timeframe':resolution=target.dataset.resolution;if(terminalMode==='sample')renderTerminal();else if(selectedInstrument)await selectMarket(selectedInstrument);else renderTerminal();break;case'integration-status':integrationStatus();break;case'admin-probe':await post('product-health-probe');await refreshSnapshot();integrationStatus();break;case'admin-health':{const health=await api('product-health');showDialog(L('Owner operational health','Driftsstatus for eieren'),`<pre class="p-key">${esc(JSON.stringify(health,null,2))}</pre>`);break;}case'refresh-terminal':await refreshWorkspace();break;case'focus-ai':if(isTerminal()){terminalView='research';renderTerminal();}el('#product-ai-form textarea')?.focus();(el('#product-ai-form')||el('.pt-screen-head',root))?.scrollIntoView({block:'nearest'});break;case'broker':brokerPage();break;case'broker-connect':{const result=await post('product-broker-connect',{mode:target.dataset.mode||'paper'}),url=safeWebUrl(result.authorizationUrl);if(!url)throw{code:'BROKER_AUTHORIZATION_REQUIRED'};location.assign(url);break;}case'broker-sync':await post('product-broker-sync',{connectionId:target.dataset.id||currentConnection()?.id});await loadTerminalData();brokerPage();break;case'broker-stop':await post('product-broker-stop',{connectionId:target.dataset.id||currentConnection()?.id});await loadTerminalData();if(dialog.open)closeDialog();renderTerminal();notify(L('New automated entries stopped. Existing orders and protective stops remain at the broker.','Nye automatiske innganger er stanset. Eksisterende ordrer og beskyttelsesordrer er fortsatt hos megleren.'));break;case'broker-disconnect':disconnectBroker(target.dataset.id);break;case'risk-limits':accountRiskForm();break;case'request-deletion':requestDeletion();break;case'new-strategy':strategyForm();break;case'edit-strategy':strategyForm(target.dataset.id);break;case'automation-consent':automationConsent();break;case'broker-order':brokerOrder(false);break;case'reduce-order':brokerOrder(true);break;case'edit-broker-order':brokerOrder(brokerOrderDraft.reduceOnly,brokerOrderDraft);break;case'cancel-order':cancelBrokerOrder(target.dataset.id);break;case'refresh-orders':{const result=await api('product-broker-orders');orderIntents=result.intents||[];renderTerminal();break;}case'holding-context':{const instrument=(summary?.holdings||[]).find(item=>item.instrument.id===target.dataset.instrument)?.instrument||watchlist.find(item=>item.id===target.dataset.instrument);if(instrument){selectedInstrument=instrument;newsSymbol=instrument.symbol;await loadContext();portfolioPage();}break;}case'reminders-list':showDialog(L('In-app reminders','Påminnelser i appen'),remindersPanel());break;case'news-full':fullNews();break;case'calendar-full':fullCalendar();break;case'add-reminder':await post('product-reminders',{type:'add',eventId:target.dataset.id,leadMinutes:5});await loadReminders();if(dialog.open)fullCalendar();else renderWorkspace();notify(L('Reminder saved. Keep this tab open for in-app delivery.','Påminnelsen er lagret. Hold fanen åpen for varsling i appen.'));break;case'remove-reminder':await post('product-reminders',{type:'remove',eventId:target.dataset.id});await loadReminders();fullCalendar();break;case'backtest':backtestForm();break;case'scan':scanForm();break;case'retry-product':location.reload();break;}}catch(error){const node=el('[data-error]',dialog.open?dialog:root)||el('[data-account-error]');if(node)node.textContent=errorText(error);notify(errorText(error));}finally{operationBusy=false;}});dialog.addEventListener('close',()=>{if(dialog.open)return;if(terminalAuthOpen){terminalAuthOpen=false;surface='workspace';dialog.classList.remove('pt-terminal-auth');}dialog.innerHTML='';if(lastDialogTrigger?.isConnected)lastDialogTrigger.focus();if(isTerminal())mountChart();});}
function disconnectBroker(connectionId){showDialog(L('Disconnect brokerage access?','Koble fra meglertilgangen?'),`<p>${L('This stops new automation and erases Nortivo’s stored access. Existing positions, orders and protective stops remain at the broker. Revoke the app grant directly at the broker as well.','Dette stanser ny automatisering og sletter Nortivos lagrede tilgang. Eksisterende posisjoner, ordrer og beskyttelsesordrer forblir hos megleren. Trekk også tilbake apptilgangen direkte hos megleren.')}</p><form id="disconnect-form">${formActions(L('Disconnect stored access','Koble fra lagret tilgang'))}</form>`);const id=requestId();bindForm('#disconnect-form',async()=>{await api('product-broker-disconnect',{method:'POST',body:{requestId:id,connectionId}});await loadTerminalData();closeDialog();renderTerminal();},{scope:dialog});}
function cancelBrokerOrder(intentId){showDialog(L('Request order cancellation','Be om ordrekansellering'),`<p>${L('The broker may fill an order before cancellation is confirmed. Refresh the original order status. Protective orders are not cancelled automatically by stopping automation.','Megleren kan utføre en ordre før kansellering er bekreftet. Oppdater den opprinnelige ordrestatusen. Beskyttelsesordrer kanselleres ikke automatisk når automatisering stanses.')}</p><form id="cancel-order-form">${formActions(L('Request cancellation','Be om kansellering'))}</form>`);const id=requestId();bindForm('#cancel-order-form',async()=>{await api('product-broker-cancel',{method:'POST',body:{requestId:id,intentId}});await loadTerminalData();closeDialog();renderTerminal();},{scope:dialog});}
function accountRiskForm(){const connection=currentConnection();if(!connection)return;showDialog(L('Account risk limits','Kontorisikogrenser'),`<p><strong>${esc(connection.accountLabel)} · ${esc(connection.mode)}</strong></p><p class="p-muted">${L('Saving limits does not enable automation. New risk-increasing orders are checked against these limits and provider freshness.','Lagring av grenser aktiverer ikke automatisering. Nye ordrer som øker risiko, kontrolleres mot disse grensene og dataenes aktualitet.')}</p><form id="account-risk-form" class="p-form"><div class="p-fields">${field(L('Maximum order notional (USD)','Maksimalt ordrebeløp (USD)'),'maxOrderNotional',connection.risk?.maxOrderNotional||'','text','inputmode="decimal" required')}${field(L('Maximum position notional (USD)','Maksimalt posisjonsbeløp (USD)'),'maxPositionNotional',connection.risk?.maxPositionNotional||'','text','inputmode="decimal" required')}${field(L('Daily loss limit (USD)','Daglig tapsgrense (USD)'),'maxDailyLoss',connection.risk?.maxDailyLoss||'','text','inputmode="decimal" required')}${field(L('Maximum orders per day','Maksimalt antall ordrer per dag'),'maxOrdersPerDay',connection.risk?.maxOrdersPerDay||'','number','min="1" max="100" required')}</div>${formActions(L('Save limits with automation stopped','Lagre grenser med automatisering stanset'))}</form>`);const id=requestId();bindForm('#account-risk-form',async data=>{await api('product-broker-consent',{method:'POST',body:{requestId:id,connectionId:connection.id,automationEnabled:false,risk:{maxOrderNotional:data.maxOrderNotional,maxPositionNotional:data.maxPositionNotional,maxDailyLoss:data.maxDailyLoss,maxOrdersPerDay:Number(data.maxOrdersPerDay)}}});await loadTerminalData();closeDialog();renderTerminal();},{scope:dialog});}
function requestDeletion(){showDialog(L('Request account deletion','Be om kontosletting'),`<p class="p-notice warning">${L('This records a deletion request and stops new risk-increasing access. Billing and broker connections must be resolved before records are deleted. Existing orders and protective stops remain at the broker. Export the records you need first.','Dette registrerer en sletteforespørsel og stanser ny tilgang som øker risiko. Betaling og meglertilkoblinger må håndteres før registreringer slettes. Eksisterende ordrer og beskyttelsesordrer forblir hos megleren. Eksporter registreringene du trenger først.')}</p><form id="deletion-request-form"><label class="p-check"><input type="checkbox" required><span>${L('I want support to resolve my subscription and connections before deleting this account.','Jeg ønsker at kundestøtte håndterer abonnementet og tilkoblingene før kontoen slettes.')}</span></label>${formActions(L('Record deletion request','Registrer sletteforespørselen'))}</form>`);const id=requestId();bindForm('#deletion-request-form',async()=>{await api('product-deletion-request',{method:'POST',body:{requestId:id}});await refreshSnapshot();closeDialog();await accountPage();notify(L('Deletion request recorded. Billing and broker review are required before deletion.','Sletteforespørselen er registrert. Betaling og megler må gjennomgås før sletting.'));},{scope:dialog});}
export async function startProduct(){root=el('#app');if(!root)return false;let enabled=false;try{catalog=await api('product-plans');enabled=catalog.productEnabled===true;}catch(error){if(['PRODUCT_DISABLED','NOT_FOUND'].includes(error.code)&&isTerminal())return false;catalog={productEnabled:false,ready:false};if(error.status!==404){document.body.classList.add('product-app');root.innerHTML=`<main class="p-shell"><section class="p-auth p-panel"><div class="p-panel-body"><h1>${L('The workspace could not connect','Arbeidsområdet kunne ikke koble til')}</h1><p class="p-error">${esc(errorText(error))}</p><button type="button" data-product="retry-product">${L('Refresh page','Oppdater siden')}</button></div></section></main>`;root.querySelector('[data-product=retry-product]')?.addEventListener('click',()=>location.reload());return true;}}if(!enabled&&isTerminal())return false;document.body.classList.add('product-app');root.classList.add('product-app');dialog=document.createElement('dialog');dialog.className='p-dialog';document.body.append(dialog);bindEvents();try{session=await api('session');snapshot=session.product||await api('product');}catch(error){if(error.status!==401)notify(errorText(error));session=null;snapshot=null;}const fragment=new URLSearchParams(location.hash.slice(1));if(fragment.has('verify')||fragment.has('reset')){const kind=fragment.has('verify')?'verify':'reset';callback={kind,token:fragment.get(kind)};history.replaceState(null,'',location.pathname+location.search);authScreen(kind);return true;}if(/\/pricing\//.test(location.pathname)){renderPricing();return true;}if(new URLSearchParams(location.search).has('auth')){if(user()?.emailVerified)await continueIntent();else authScreen(new URLSearchParams(location.search).get('auth')==='signup'?'signup':'login');return true;}if(user()){try{await loadPortfolio();if(isTerminal())await loadTerminalData();else{await loadContext();await loadWatchlist();}}catch(error){notify(errorText(error));}}renderWorkspace();if(isTerminal())void loadTerminalReport();if(new URLSearchParams(location.search).get('billing')==='pending'&&user()){let checks=0;const timer=setInterval(async()=>{if(++checks>6||document.hidden){clearInterval(timer);return;}try{await post('product-refresh');await refreshSnapshot();if(paid()){clearInterval(timer);history.replaceState(null,'',location.pathname);await refreshWorkspace();}}catch{clearInterval(timer);}},5000);}return true;}

function productSwitcher(active){return `<details class="pt-system"><summary>${active==='terminal'?'Terminal Pro':L('Portfolio','Portefølje')} ${terminalIcon('chevron-down')}</summary><nav aria-label="${L('Nortivo products','Nortivo-produkter')}"><a href="${path('portfolio')}" ${active==='portfolio'?'aria-current="page"':''}>${L('Portfolio','Portefølje')}</a><a href="${path('terminal')}" ${active==='terminal'?'aria-current="page"':''}>Terminal Pro</a><a href="${path('pricing')}">${L('Plans & pricing','Abonnementer og priser')}</a><a href="/${locale}/support/">${L('Support','Kundestøtte')}</a>${button(locale==='nb'?'English':'Norsk','language')}</nav></details>`;}

function destroyChart(){if(chart){const state=chart.getViewState?.();if(state&&chartViewKey)chartViews.set(chartViewKey,state);chart.destroy();chart=null;}chartViewKey=null;}

function chartCacheKey(){return `${terminalMode}|${selectedInstrument?.id||selectedInstrument?.symbol||''}|${resolution}`;}

function terminalAccountSummary(){const sample=terminalMode==='sample',c=currentConnection(),a=sampleState?.account,b=c?.balances;return `<div class="pt-account-summary pt-context"><span><span class="muted">${sample?L('Sample account','Eksempelkonto'):L('Account','Konto')}</span> <strong>${sample&&a?money(String(a.equityMinor/100),'USD'):b?.equity!==undefined?money(b.equity,b.currency):esc(c?.accountLabel||L('Not connected','Ikke tilkoblet'))}</strong></span>${selectedInstrument?`<span><strong>${esc(selectedInstrument.symbol)}</strong> <span class="muted">${esc(selectedInstrument.venue||'')} · ${esc(selectedInstrument.currency||'USD')} · ${resolution}</span></span>`:''}<span class="muted">${sample?`${L('Fixed replay','Fast avspilling')} · ${date(sampleState?.replay?.asOf)}`:c?`${L('Last sync','Sist synkronisert')} · ${date(c.lastSyncAt)}`:L('Connect an account to see balances','Koble til en konto for å se saldoer')}</span></div>`;}

function terminalScreen(title,description,body,actions=''){return `<div class="pt-page"><header class="pt-screen-head"><div><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="pt-screen-actions">${actions}</div>`:''}</header>${body}</div>`;}

function terminalResearchContext(){const sample=terminalMode==='sample',m=chartMarket(),q=sample?m?.quote:marketData?.quote,s=sample?[...(sampleState?.signals||[])].reverse().find(item=>item.symbol===selectedInstrument?.symbol):null;return panel(L('Research context','Analysegrunnlag'),`<dl class="p-detail"><div><dt>${L('Instrument','Instrument')}</dt><dd>${esc(selectedInstrument?.symbol||L('None selected','Ingen valgt'))}</dd></div><div><dt>${L('Interval','Intervall')}</dt><dd>${resolution}</dd></div><div><dt>${L('Source','Kilde')}</dt><dd>${sample?L('Fictional sample replay','Fiktiv eksempelavspilling'):esc(marketData?.source||L('Not available','Ikke tilgjengelig'))}</dd></div><div><dt>${L('As of','Fra')}</dt><dd>${date(q?.asOf)}</dd></div></dl>${s?`<p>${L('The recorded signal contains rule evidence for this instrument. It is separate from an AI explanation.','Det registrerte signalet inneholder regelgrunnlag for dette instrumentet. Det er adskilt fra en KI-forklaring.')}</p>`:`<p class="p-meta">${L('No evaluated signal is available for this instrument. A chart alone does not establish an entry, price target or forecast.','Ingen vurderte signaler finnes for dette instrumentet. En graf alene gir ikke en inngang, et kursmål eller en prognose.')}</p>`}`);}

function terminalPositionsPanel(sample=false){const positions=sample?sampleState?.positions||[]:currentConnection()?.positions||[];return panel(sample?L('Virtual positions','Virtuelle posisjoner'):L('Broker positions','Meglerposisjoner'),positions.length?`<div class="p-table-wrap" role="region" tabindex="0" aria-label="${L('Scrollable data table','Rullbar datatabell')}"><table><caption>${sample?L('Sample account · USD','Eksempelkonto · USD'):L('Latest broker-synchronized positions','Sist synkroniserte meglerposisjoner')}</caption><thead><tr><th>${L('Instrument','Instrument')}</th><th>${L('Quantity','Antall')}</th><th>${L('Value','Verdi')}</th><th>${L('Unrealized P&L','Urealisert resultat')}</th></tr></thead><tbody>${positions.map(p=>`<tr><th scope="row">${esc(p.symbol||p.instrumentId||'—')}</th><td class="number">${decimal(p.quantity)}</td><td class="number">${sample?money(String(p.marketValueMinor/100),'USD'):money(p.marketValue,p.currency||currentConnection()?.balances?.currency||'USD')}</td><td class="number">${sample?money(String(p.unrealizedPnlMinor/100),'USD'):money(p.unrealizedPnl,p.currency||currentConnection()?.balances?.currency||'USD')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="pt-empty"><h3>${L('No positions to display','Ingen posisjoner å vise')}</h3><p>${sample?L('This replay snapshot contains no open virtual positions.','Dette avspillingsbildet inneholder ingen åpne virtuelle posisjoner.'):L('Connected broker positions appear after synchronization. Your manual portfolio is available separately.','Tilkoblede meglerposisjoner vises etter synkronisering. Den manuelle porteføljen er tilgjengelig separat.')}</p></div>`);}

function terminalStrategiesPanel(){return panel(L('Saved strategies','Lagrede strategier'),`<p class="p-meta">${L('Define the instrument, rule periods and order size. Saving a strategy does not start a bot.','Angi instrument, regelperioder og ordrestørrelse. Lagring av en strategi starter ikke en robot.')}</p>${strategies.length?`<ul class="p-list">${strategies.map(s=>`<li><div class="p-actions"><strong>${esc(s.name)}</strong><span class="p-status">${s.enabled?L('Enabled','Aktivert'):L('Disabled','Deaktivert')}</span></div><dl class="p-detail"><div><dt>${L('Instrument','Instrument')}</dt><dd>${esc(s.instrumentId)}</dd></div><div><dt>${L('Rule','Regel')}</dt><dd>SMA ${esc(s.fast)} / ${esc(s.slow)}</dd></div><div><dt>${L('Version','Versjon')}</dt><dd>${esc(s.version)}</dd></div></dl>${button(L('Edit strategy','Rediger strategi'),'edit-strategy','',`data-id="${esc(s.id)}" ${!pro()?'disabled':''}`)}</li>`).join('')}</ul>`:`<div class="pt-empty"><h3>${L('Define your first strategy','Definer den første strategien din')}</h3><p>${L('Start with a supported moving-average rule, then use Research to test its assumptions.','Start med en støttet regel for glidende gjennomsnitt, og bruk Analyse til å teste forutsetningene.')}</p></div>`}<div class="p-actions">${button(L('New strategy','Ny strategi'),'new-strategy','p-primary',!pro()?'disabled':'')}${terminalButton(L('Open Research','Åpne Analyse'),'terminal-view','file-search','',`data-view="research"`)}</div>`);}

function terminalAnalyticsPanel(sample=false){const a=sample?sampleState?.account:null,closed=sample?sampleState?.closedTrades||[]:[],metrics=sample?[[L('Closed trades','Lukkede handler'),decimal(a?.completedTrades??0)],[L('Win rate','Treffprosent'),a?.winRate==null?'—':`${decimal(a.winRate)}%`],[L('Profit factor','Profittfaktor'),a?.profitFactor==null?'—':decimal(a.profitFactor)],[L('Gross realized profit','Brutto realisert gevinst'),a?money(String(a.grossProfitMinor/100),'USD'):'—'],[L('Gross realized loss','Brutto realisert tap'),a?money(String(a.grossLossMinor/100),'USD'):'—']]:[];return panel(L('Account performance','Kontoresultater'),sample?`<dl class="p-detail">${metrics.map(([label,value])=>`<div><dt>${label}</dt><dd class="number">${value}</dd></div>`).join('')}</dl><p class="p-source">${L('Sample account only','Kun eksempelkonto')} · ${date(a?.metricPeriod?.from)} – ${date(a?.metricPeriod?.to)}</p>${closed.length?`<div class="p-table-wrap" role="region" tabindex="0" aria-label="${L('Scrollable data table','Rullbar datatabell')}"><table><caption>${L('Closed virtual lots','Lukkede virtuelle poster')}</caption><thead><tr><th>${L('Instrument','Instrument')}</th><th>${L('Net result · USD','Nettoresultat · USD')}</th></tr></thead><tbody>${closed.map(t=>`<tr><th scope="row">${esc(t.symbol||'—')}</th><td class="number">${money(String(t.pnlMinor/100),'USD')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="pt-empty"><h3>${L('No closed trades in this replay','Ingen lukkede handler i avspillingen')}</h3><p>${L('Win rate and profit factor remain unavailable until there are enough completed trades.','Treffprosent og profittfaktor forblir utilgjengelige til det finnes nok fullførte handler.')}</p></div>`}<details><summary>${L('Metric definitions','Definisjoner')}</summary><p>${L('Win rate measures profitable closed lots after allocated fees. Profit factor compares total closed-lot profit with total closed-lot loss. Open positions and company history are excluded.','Treffprosent måler lønnsomme lukkede poster etter fordelte gebyrer. Profittfaktor sammenligner samlet gevinst med samlet tap i lukkede poster. Åpne posisjoner og selskapshistorikk er utelatt.')}</p></details>`:`<div class="pt-empty"><h3>${L('A balance is not a performance history','En saldo er ikke en resultathistorikk')}</h3><p>${L('A reconciled broker return series is not available here yet. We do not estimate win rate, drawdown or returns from a current balance.','En avstemt resultatserie fra megleren finnes ikke her ennå. Treffprosent, verdifall og avkastning anslås ikke fra en nåværende saldo.')}</p><div class="p-actions">${button(L('View connection','Se tilkobling'),'broker')}<a class="p-button" href="${path('portfolio')}">${L('Recorded portfolio history','Registrert porteføljehistorikk')}</a></div></div>`);}

function terminalRecordsPanel(sample=false){return panel(L('Your records','Registreringene dine'),`<p>${sample?L('This sample account uses virtual USD balances and fixed fictional prices. Its records are separate from Nortivo’s historical NOK report.','Denne eksempelkontoen bruker virtuelle USD-saldoer og faste fiktive kurser. Registreringene er adskilt fra Nortivos historiske NOK-rapport.'):L('Manual portfolio records, broker activity and Nortivo’s company report are kept separately. Choose the record you need.','Manuelle porteføljeregistreringer, megleraktivitet og Nortivos selskapsrapport holdes adskilt. Velg registreringen du trenger.')}</p><ul class="p-list">${sample?`<li><strong>${L('Replay snapshot','Avspillingsbilde')}</strong><span class="p-meta">${date(sampleState?.replay?.asOf)} · ${L('Read-only virtual account','Skrivebeskyttet virtuell konto')}</span></li><li><strong>${L('Recorded fills','Registrerte utførelser')}</strong><span class="number">${sampleState?.fills?.length??0}</span></li>`:`<li><a href="${path('portfolio')}">${L('Manual portfolio ledger & export','Manuell porteføljehistorikk og eksport')}</a><span class="p-meta">${L('Holdings, cash movements and dated observations.','Beholdninger, kontantbevegelser og daterte observasjoner.')}</span></li><li>${terminalButton(L('Broker order history','Meglerens ordrehistorikk'),'terminal-view','list','',`data-view="trade"`)}<span class="p-meta">${L('Requests and their latest execution status.','Forespørsler og deres siste utførelsesstatus.')}</span></li><li>${button(L('Export legacy paper history','Eksporter tidligere papirhistorikk'),'export-legacy')}<span class="p-meta">${L('Earlier virtual trading records, if available.','Tidligere registreringer av virtuell handel, hvis tilgjengelig.')}</span></li>`}</ul>`);}

function terminalSampleStrategyPanel(){const s=sampleState?.strategy;return panel(L('Example strategy rules','Eksempelets strategiregler'),s?`<dl class="p-detail"><div><dt>${L('Rule','Regel')}</dt><dd>EMA ${esc(s.fastPeriod??s.fast??'—')} / ${esc(s.slowPeriod??s.slow??'—')}</dd></div><div><dt>${L('Quantity','Antall')}</dt><dd>${decimal(s.quantity)}</dd></div><div><dt>${L('Instrument','Instrument')}</dt><dd>${esc(sampleState?.settings?.selectedSymbol||selectedInstrument?.symbol||'—')}</dd></div></dl><p>${L('The example evaluates a long-only EMA trend rule on completed one-minute candles. Optional VWAP and volume conditions belong to the replay rules. This read-only view does not evaluate a new signal.','Eksempelet vurderer en EMA-trendregel med kun kjøp på fullførte ettminuttskurser. Valgfrie VWAP- og volumvilkår tilhører avspillingsreglene. Denne skrivebeskyttede visningen vurderer ikke et nytt signal.')}</p><details><summary>${L('Rule details','Regeldetaljer')}</summary><p>${esc(s.description||'')}</p></details>`:L('No strategy rules are available in this snapshot.','Ingen strategiregler finnes i dette bildet.'));}

function sampleOrdersTable(){const orders=sampleState?.orders||[];return orders.length?`<div class="p-table-wrap" role="region" tabindex="0" aria-label="${L('Scrollable data table','Rullbar datatabell')}"><table><thead><tr><th>${L('Instrument / side','Instrument / retning')}</th><th>${L('Quantity','Antall')}</th><th>${L('Status','Status')}</th></tr></thead><tbody>${orders.map(o=>`<tr><th>${esc(o.symbol)}<small>${o.side==='buy'?L('Buy','Kjøp'):L('Sell','Selg')}</small></th><td class="number">${decimal(o.quantity)}</td><td>${stateLabel(o.status)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="pt-empty"><h3>${L('No sample orders recorded','Ingen eksempelordrer registrert')}</h3><p>${L('There are no orders at this replay timestamp. Trade entry and cancellation are disabled in this sample.','Det finnes ingen ordrer ved dette avspillingstidspunktet. Ordreinngang og kansellering er deaktivert i eksempelet.')}</p></div>`;}

function accountWorkspace(){const current=location.pathname;if(/\/terminal\//.test(current))return 'terminal';if(/\/portfolio\//.test(current))return 'portfolio';const target=internalPath(intent.returnPath,snapshot?.onboarding?.returnPath||path('portfolio'));return /\/terminal\//.test(target)?'terminal':'portfolio';}
